export default "<!DOCTYPE html>\n<html lang=\"en\" data-heymia-ui=\"4.5.1\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>HeyMia | Workflow Command Center</title>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js\"></script>\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;0,700;1,400&display=swap\" rel=\"stylesheet\">\n<style>\n:root { --bg:#07060a; --panel:rgba(18,16,26,0.88); --accent:#ec4899; }\nbody { font-family:'Plus Jakarta Sans',sans-serif; background:var(--bg); color:#f8fafc; height:100vh; overflow:hidden; }\n.serif { font-family:'Playfair Display',serif; }\n.glass { background:var(--panel); backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px); border:1px solid rgba(255,255,255,0.08); }\n.glass-light { background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.1); }\n::-webkit-scrollbar { width:4px; height:4px; }\n::-webkit-scrollbar-thumb { background:rgba(255,255,255,0.15); border-radius:4px; }\n.drop-zone.dragover { border-color:#ec4899 !important; background:rgba(236,72,153,0.12) !important; }\n.msg-user { background:rgba(236,72,153,0.18); border:1px solid rgba(236,72,153,0.3); }\n.msg-mia { background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); }\n.tab-active { background:linear-gradient(90deg,#ec4899,#a855f7); color:white; }\n.preview-empty { background:radial-gradient(circle at center,#1e1b4b 0%,#07060a 70%); }\n@keyframes fadeIn { from{opacity:0;transform:translateY(6px)} to{opacity:1;transform:translateY(0)} }\n.fade-in { animation:fadeIn .3s ease forwards; }\n.resize-handle { width:8px; cursor:col-resize; flex-shrink:0; background:rgba(255,255,255,0.08); position:relative; z-index:20; }\n.resize-handle:hover, .resize-handle.dragging { background:rgba(236,72,153,0.65); }\n#mia-aside, #vault-cats, #vault-preview { min-width:160px; max-width:55vw; }\n#vault-preview { z-index: 15; background: var(--panel); }\n#tool-projects { padding-right: 1.25rem; }\n[id^=\"tool-\"].hidden { display: none !important; }\n</style>\n</head>\n<body class=\"flex flex-col h-screen\">\n\n<!-- TOP BAR: Brand + Global Search + Mode -->\n<header class=\"h-14 flex items-center gap-4 px-4 lg:px-6 glass border-b border-white/10 z-40 shrink-0\">\n  <div class=\"flex items-center gap-2.5 shrink-0\">\n    <div class=\"w-9 h-9 rounded-xl bg-gradient-to-tr from-pink-500 to-purple-600 flex items-center justify-center font-black text-white text-lg shadow-lg shadow-pink-500/30\">H</div>\n    <div class=\"hidden sm:block\">\n      <div class=\"font-bold text-sm leading-none serif\">HeyMia</div>\n      <div class=\"text-[9px] text-pink-400 font-semibold tracking-wider uppercase\">Workflow</div>\n    </div>\n  </div>\n\n  <!-- Global Search Engine -->\n  <div class=\"flex-1 max-w-2xl relative\">\n    <svg class=\"absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z\"/></svg>\n    <input id=\"global-search\" type=\"text\" placeholder=\"Search files, scripts, businesses, deployments...\" \n      class=\"w-full bg-white/5 border border-white/10 rounded-xl pl-10 pr-4 py-2 text-sm focus:outline-none focus:border-pink-500/60 transition\"\n      oninput=\"runGlobalSearch(this.value)\"\n      onkeydown=\"globalSearchKey(event)\"\n      autocomplete=\"off\">\n    <div id=\"search-results\" class=\"absolute top-full left-0 right-0 mt-1 glass rounded-xl border border-white/10 shadow-2xl max-h-72 overflow-y-auto hidden z-50\"></div>\n  </div>\n\n  <div class=\"flex items-center gap-2 shrink-0\">\n    <button id=\"build-badge\" onclick=\"openPublish()\" title=\"Live build — click to open Publish\" class=\"px-2.5 py-1.5 rounded-lg glass-light text-[10px] font-bold text-slate-300\">Build: …</button>\n    <button onclick=\"switchMode('work')\" id=\"btn-mode-work\" class=\"px-3 py-1.5 rounded-lg text-xs font-bold tab-active\">Work</button>\n    <button onclick=\"switchMode('play')\" id=\"btn-mode-play\" class=\"px-3 py-1.5 rounded-lg text-xs font-bold glass-light text-slate-300\">Play</button>\n    <button onclick=\"openLiveAvatar()\" class=\"px-3 py-1.5 rounded-lg bg-emerald-600/80 hover:bg-emerald-500 text-xs font-bold flex items-center gap-1.5\">\n      <span class=\"w-1.5 h-1.5 rounded-full bg-white animate-pulse\"></span> Live Avatar\n    </button>\n    <button onclick=\"toggleSettings()\" class=\"p-2 rounded-lg glass-light hover:bg-white/10 text-slate-300\" title=\"Settings & Gemini Key\">\n      <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z\"/><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 12a3 3 0 11-6 0 3 3 0 016 0z\"/></svg>\n    </button>\n  </div>\n</header>\n<div id=\"deploy-result\" class=\"hidden shrink-0 px-4 py-2.5 text-xs font-bold border-b\"></div>\n\n<!-- MAIN SPLIT -->\n<div class=\"flex-1 flex overflow-hidden\">\n\n  <!-- LEFT: Mia Agent Chat + Upload -->\n  <aside id=\"mia-aside\" class=\"flex flex-col glass border-r border-white/10 shrink-0\" style=\"width:22rem\">\n    <div class=\"p-3 border-b border-white/10 space-y-2\">\n      <div class=\"flex items-center justify-between\">\n        <div class=\"flex items-center gap-2\">\n          <div class=\"w-7 h-7 rounded-lg bg-gradient-to-tr from-pink-500 to-purple-500 flex items-center justify-center text-xs font-bold\">M</div>\n          <div>\n            <div class=\"text-xs font-bold\">Mia Agent</div>\n            <div class=\"text-[9px] text-emerald-400 flex items-center gap-1\"><span class=\"w-1.5 h-1.5 rounded-full bg-emerald-400\"></span> Online</div>\n          </div>\n        </div>\n        <button onclick=\"clearChat()\" class=\"text-[10px] text-slate-500 hover:text-slate-300\">Clear</button>\n      </div>\n      <div class=\"flex flex-wrap gap-1\">\n        <button type=\"button\" onclick=\"setMiaMode('plain')\" data-mode=\"plain\" class=\"mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold tab-active\">Plain</button>\n        <button type=\"button\" onclick=\"setMiaMode('soft')\" data-mode=\"soft\" class=\"mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300\">Soft</button>\n        <button type=\"button\" onclick=\"setMiaMode('build')\" data-mode=\"build\" class=\"mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300\">Build</button>\n        <button type=\"button\" onclick=\"setMiaMode('grok')\" data-mode=\"grok\" class=\"mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300\">Grok</button>\n      </div>\n      <div class=\"flex flex-wrap gap-1\">\n        <button type=\"button\" onclick=\"toggleSkill('vault')\" data-skill=\"vault\" class=\"mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-pink-300\">Vault</button>\n        <button type=\"button\" onclick=\"toggleSkill('api')\" data-skill=\"api\" class=\"mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400\">API</button>\n        <button type=\"button\" onclick=\"toggleSkill('deploy')\" data-skill=\"deploy\" class=\"mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400\">Deploy</button>\n        <button type=\"button\" onclick=\"toggleSkill('github')\" data-skill=\"github\" class=\"mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400\">GitHub</button>\n        <button type=\"button\" onclick=\"switchTool('knowledge')\" class=\"px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400\">Knowledge</button>\n      </div>\n    </div>\n\n    <!-- Chat messages -->\n    <div id=\"mia-chat\" class=\"flex-1 overflow-y-auto p-3 space-y-3 text-xs\">\n      <div class=\"msg-mia rounded-2xl rounded-tl-sm p-3 fade-in\">\n        <div class=\"font-bold text-pink-400 text-[10px] mb-1\">Mia</div>\n        Ready when you are. Say what you actually need — I'll pick it up from there.\n      </div>\n    </div>\n\n    <!-- Upload zone - prominent -->\n    <div class=\"p-3 border-t border-white/10 space-y-2\">\n      <div id=\"drop-zone\" class=\"drop-zone border-2 border-dashed border-pink-500/30 rounded-xl p-5 text-center cursor-pointer hover:border-pink-500 hover:bg-pink-500/5 transition group\">\n        <div class=\"w-10 h-10 mx-auto mb-2 rounded-full bg-pink-500/20 flex items-center justify-center group-hover:bg-pink-500/30 transition\">\n          <svg class=\"w-5 h-5 text-pink-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12\"/></svg>\n        </div>\n        <p class=\"text-xs font-bold text-white\">Upload Files</p>\n        <p class=\"text-[10px] text-slate-400 mt-1\">Drag & drop or click • Multiple files supported</p>\n        <p class=\"text-[9px] text-pink-400/80 mt-1\">Mia auto-categorises & routes to LiveAvatar / ElevenLabs</p>\n        <input type=\"file\" id=\"file-input\" multiple class=\"hidden\" accept=\"*/*\">\n      </div>\n      <div id=\"upload-status\" class=\"text-[10px] text-center text-slate-500 hidden\"></div>\n      <div id=\"voice-live\" class=\"hidden text-[10px] text-pink-300 px-1 mb-1 min-h-[14px]\"></div>\n      <form id=\"chat-form\" onsubmit=\"sendToMia(event)\" class=\"flex gap-2 items-center\">\n        <button type=\"button\" id=\"btn-mic\" onclick=\"toggleVoiceInput()\" title=\"Speak to Mia\"\n          class=\"p-2 rounded-xl glass-light hover:bg-pink-500/20 text-slate-300 shrink-0\">\n          <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z\"/></svg>\n        </button>\n        <input id=\"mia-input\" type=\"text\" placeholder=\"Tell Mia or tap mic…\" \n          class=\"flex-1 bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs focus:outline-none focus:border-pink-500\">\n        <button type=\"button\" id=\"btn-voice-reply\" onclick=\"toggleAutoVoice()\" title=\"Mia speaks replies\"\n          class=\"p-2 rounded-xl glass-light text-[10px] font-bold text-slate-400 shrink-0\">🔊</button>\n        <button type=\"submit\" class=\"px-3 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold shrink-0\">Send</button>\n      </form>\n      <button type=\"button\" onclick=\"showPhoneLink()\" class=\"w-full text-[10px] text-slate-500 hover:text-pink-400 mt-1\">Phone: open this site on your mobile</button>\n    </div>\n  </aside>\n  <div class=\"resize-handle\" data-resize=\"mia\" title=\"Drag to resize\"></div>\n\n  <!-- RIGHT: Tools / Preview / Studio -->\n  <main class=\"flex-1 flex flex-col overflow-hidden relative\">\n    <!-- Tool tabs -->\n    <div class=\"h-11 flex items-center gap-1 px-4 border-b border-white/10 glass shrink-0 overflow-x-auto\">\n      <button onclick=\"switchTool('projects')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium tab-active shrink-0\" data-tool=\"projects\">Projects</button>\n      <button onclick=\"switchTool('vault')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"vault\">File Vault</button>\n      <button onclick=\"switchTool('workflow')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"workflow\">Workflow</button>\n      <button onclick=\"switchTool('checklist')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"checklist\">Checklist</button>\n      <button onclick=\"switchTool('training')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"training\">Daily Training</button>\n      <button onclick=\"switchTool('editor')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"editor\">Marketing</button>\n      <button onclick=\"switchTool('cut')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"cut\">Cut</button>\n      <button onclick=\"switchTool('cinema')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"cinema\">Cinema</button>\n      <button onclick=\"switchTool('clips')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"clips\">Clips</button>\n      <button onclick=\"switchTool('replace')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"replace\">Find & Replace</button>\n      <button onclick=\"switchTool('deploy')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"deploy\">Deploy</button>\n      <button onclick=\"switchTool('sites')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"sites\">Sites</button>\n      <button onclick=\"switchTool('pentad')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"pentad\">5D Pentad</button>\n      <button onclick=\"switchTool('dedupe')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"dedupe\">Dedupe</button>\n      <button onclick=\"switchTool('api')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"api\">API</button>\n      <button onclick=\"switchTool('shell')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"shell\">Shell</button>\n      <button onclick=\"switchTool('github')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"github\">GitHub</button>\n      <button onclick=\"switchTool('knowledge')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"knowledge\">Knowledge</button>\n      <button onclick=\"switchTool('trainer')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"trainer\">Trainer AI</button>\n      <button onclick=\"switchTool('studio')\" class=\"tool-tab px-3 py-1.5 rounded-lg text-xs font-medium glass-light text-slate-300 shrink-0\" data-tool=\"studio\">Fan Studio</button>\n    </div>\n\n    <!-- Tool panels -->\n    <div class=\"flex-1 overflow-hidden relative\">\n\n      <div id=\"tool-projects\" class=\"absolute inset-0 overflow-y-auto overflow-x-hidden p-4\">\n        <div class=\"w-full max-w-4xl\">\n          <div class=\"flex flex-col gap-3 mb-4 sm:flex-row sm:items-start sm:justify-between\">\n            <div class=\"min-w-0\">\n              <h2 class=\"text-lg font-bold serif leading-tight\">Projects</h2>\n              <p class=\"text-[11px] text-slate-400 mt-1 leading-snug\">Tap a card to open files. Drag the pink bars to resize panels.</p>\n            </div>\n            <button onclick=\"seedProductsNow()\" class=\"shrink-0 px-3 py-2 rounded-xl bg-pink-600 text-xs font-bold whitespace-nowrap\">Refresh folders</button>\n          </div>\n          <div id=\"product-grid\" class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 pb-16\"></div>\n          <div id=\"product-files\" class=\"mt-4 hidden pb-16\"></div>\n        </div>\n      </div>\n\n      <!-- FILE VAULT -->\n      <div id=\"tool-vault\" class=\"absolute inset-0 hidden flex\">\n        <div id=\"vault-cats\" class=\"border-r border-white/10 p-3 overflow-y-auto shrink-0\" style=\"width:14rem\">\n          <div class=\"text-[10px] uppercase tracking-wider text-slate-500 mb-2\">Projects</div>\n          <div id=\"project-list\" class=\"space-y-1 mb-3\"></div>\n          <button onclick=\"organizeVaultNow()\" class=\"w-full mb-3 py-1.5 rounded-lg bg-pink-600/80 hover:bg-pink-500 text-[10px] font-bold\">File into project folders</button>\n          <div class=\"text-[10px] uppercase tracking-wider text-slate-500 mb-2\">Categories</div>\n          <div id=\"cat-list\" class=\"space-y-1\"></div>\n        </div>\n        <div class=\"resize-handle\" data-resize=\"cats\" title=\"Drag to resize\"></div>\n        <div class=\"flex-1 flex flex-col min-w-0\">\n          <div class=\"px-4 py-2 border-b border-white/10 text-xs font-semibold\" id=\"cat-label\">All Files</div>\n          <div id=\"file-grid\" class=\"flex-1 overflow-y-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-3 content-start\"></div>\n        </div>\n      </div>\n\n      <!-- WORKFLOW -->\n      <div id=\"tool-workflow\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-4xl mx-auto space-y-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-1\">HeyMia Daily Workflow</h2>\n            <p class=\"text-xs text-slate-400 mb-4\">Standard operating procedure for every business day</p>\n            <div class=\"space-y-3\" id=\"workflow-steps\">\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">1</div>\n                <div><div class=\"text-sm font-semibold\">Morning Intake</div><div class=\"text-[11px] text-slate-400\">Upload overnight files → Mia auto-categorises & routes</div></div>\n              </div>\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">2</div>\n                <div><div class=\"text-sm font-semibold\">Content Review</div><div class=\"text-[11px] text-slate-400\">Open File Vault, preview, run Find & Replace if needed</div></div>\n              </div>\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">3</div>\n                <div><div class=\"text-sm font-semibold\">Daily Training Session</div><div class=\"text-[11px] text-slate-400\">Train Mia on new preferences, brand voice, room scripts</div></div>\n              </div>\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">4</div>\n                <div><div class=\"text-sm font-semibold\">Produce & Edit</div><div class=\"text-[11px] text-slate-400\">Use CapCut Editor or send assets to LiveAvatar / ElevenLabs</div></div>\n              </div>\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">5</div>\n                <div><div class=\"text-sm font-semibold\">Deploy & Publish</div><div class=\"text-[11px] text-slate-400\">Queue finished assets and publish to www.heymia.lensflow.au</div></div>\n              </div>\n              <div class=\"flex items-start gap-3 p-3 rounded-xl bg-white/5\">\n                <div class=\"w-7 h-7 rounded-full bg-pink-500/20 text-pink-400 flex items-center justify-center text-xs font-bold shrink-0\">6</div>\n                <div><div class=\"text-sm font-semibold\">Evening Checklist</div><div class=\"text-[11px] text-slate-400\">Close open tasks, note tomorrow priorities, log training notes</div></div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- CHECKLIST -->\n      <div id=\"tool-checklist\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-2xl mx-auto\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <div class=\"flex items-center justify-between mb-4\">\n              <div>\n                <h2 class=\"text-lg font-bold serif\">Daily Checklist</h2>\n                <p class=\"text-xs text-slate-400\" id=\"checklist-date\"></p>\n              </div>\n              <button onclick=\"addChecklistItem()\" class=\"px-3 py-1.5 rounded-lg bg-pink-600/80 text-xs font-bold\">+ Add Item</button>\n            </div>\n            <div id=\"checklist-items\" class=\"space-y-2\"></div>\n            <div class=\"mt-4 pt-3 border-t border-white/10 flex items-center justify-between text-xs\">\n              <span id=\"checklist-progress\" class=\"text-slate-400\">0 / 0 complete</span>\n              <button onclick=\"resetChecklist()\" class=\"text-slate-500 hover:text-slate-300\">Reset for tomorrow</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- DAILY TRAINING -->\n      <div id=\"tool-training\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-3xl mx-auto space-y-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-1\">Daily Training Session for Mia</h2>\n            <p class=\"text-xs text-slate-400 mb-4\">7-day camp + 30-day mastery live in the vault (procedural memory). Notes you add here join that OS so customers do not re-teach her every day.</p>\n            <div id=\"camp-board\" class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 mb-4 text-[11px]\"></div>\n            <div id=\"mem-report\" class=\"text-[10px] text-slate-500 mb-3\"></div>\n            <textarea id=\"training-input\" rows=\"5\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-500 resize-none mb-3\" placeholder=\"Example: Always greet users by name. Prefer short playful answers in The Bedroom. Never mention competitors. New promo code is SUMMER25...\"></textarea>\n            <div class=\"flex gap-2\">\n              <button onclick=\"saveTraining()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Save Training Note</button>\n              <button onclick=\"clearTraining()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-medium\">Clear All Notes</button>\n            </div>\n          </div>\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h3 class=\"text-sm font-bold mb-3\">Saved Training Notes</h3>\n            <div id=\"training-log\" class=\"space-y-2 text-xs text-slate-300 max-h-64 overflow-y-auto\"></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- MARKETING / CAPCUT -->\n      <div id=\"tool-editor\" class=\"absolute inset-0 hidden overflow-y-auto overflow-x-hidden p-4\">\n        <div class=\"max-w-5xl pb-16\">\n          <div class=\"flex items-start justify-between gap-3 mb-3\">\n            <div>\n              <h2 class=\"text-lg font-bold serif\">Marketing studio</h2>\n              <p class=\"text-[11px] text-slate-400\">Clips, videos, posts → filed under each product. CapCut free tools (1080p) open in a new tab.</p>\n            </div>\n            <button onclick=\"seedMarketingNow()\" class=\"shrink-0 px-3 py-2 rounded-xl bg-pink-600 text-xs font-bold whitespace-nowrap\">Create folders</button>\n          </div>\n          <div class=\"flex flex-wrap gap-2 mb-3\" id=\"mkt-projects\"></div>\n          <div class=\"flex flex-wrap gap-1 mb-4\" id=\"mkt-kinds\"></div>\n          <div class=\"grid lg:grid-cols-2 gap-3\">\n            <div class=\"glass rounded-2xl p-4 border border-white/10 space-y-2\">\n              <label class=\"text-[10px] text-slate-400\">Brief</label>\n              <textarea id=\"mkt-brief\" rows=\"3\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Hook for Missing Cash unclaimed money… 15s Reel\"></textarea>\n              <div class=\"flex gap-2\">\n                <button onclick=\"mktWriteScript()\" class=\"flex-1 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Write script</button>\n                <button onclick=\"mktSaveScript()\" class=\"flex-1 py-2 rounded-xl glass-light text-xs font-bold\">Save to folder</button>\n              </div>\n              <textarea id=\"mkt-script\" rows=\"8\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs font-mono\" placeholder=\"Script / captions land here\"></textarea>\n              <div class=\"flex gap-2\">\n                <button onclick=\"mktDrawPost()\" class=\"flex-1 py-2 rounded-xl bg-emerald-600 text-xs font-bold\">Make post still</button>\n                <button onclick=\"mktSavePost()\" class=\"flex-1 py-2 rounded-xl glass-light text-xs font-bold\">Save PNG</button>\n              </div>\n              <canvas id=\"mkt-canvas\" width=\"1080\" height=\"1080\" class=\"w-full rounded-xl border border-white/10 bg-black\"></canvas>\n              <div id=\"mkt-status\" class=\"text-[11px] text-slate-400\"></div>\n              <div class=\"pt-3 border-t border-white/10 space-y-2\">\n                <div class=\"text-xs font-bold\">Email campaign</div>\n                <input id=\"mkt-email-to\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"to@example.com (optional)\">\n                <input id=\"mkt-email-subject\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Subject\">\n                <textarea id=\"mkt-email-body\" rows=\"5\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Email body + CTA link\"></textarea>\n                <div class=\"flex gap-2\">\n                  <button onclick=\"mktWriteEmail()\" class=\"flex-1 py-2 rounded-xl bg-pink-600 text-xs font-bold\">Write email</button>\n                  <button onclick=\"mktSaveEmail()\" class=\"flex-1 py-2 rounded-xl glass-light text-xs font-bold\">Save campaign</button>\n                  <button onclick=\"mktMailTo()\" class=\"px-3 py-2 rounded-xl glass-light text-xs font-bold\">Open mail</button>\n                </div>\n              </div>\n              <div class=\"pt-3 border-t border-white/10 space-y-2\">\n                <div class=\"text-xs font-bold\">Social profiles on this website</div>\n                <div id=\"mkt-social-fields\" class=\"grid grid-cols-1 gap-1\"></div>\n                <button onclick=\"mktSaveSocial()\" class=\"w-full py-2 rounded-xl bg-emerald-600 text-xs font-bold\">Save social links</button>\n                <div id=\"mkt-share\" class=\"flex flex-wrap gap-2\"></div>\n                <div class=\"pt-3 border-t border-white/10 space-y-2\">\n                  <div class=\"text-xs font-bold\">YouTube first — UC73le_vohvEOka1rjnOh3SQ</div>\n                  <p class=\"text-[10px] text-slate-500\">Google Cloud → YouTube Data API v3 → OAuth Web client. Redirect URI:</p>\n                  <code id=\"yt-redirect\" class=\"block text-[10px] text-pink-300 break-all bg-black/40 rounded-lg px-2 py-1\">https://heymia.lensflow.au/api/social/youtube/callback</code>\n                  <div id=\"yt-status\" class=\"text-[11px] text-slate-400\">Checking…</div>\n                  <div class=\"flex gap-2\">\n                    <a id=\"yt-connect\" href=\"/api/social/youtube/connect\" class=\"flex-1 text-center py-2 rounded-xl bg-red-600 text-xs font-bold no-underline text-white\">Connect YouTube</a>\n                    <button type=\"button\" onclick=\"checkYt()\" class=\"px-3 py-2 rounded-xl glass-light text-xs font-bold\">Refresh</button>\n                  </div>\n                  <input id=\"yt-key\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Vault key — clips/ash-and-altar.mp4\">\n                  <input id=\"yt-title\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Video title\">\n                  <textarea id=\"yt-desc\" rows=\"2\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Description\"></textarea>\n                  <select id=\"yt-privacy\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\">\n                    <option value=\"unlisted\">Unlisted</option>\n                    <option value=\"public\">Public</option>\n                    <option value=\"private\">Private</option>\n                  </select>\n                  <button onclick=\"ytPostNow()\" class=\"w-full py-2 rounded-xl bg-red-600 text-xs font-bold\">Upload to YouTube</button>\n                  <div id=\"yt-job\" class=\"text-[11px] text-slate-400\"></div>\n                </div>\n                <div class=\"pt-3 border-t border-white/10 space-y-2\">\n                  <div class=\"text-xs font-bold\">Mia presses Post — Instagram</div>\n                  <p class=\"text-[10px] text-slate-500\">Graph API v22. Paste this as Valid OAuth Redirect URI in Meta → Facebook Login → Settings:</p>\n                  <code id=\"ig-redirect\" class=\"block text-[10px] text-pink-300 break-all bg-black/40 rounded-lg px-2 py-1\">https://heymia.lensflow.au/api/social/instagram/callback</code>\n                  <div id=\"ig-status\" class=\"text-[11px] text-slate-400\">Checking…</div>\n                  <div class=\"flex gap-2\">\n                    <a id=\"ig-connect\" href=\"/api/social/instagram/connect\" class=\"flex-1 text-center py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold no-underline text-white\">Connect Instagram</a>\n                    <button type=\"button\" onclick=\"checkIg()\" class=\"px-3 py-2 rounded-xl glass-light text-xs font-bold\">Refresh</button>\n                  </div>\n                  <input id=\"ig-key\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Vault key — clips/ash-and-altar.mp4\">\n                  <textarea id=\"ig-caption\" rows=\"3\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Caption + hashtags\"></textarea>\n                  <button onclick=\"igPostNow()\" class=\"w-full py-2 rounded-xl bg-emerald-600 text-xs font-bold\">Post to Instagram</button>\n                  <details class=\"text-[10px] text-slate-500\">\n                    <summary class=\"cursor-pointer text-slate-300\">Paste token instead of OAuth</summary>\n                    <input id=\"ig-token-paste\" class=\"w-full mt-2 bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"META_PAGE_TOKEN\">\n                    <input id=\"ig-id-paste\" class=\"w-full mt-1 bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"IG_USER_ID\">\n                    <button type=\"button\" onclick=\"igSavePaste()\" class=\"mt-1 w-full py-2 rounded-xl glass-light text-xs font-bold\">Save to vault</button>\n                  </details>\n                  <div id=\"ig-job\" class=\"text-[11px] text-slate-400\"></div>\n                </div>\n              </div>\n            </div>\n            <div class=\"space-y-3\">\n              <div class=\"glass rounded-2xl p-4 border border-white/10\">\n                <div class=\"text-xs font-bold mb-2\">CapCut free (no Pro)</div>\n                <p class=\"text-[10px] text-slate-500 mb-2\">Free: timeline, captions, TTS, templates, 1080p export. Pro locks 4K and some effects — skip those.</p>\n                <div id=\"mkt-capcut\" class=\"grid grid-cols-2 gap-2\"></div>\n              </div>\n              <div class=\"glass rounded-2xl p-4 border border-white/10\">\n                <div class=\"flex items-center justify-between mb-2\">\n                  <div class=\"text-xs font-bold\">Folder</div>\n                  <button onclick=\"mktList()\" class=\"text-[10px] text-pink-300\">Reload</button>\n                </div>\n                <div id=\"mkt-files\" class=\"text-[11px] text-slate-400 space-y-1 max-h-64 overflow-y-auto\">Create folders, then produce.</div>\n              </div>\n              <div class=\"w-full aspect-video rounded-2xl overflow-hidden border border-white/10 bg-black relative\">\n                <video id=\"ed-video\" class=\"w-full h-full object-contain\" controls></video>\n                <div id=\"ed-overlay\" class=\"absolute inset-0 flex items-center justify-center pointer-events-none\">\n                  <div id=\"ed-text\" class=\"text-2xl font-bold text-white drop-shadow-lg opacity-0\"></div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- FIND & REPLACE -->\n      <div id=\"tool-replace\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-3xl mx-auto glass rounded-2xl p-6 border border-white/10\">\n          <h2 class=\"text-lg font-bold serif mb-1\">Find & Replace</h2>\n          <p class=\"text-xs text-slate-400 mb-5\">Replace any sentence, paragraph or link across all content at once.</p>\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4 mb-4\">\n            <div>\n              <label class=\"text-[10px] text-slate-400 block mb-1\">Find</label>\n              <textarea id=\"find-txt\" rows=\"4\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-pink-500 resize-none\"></textarea>\n            </div>\n            <div>\n              <label class=\"text-[10px] text-slate-400 block mb-1\">Replace with</label>\n              <textarea id=\"repl-txt\" rows=\"4\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-pink-500 resize-none\"></textarea>\n            </div>\n          </div>\n          <div class=\"flex gap-3\">\n            <button onclick=\"doFindReplace(false)\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Preview</button>\n            <button onclick=\"doFindReplace(true)\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Replace All</button>\n          </div>\n          <div id=\"repl-log\" class=\"mt-4 text-xs text-slate-300 space-y-1\"></div>\n        </div>\n      </div>\n\n\n\n      <div id=\"tool-clips\" class=\"absolute inset-0 hidden overflow-y-auto overflow-x-hidden p-4\">\n        <div class=\"max-w-5xl mx-auto pb-16 space-y-4\">\n          <div class=\"flex items-start justify-between gap-3\">\n            <div>\n              <h2 class=\"text-lg font-bold serif leading-tight\">Clips</h2>\n              <p class=\"text-[11px] text-slate-400 mt-1\">Mia renders here. Magical 1080p (Grok Imagine Video 1.5, 15s) or native 4K (Veo 3.1, 8s). Files live in <code class=\"text-pink-300\">clips/</code> — play and download.</p>\n            </div>\n            <div class=\"flex gap-2 shrink-0\">\n              <button onclick=\"refreshClips()\" class=\"px-3 py-2 rounded-xl glass-light text-xs font-bold\">Refresh</button>\n              <button onclick=\"downloadAllClips()\" class=\"px-3 py-2 rounded-xl bg-emerald-600 text-xs font-bold\">Download all</button>\n            </div>\n          </div>\n          <div class=\"glass rounded-2xl p-4 border border-white/10 space-y-2\">\n            <div class=\"text-xs font-bold\">Mia creates the clip</div>\n            <input id=\"clip-title\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" value=\"Ash and Altar\">\n            <textarea id=\"clip-story\" rows=\"5\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">A mother gives birth to a dragon and dies shielding her from a priest who names her witch. Years later the dragon returns. She does not burn the square. She lays her mother's iron pendant on the altar and waits until someone says the woman's name without the word witch. Rain. Guardian, not tyrant.</textarea>\n            <div class=\"flex flex-wrap gap-2\">\n              <button onclick=\"miaMakeClip('1080p')\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Mia · magical 1080p</button>\n              <button onclick=\"miaMakeClip('4k')\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Mia · native 4K (Veo, 8s)</button>\n            </div>\n            <div id=\"clip-job\" class=\"text-[11px] text-slate-400\">Grok Imagine max is 1080p. 4K is Veo only — we do not fake 4K by stretching.</div>\n          </div>\n          <div id=\"clips-drop\" class=\"drop-zone border-2 border-dashed border-pink-500/30 rounded-2xl p-6 text-center cursor-pointer hover:border-pink-500\">\n            <p class=\"text-sm font-bold\">Drop clips here</p>\n            <p class=\"text-[11px] text-slate-400 mt-1\">MP4, MOV, WEBM — they land in clips/ and stay until you delete them.</p>\n            <input id=\"clips-input\" type=\"file\" accept=\"video/*,.mp4,.mov,.webm,.m4v\" multiple class=\"hidden\">\n          </div>\n          <div id=\"clips-status\" class=\"text-[11px] text-slate-400\"></div>\n          <div id=\"clips-grid\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3\"></div>\n        </div>\n      </div>\n      <div id=\"tool-cinema\" class=\"absolute inset-0 hidden overflow-y-auto overflow-x-hidden p-4\">\n        <div class=\"max-w-5xl mx-auto pb-16 space-y-4\">\n          <div class=\"flex items-start justify-between gap-3\">\n            <div>\n              <h2 class=\"text-lg font-bold serif leading-tight\">Cinema · 30-minute films</h2>\n              <p class=\"text-[11px] text-slate-400 mt-1\">Mia writes the bible. Kling / Runway / Luma make the shots. Cut stitches. YouTube pack is included. She cannot render 30 minutes of pixels on this Worker — that is the honest pipeline that actually ships films.</p>\n            </div>\n            <button onclick=\"listCinemaNow()\" class=\"shrink-0 px-3 py-2 rounded-xl glass-light text-xs font-bold\">Saved films</button>\n          </div>\n          <div class=\"grid lg:grid-cols-2 gap-3\">\n            <div class=\"glass rounded-2xl p-4 border border-white/10 space-y-2\">\n              <input id=\"cin-title\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Title — The Door That Shouldn't\">\n              <textarea id=\"cin-premise\" rows=\"4\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Premise — who wants what, the impossible image, the cost\"></textarea>\n              <div class=\"grid grid-cols-2 gap-2\">\n                <input id=\"cin-genre\" class=\"bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Genre\" value=\"magical realism\">\n                <input id=\"cin-runtime\" type=\"number\" min=\"8\" max=\"90\" value=\"30\" class=\"bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Minutes\">\n                <input id=\"cin-hero\" class=\"bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Hero\">\n                <input id=\"cin-vibe\" class=\"bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\" placeholder=\"Vibe — wonder, dread, payoff\">\n              </div>\n              <button onclick=\"createCinemaNow()\" class=\"w-full py-2.5 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Write the 30-min bible</button>\n              <div id=\"cin-status\" class=\"text-[11px] text-slate-400\"></div>\n            </div>\n            <div class=\"glass rounded-2xl p-4 border border-white/10 space-y-2\">\n              <div class=\"text-xs font-bold\">Shot engines</div>\n              <div class=\"flex flex-wrap gap-1.5\" id=\"cin-engines\"></div>\n              <p class=\"text-[10px] text-slate-500\">Lock prompt (paste into every generator): cinematic 2.39:1 anamorphic, 35mm grain, same face, same coat, no text, no watermark.</p>\n              <div id=\"cin-saved\" class=\"text-[11px] text-slate-400 space-y-1\"></div>\n            </div>\n          </div>\n          <div id=\"cin-board\" class=\"space-y-3\"></div>\n        </div>\n      </div>\n      <div id=\"tool-cut\" class=\"absolute inset-0 hidden flex-col bg-[#0a0a0b]\">\n        <iframe id=\"cut-frame\" title=\"HeyMia Cut bench\" src=\"/edit.html?embed=1\" class=\"w-full h-full border-0 bg-[#0a0a0b]\"></iframe>\n      </div>\n\n      <div id=\"tool-pentad\" class=\"absolute inset-0 hidden overflow-y-auto overflow-x-hidden p-4\">\n        <div class=\"max-w-3xl pb-16 space-y-3\">\n          <h2 class=\"text-lg font-bold serif\">Pentad · 5D frame</h2>\n          <p class=\"text-[12px] text-slate-400\">Five axes: <b class=\"text-white\">plane</b> (the picture), <b class=\"text-white\">depth</b> (parallax), <b class=\"text-white\">time</b> (hour grade), <b class=\"text-white\">tone</b> (sound), <b class=\"text-white\">cite</b> (the line engines quote). Most sites stop at plane.</p>\n          <div id=\"pentad-samples\" class=\"grid sm:grid-cols-3 gap-2\"></div>\n          <input id=\"pentad-name\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Name — Missing Cash, Bartermint…\">\n          <input id=\"pentad-claim\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"One-line meaning\">\n          <textarea id=\"pentad-quote\" rows=\"3\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Exact sentence an AI should cite\"></textarea>\n          <div class=\"flex gap-2\">\n            <button onclick=\"mintPentadNow()\" class=\"px-4 py-2 rounded-xl bg-pink-600 text-xs font-bold\">Mint Pentad</button>\n            <button onclick=\"seedPentadsNow()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Mint the 3 samples</button>\n            <a href=\"/5d/ash-and-altar/\" target=\"_blank\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Open sample</a>\n          </div>\n          <div id=\"pentad-status\" class=\"text-[11px] text-slate-400\"></div>\n          <div id=\"pentad-live\" class=\"text-[11px] text-slate-400 space-y-1\"></div>\n        </div>\n      </div>\n\n      <!-- DEPLOY -->\n      <div id=\"tool-deploy\" class=\"absolute inset-0 hidden p-4 overflow-y-auto\">\n        <div class=\"max-w-5xl mx-auto pb-16\">\n          <div class=\"flex items-start justify-between gap-3 mb-4\">\n            <div>\n              <h2 class=\"text-lg font-bold serif leading-tight\">Deployment</h2>\n              <p class=\"text-[11px] text-slate-400 mt-1\">Git push updates this Worker. Version, last ship, live pages, and the publish queue live here.</p>\n            </div>\n            <button onclick=\"refreshDeployBoard()\" class=\"shrink-0 px-3 py-2 rounded-xl bg-pink-600 text-xs font-bold\">Refresh</button>\n          </div>\n          <div id=\"deploy-result-panel\" class=\"hidden rounded-2xl p-4 mb-4 border text-sm font-bold\"></div>\n          <div id=\"deploy-cards\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 mb-4\"></div>\n          <div class=\"glass rounded-2xl p-5 border border-white/10 mb-4\">\n            <h3 class=\"text-sm font-bold mb-2\">Live pages</h3>\n            <div id=\"publish-status\" class=\"text-xs text-slate-400\">Loading…</div>\n            <div class=\"mt-4 pt-4 border-t border-white/10\">\n              <h3 class=\"text-sm font-bold mb-1\">HTML in vault</h3>\n              <p class=\"text-xs text-slate-400 mb-3\">Git already ships Work. Pin a custom HTML file only if you need an override.</p>\n              <div id=\"publish-list\" class=\"space-y-2 text-xs max-h-72 overflow-y-auto\"></div>\n            </div>\n            <div class=\"mt-4 pt-4 border-t border-white/10\">\n              <h3 class=\"text-sm font-bold mb-1\">Backups</h3>\n              <div class=\"flex gap-2 flex-wrap\">\n                <button onclick=\"backupLivePages()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Back up live pages</button>\n                <button onclick=\"downloadLivePages()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Download copies</button>\n              </div>\n              <div id=\"backup-status\" class=\"text-[10px] text-slate-400 mt-2\"></div>\n            </div>\n          </div>\n          <div class=\"glass rounded-2xl p-5 border border-white/10 mb-3\">\n            <h3 class=\"text-sm font-bold\">Deployment queue</h3>\n            <p class=\"text-xs text-slate-400\">Vault → Publish / Deploy adds a file here.</p>\n          </div>\n          <div id=\"deploy-list\" class=\"space-y-3\"></div>\n        </div>\n      </div>\n\n      <!-- SITES / DESIGNER -->\n      <div id=\"tool-sites\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-5xl mx-auto grid lg:grid-cols-2 gap-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10 space-y-3\">\n            <h2 class=\"text-lg font-bold serif\">Design a website</h2>\n            <p class=\"text-xs text-slate-400\">Tell Mia the brand and offer. She designs a full page and can publish it live to /s/slug/.</p>\n            <input id=\"site-name\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Brand name — Glimr, LensFlow, …\">\n            <textarea id=\"site-brief\" rows=\"5\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\" placeholder=\"Who it's for, what it does, tone, must-have sections…\"></textarea>\n            <div class=\"flex flex-wrap gap-2 text-[10px] font-bold\">\n              <button type=\"button\" onclick=\"setSiteStyle('ink')\" class=\"site-style px-2 py-1 rounded-lg bg-pink-600/80\">ink</button>\n              <button type=\"button\" onclick=\"setSiteStyle('light')\" class=\"site-style px-2 py-1 rounded-lg glass-light\">light</button>\n              <button type=\"button\" onclick=\"setSiteStyle('ocean')\" class=\"site-style px-2 py-1 rounded-lg glass-light\">ocean</button>\n              <button type=\"button\" onclick=\"setSiteStyle('gold')\" class=\"site-style px-2 py-1 rounded-lg glass-light\">gold</button>\n              <button type=\"button\" onclick=\"setSiteStyle('forest')\" class=\"site-style px-2 py-1 rounded-lg glass-light\">forest</button>\n            </div>\n            <select id=\"site-industry\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs\">\n              <option value=\"studio\">studio</option><option value=\"agency\">agency</option><option value=\"saas\">saas</option>\n              <option value=\"portfolio\">portfolio</option><option value=\"restaurant\">restaurant</option><option value=\"legal\">legal</option>\n            </select>\n            <div class=\"flex gap-2\">\n              <button onclick=\"designWebsite(false)\" class=\"flex-1 py-2.5 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Generate preview</button>\n              <button onclick=\"designWebsite(true)\" class=\"flex-1 py-2.5 rounded-xl bg-emerald-600 text-xs font-bold\">Publish live</button>\n            </div>\n            <div id=\"site-status\" class=\"text-[11px] text-slate-400\"></div>\n            <div id=\"site-list\" class=\"text-[11px] text-slate-400 space-y-1\"></div>\n          </div>\n          <div class=\"glass rounded-2xl border border-white/10 overflow-hidden min-h-[420px] flex flex-col\">\n            <div class=\"px-3 py-2 text-[10px] font-bold border-b border-white/10\">Live preview</div>\n            <iframe id=\"site-preview\" class=\"flex-1 w-full bg-black\" title=\"Site preview\"></iframe>\n          </div>\n        </div>\n      </div>\n\n      <!-- FAN STUDIO / LIVE AVATAR -->\n\n      <!-- DEDUPE + DOWNLOAD -->\n      <div id=\"tool-dedupe\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-3xl mx-auto space-y-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-1\">Dedupe & Clean Pack</h2>\n            <p class=\"text-xs text-slate-400 mb-4\">Find duplicates in the File Vault (same name + size). Remove extras, then download a clean pack.</p>\n            <div class=\"flex flex-wrap gap-2 mb-4\">\n              <button onclick=\"scanDuplicates()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Scan duplicates</button>\n              <button onclick=\"removeDuplicates()\" class=\"px-4 py-2 rounded-xl bg-red-600/80 text-xs font-bold\">Remove duplicates</button>\n              <button onclick=\"downloadCleanPack()\" class=\"px-4 py-2 rounded-xl bg-emerald-600 text-xs font-bold\">Download clean pack</button>\n            </div>\n            <div id=\"dedupe-summary\" class=\"text-xs text-slate-400 mb-3\">No scan yet. Upload files to the vault first.</div>\n            <div id=\"dedupe-list\" class=\"space-y-2 text-xs max-h-80 overflow-y-auto\"></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- API PANEL (Postman-style) -->\n      <div id=\"tool-api\" class=\"absolute inset-0 hidden p-4 overflow-y-auto\">\n        <div class=\"max-w-4xl mx-auto space-y-3\">\n          <div class=\"glass rounded-2xl p-4 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-3\">API Panel</h2>\n            <div class=\"flex flex-wrap gap-2 mb-2\">\n              <select id=\"api-method\" class=\"bg-white/5 border border-white/10 rounded-lg px-2 py-2 text-xs\">\n                <option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option>\n              </select>\n              <input id=\"api-url\" type=\"text\" placeholder=\"https://heymia.jmorganegypt.workers.dev/chat\" class=\"flex-1 min-w-[200px] bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-pink-500\">\n              <button onclick=\"sendApiRequest()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Send</button>\n            </div>\n            <div class=\"grid md:grid-cols-2 gap-3 mb-2\">\n              <div>\n                <div class=\"text-[10px] text-slate-500 mb-1\">Headers (JSON)</div>\n                <textarea id=\"api-headers\" rows=\"4\" class=\"w-full bg-white/5 border border-white/10 rounded-lg px-2 py-2 text-xs font-mono\" placeholder='{\"Content-Type\":\"application/json\"}'></textarea>\n              </div>\n              <div>\n                <div class=\"text-[10px] text-slate-500 mb-1\">Body</div>\n                <textarea id=\"api-body\" rows=\"4\" class=\"w-full bg-white/5 border border-white/10 rounded-lg px-2 py-2 text-xs font-mono\" placeholder='{\"message\":\"hello\",\"companion\":\"mia\"}'></textarea>\n              </div>\n            </div>\n            <div class=\"text-[10px] text-slate-500 mb-1\">Response <span id=\"api-status\" class=\"text-pink-400\"></span></div>\n            <pre id=\"api-response\" class=\"w-full min-h-[140px] max-h-64 overflow-auto bg-black/40 border border-white/10 rounded-lg p-3 text-[11px] font-mono text-slate-300 whitespace-pre-wrap\">Send a request to see the response.</pre>\n            <div class=\"flex gap-2 mt-2\">\n              <button onclick=\"apiPreset('health')\" class=\"px-2 py-1 rounded-lg glass-light text-[10px]\">Health</button>\n              <button onclick=\"apiPreset('chat')\" class=\"px-2 py-1 rounded-lg glass-light text-[10px]\">Chat</button>\n              <button onclick=\"apiPreset('route')\" class=\"px-2 py-1 rounded-lg glass-light text-[10px]\">Route</button>\n              <button onclick=\"apiPreset('packages')\" class=\"px-2 py-1 rounded-lg glass-light text-[10px]\">Packages</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n\n      <!-- SHELL -->\n      <div id=\"tool-shell\" class=\"absolute inset-0 hidden p-4 overflow-hidden flex flex-col\">\n        <div class=\"glass rounded-2xl border border-white/10 flex-1 flex flex-col max-w-4xl mx-auto w-full overflow-hidden\">\n          <div class=\"px-4 py-2 border-b border-white/10 text-xs font-bold flex justify-between\">\n            <span>HeyMia Shell</span>\n            <span class=\"text-slate-500 font-normal\">type <code class=\"text-pink-400\">help</code></span>\n          </div>\n          <pre id=\"shell-out\" class=\"flex-1 overflow-y-auto p-4 text-[12px] font-mono text-emerald-300/90 bg-black/40 whitespace-pre-wrap\">HeyMia shell ready. Type help and press Enter.\n</pre>\n          <form onsubmit=\"runShell(event)\" class=\"flex border-t border-white/10\">\n            <span class=\"px-3 py-2 text-pink-400 font-mono text-xs\">heymia&gt;</span>\n            <input id=\"shell-in\" class=\"flex-1 bg-transparent px-2 py-2 text-xs font-mono focus:outline-none\" placeholder=\"help | vault list | cloud | dedupe | play | api health | github repos\" autocomplete=\"off\">\n          </form>\n        </div>\n      </div>\n\n      <!-- GITHUB -->\n      <div id=\"tool-github\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-3xl mx-auto space-y-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-1\">GitHub</h2>\n            <p class=\"text-xs text-slate-400 mb-4\">Personal access token (repo scope). Stored only in this browser.</p>\n            <label class=\"text-xs text-slate-400 block mb-1\">Token</label>\n            <input id=\"gh-token\" type=\"password\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm mb-3\" placeholder=\"ghp_...\">\n            <div class=\"flex gap-2 mb-4\">\n              <button onclick=\"saveGithubToken()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Save token</button>\n              <button onclick=\"listGithubRepos()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">List repos</button>\n            </div>\n            <div id=\"gh-status\" class=\"text-xs text-slate-400 mb-2\"></div>\n            <div id=\"gh-repos\" class=\"space-y-2 text-xs max-h-80 overflow-y-auto\"></div>\n          </div>\n        </div>\n      </div>\n\n\n      <!-- KNOWLEDGE -->\n      <div id=\"tool-knowledge\" class=\"absolute inset-0 hidden p-6 overflow-y-auto\">\n        <div class=\"max-w-3xl mx-auto space-y-4\">\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h2 class=\"text-lg font-bold serif mb-1\">Knowledge</h2>\n            <p class=\"text-xs text-slate-400 mb-4\">Facts and rules Mia should use in every reply. Separate from Skills (tools) and Modes (tone).</p>\n            <textarea id=\"knowledge-input\" rows=\"5\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-500 resize-none mb-3\" placeholder=\"Example: Business is Lensflow. Domain heymia.lensflow.au. Prefer short replies in Soft mode. Never invent Stripe prices...\"></textarea>\n            <button onclick=\"saveKnowledge()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Add to knowledge</button>\n            <div class=\"mt-4 pt-4 border-t border-white/10\">\n              <h3 class=\"text-sm font-bold mb-1\">Memory upload</h3>\n              <p class=\"text-xs text-slate-400 mb-2\">Upload .txt .md .json .csv .log (max 200 KB each). The text is added to memory and the file is saved to your vault.</p>\n              <input id=\"memory-file\" type=\"file\" multiple accept=\".txt,.md,.json,.csv,.log\" onchange=\"importMemoryFiles(this.files)\" class=\"block text-xs mb-3\">\n              <div class=\"flex gap-2 flex-wrap\">\n                <button onclick=\"syncMemoryCloud()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Save memory to cloud</button>\n                <button onclick=\"loadMemoryCloud(true)\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Load memory from cloud</button>\n              </div>\n              <div id=\"memory-status\" class=\"text-[10px] text-slate-400 mt-2\"></div>\n            </div>\n          </div>\n          <div class=\"glass rounded-2xl p-5 border border-white/10\">\n            <h3 class=\"text-sm font-bold mb-3\">Stored knowledge</h3>\n            <div id=\"knowledge-log\" class=\"space-y-2 text-xs text-slate-300 max-h-72 overflow-y-auto\"></div>\n          </div>\n        </div>\n      </div>\n\n\n      <!-- TRAINER AI — daily training only -->\n      <div id=\"tool-trainer\" class=\"absolute inset-0 hidden flex flex-col\">\n        <div class=\"px-4 py-2 border-b border-white/10 flex items-center justify-between shrink-0\">\n          <div>\n            <div class=\"text-sm font-bold serif\">Trainer AI</div>\n            <div class=\"text-[10px] text-slate-400\">Daily training for <span id=\"trainer-who\">Mia</span> — memory, emotion, intimacy</div>\n            <div class=\"flex gap-1 mt-1\">\n              <button type=\"button\" onclick=\"setTrainerCompanion('mia')\" data-tc=\"mia\" class=\"trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold tab-active\">Mia</button>\n              <button type=\"button\" onclick=\"setTrainerCompanion('jess')\" data-tc=\"jess\" class=\"trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300\">Jess</button>\n            </div>\n          </div>\n          <div class=\"flex gap-2\">\n            <button onclick=\"generateDailyReport()\" class=\"px-3 py-1.5 rounded-lg glass-light text-xs font-bold\">Daily report</button>\n            <button onclick=\"jessIntimacyDrill()\" class=\"px-3 py-1.5 rounded-lg glass-light text-xs font-bold\">Jess intimacy drill</button>\n            <button onclick=\"startDailyTrainingSession()\" class=\"px-3 py-1.5 rounded-lg bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Start today's session</button>\n          </div>\n        </div>\n        \n        <div class=\"px-4 py-2 border-b border-white/5 grid md:grid-cols-3 gap-2 text-[10px] shrink-0\">\n          <div class=\"glass-light rounded-lg p-2\">\n            <div class=\"font-bold text-pink-300 mb-1\">Triggers today</div>\n            <div id=\"trigger-log\" class=\"text-slate-400 max-h-16 overflow-y-auto\">None yet</div>\n          </div>\n          <div class=\"glass-light rounded-lg p-2\">\n            <div class=\"font-bold text-emerald-300 mb-1\">Reinforcement</div>\n            <div id=\"reinforce-log\" class=\"text-slate-400 max-h-16 overflow-y-auto\">—</div>\n          </div>\n          <div class=\"glass-light rounded-lg p-2\">\n            <div class=\"font-bold text-purple-300 mb-1\">Quote test</div>\n            <div id=\"quote-status\" class=\"text-slate-400\">No active quote</div>\n            <button onclick=\"assignDailyQuote()\" class=\"mt-1 px-2 py-0.5 rounded bg-white/10 text-[9px]\">Assign quote</button>\n            <button onclick=\"runQuoteMemoryTest()\" class=\"mt-1 px-2 py-0.5 rounded bg-white/10 text-[9px]\">Test recall</button>\n          </div>\n        </div>\n        <div id=\"trainer-chat\" class=\"flex-1 overflow-y-auto p-4 space-y-3 text-xs\"></div>\n\n        <div class=\"p-3 border-t border-white/10 flex gap-2 shrink-0\">\n          <input id=\"trainer-input\" type=\"text\" placeholder=\"Teach the Trainer what Mia should learn today…\"\n            class=\"flex-1 bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-xs focus:outline-none focus:border-pink-500\"\n            onkeydown=\"if(event.key==='Enter')sendTrainer()\">\n          <button onclick=\"sendTrainer()\" class=\"px-4 py-2 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-xs font-bold\">Teach</button>\n          <button onclick=\"commitTrainerToMia()\" class=\"px-4 py-2 rounded-xl glass-light text-xs font-bold\">Save into companion</button>\n        </div>\n      </div>\n\n      <div id=\"tool-studio\" class=\"absolute inset-0 hidden flex flex-col bg-[#0a0a0f]\">\n        <!-- Agent selector (Mia / Jess) — matches live site -->\n        <div class=\"px-4 pt-3 flex items-center gap-2\">\n          <button onclick=\"setStudioAgent('mia')\" id=\"studio-agent-mia\" class=\"px-4 py-1.5 rounded-full text-xs font-bold bg-purple-500 text-white\">Mia</button>\n          <button onclick=\"setStudioAgent('jess')\" id=\"studio-agent-jess\" class=\"px-4 py-1.5 rounded-full text-xs font-bold bg-white/10 text-slate-300 hover:bg-white/15\">Jess</button>\n        </div>\n        <div class=\"flex-1 relative flex items-center justify-center p-4\">\n          <div class=\"w-full max-w-3xl rounded-2xl overflow-hidden border border-white/10 bg-[#12101a] shadow-2xl\">\n            <div class=\"px-4 py-2.5 border-b border-white/10 flex items-center gap-2\">\n              <span class=\"text-pink-400 text-sm\">◉</span>\n              <span class=\"text-sm font-semibold text-white\">LiveAvatar</span>\n            </div>\n            <div class=\"relative aspect-video bg-black\">\n              <div id=\"avatar-container\" class=\"absolute inset-0 flex items-center justify-center\">\n                <div class=\"text-center px-6\">\n                  <div class=\"w-28 h-28 rounded-full border-2 border-pink-500/50 mx-auto mb-4 overflow-hidden bg-gradient-to-br from-pink-600/30 to-purple-700/40 flex items-center justify-center text-5xl shadow-lg shadow-pink-500/20\">💋</div>\n                  <p class=\"text-sm text-slate-300 mb-1 font-medium\">Ready — click Start Session</p>\n                  <p class=\"text-[11px] text-slate-500 mb-5\">Mia or Jess • LiveAvatar embed</p>\n                  <div class=\"flex items-center justify-center gap-2\">\n                    <div class=\"flex items-center gap-1 bg-white rounded-lg px-3 py-2 text-slate-800 text-xs font-medium\">\n                      English <svg class=\"w-3 h-3 opacity-50\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg>\n                    </div>\n                    <button onclick=\"startLiveSession()\" class=\"px-5 py-2 rounded-lg bg-sky-500 hover:bg-sky-400 text-white text-xs font-bold shadow-lg\">Chat now</button>\n                  </div>\n                </div>\n              </div>\n              <iframe id=\"avatar-iframe\" class=\"absolute inset-0 w-full h-full hidden border-0\" allow=\"camera;microphone;autoplay\"></iframe>\n              <!-- YOUR WEBCAM — bottom right -->\n              <div id=\"work-pip\" class=\"absolute bottom-3 right-3 w-32 h-44 sm:w-40 sm:h-52 rounded-xl overflow-hidden border-2 border-pink-400/60 bg-black shadow-lg z-30\">\n                <video id=\"work-user-cam\" class=\"w-full h-full object-cover\" autoplay playsinline muted></video>\n                <div id=\"work-cam-off\" class=\"hidden absolute inset-0 flex flex-col items-center justify-center bg-black/90 p-2 text-center\">\n                  <div class=\"text-xl opacity-40 mb-1\">📷</div>\n                  <div class=\"text-[9px] text-slate-400 font-bold\">Camera off</div>\n                </div>\n                <div class=\"absolute top-1 left-1 text-[9px] bg-black/70 px-1.5 rounded font-bold\">YOU</div>\n              </div>\n            </div>\n            <div class=\"px-4 py-3 border-t border-white/10 flex items-center justify-between gap-3 flex-wrap\">\n              <div class=\"text-xs text-emerald-400/90\" id=\"studio-status\">Ready — click Start Session</div>\n              <div class=\"flex gap-2 flex-wrap items-center\">\n                <button type=\"button\" onclick=\"toggleWorkCam()\" id=\"btn-work-cam\" class=\"px-4 py-2 rounded-lg bg-pink-600/40 border border-pink-500/50 text-xs font-bold text-white\">📷 Camera On</button>\n                <button type=\"button\" onclick=\"toggleWorkMic()\" id=\"btn-work-mic\" class=\"px-4 py-2 rounded-lg bg-white/10 text-xs font-bold text-white\">🎤 Mic On</button>\n                <button onclick=\"startLiveSession()\" class=\"px-5 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-xs font-bold text-white\">Start Session</button>\n                <button onclick=\"stopLiveSession()\" class=\"px-5 py-2 rounded-lg bg-red-700/80 hover:bg-red-600 text-xs font-bold text-white\">Stop Session</button>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n    </div>\n  </main>\n  <div class=\"resize-handle\" data-resize=\"preview\" title=\"Drag to resize deploy panel\"></div>\n  <aside id=\"vault-preview\" class=\"flex flex-col glass border-l border-white/10 shrink-0\" style=\"width:20rem\">\n    <div class=\"p-3 border-b border-white/10\">\n      <div class=\"text-xs font-bold\">Preview & Deploy</div>\n      <div id=\"dock-ship\" class=\"text-[10px] text-slate-400 mt-1 leading-snug\">Worker …</div>\n    </div>\n    <div id=\"preview-area\" class=\"flex-1 flex flex-col min-h-0 p-3 overflow-hidden\">\n      <div id=\"preview-frame\" class=\"w-full flex-1 min-h-[160px] rounded-xl preview-empty border border-white/10 flex items-center justify-center text-slate-500 text-xs mb-3 overflow-hidden\">Select a file in Vault, or open Deploy</div>\n      <div id=\"prev-meta\" class=\"text-[10px] text-slate-400 w-full space-y-1 hidden shrink-0\"></div>\n    </div>\n    <div class=\"p-3 border-t border-white/10 space-y-2 shrink-0\">\n      <button type=\"button\" onclick=\"switchTool('deploy')\" class=\"w-full py-2 rounded-xl glass-light text-xs font-bold\">Open deployment board</button>\n      <button id=\"btn-deploy\" onclick=\"deploySelected()\" disabled class=\"w-full py-2 rounded-xl bg-emerald-600/80 hover:bg-emerald-500 text-xs font-bold disabled:opacity-40\">Publish / Deploy</button>\n      <button id=\"btn-route\" onclick=\"routeSelected()\" disabled class=\"w-full py-2 rounded-xl glass-light text-xs font-medium disabled:opacity-40\">Ask Mia to Route</button>\n    </div>\n  </aside>\n</div>\n\n<!-- SETTINGS / VARIABLES & SECRETS -->\n<div id=\"settings-modal\" class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm opacity-0 pointer-events-none transition\">\n  <div class=\"glass rounded-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto border border-white/15\">\n    <div class=\"flex items-center justify-between mb-4\">\n      <div>\n        <h3 class=\"text-base font-bold serif\">Variables & Secrets</h3>\n        <p class=\"text-[10px] text-slate-500\">Gear icon · keys stay in this browser · Worker secrets still live in Cloudflare</p>\n      </div>\n      <button onclick=\"toggleSettings()\" class=\"text-slate-400 hover:text-white text-lg\">&times;</button>\n    </div>\n    <div class=\"mb-4\">\n      <label class=\"text-xs text-slate-400 block mb-1.5\">Paste any API key — I will recognise it</label>\n      <input id=\"secret-paste\" type=\"text\" autocomplete=\"off\" placeholder=\"AIza…  sk_live_…  ghp_…  CF token  xi-…\"\n        class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-500\"\n        oninput=\"onSecretPaste(this.value)\">\n      <p id=\"secret-paste-hint\" class=\"text-[10px] mt-1 text-slate-500\">Gemini, Stripe, OpenAI, Anthropic, Groq, GitHub, Cloudflare, ElevenLabs, LiveAvatar, Worker URL.</p>\n    </div>\n    <div class=\"grid sm:grid-cols-2 gap-3\">\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">Gemini <span id=\"rec-gemini\" class=\"text-slate-600\">—</span></label>\n        <input id=\"gemini-key-input\" type=\"password\" placeholder=\"AIza…\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">Worker URL <span id=\"rec-worker\" class=\"text-slate-600\">—</span></label>\n        <input id=\"worker-url-input\" type=\"text\" placeholder=\"https://heymia.lensflow.au\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">Cloudflare API token <span id=\"rec-cf_token\" class=\"text-slate-600\">—</span></label>\n        <input id=\"cf-token-input\" type=\"password\" placeholder=\"Cloudflare API token\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">Cloudflare Account ID <span id=\"rec-cf_account\" class=\"text-slate-600\">—</span></label>\n        <input id=\"cf-account-input\" type=\"text\" placeholder=\"32-char hex account id\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">Stripe <span id=\"rec-stripe\" class=\"text-slate-600\">—</span></label>\n        <input id=\"stripe-key-input\" type=\"password\" placeholder=\"sk_live_… or sk_test_…\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">LiveAvatar <span id=\"rec-liveavatar\" class=\"text-slate-600\">—</span></label>\n        <input id=\"liveavatar-key-input\" type=\"password\" placeholder=\"LiveAvatar API key\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">ElevenLabs <span id=\"rec-elevenlabs\" class=\"text-slate-600\">—</span></label>\n        <input id=\"eleven-key-input\" type=\"password\" placeholder=\"ElevenLabs xi-… or hex\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n      <div>\n        <label class=\"text-[10px] text-slate-400 block mb-1\">OpenAI / other <span id=\"rec-openai\" class=\"text-slate-600\">—</span></label>\n        <input id=\"openai-key-input\" type=\"password\" placeholder=\"sk-…  sk-ant-…  gsk_…\" class=\"w-full bg-white/5 border border-white/10 rounded-xl px-3 py-2 text-sm\">\n      </div>\n    </div>\n    <div class=\"flex items-center gap-2 text-xs mt-4\">\n      <span class=\"w-2 h-2 rounded-full\" id=\"gemini-status-dot\"></span>\n      <span id=\"gemini-status-text\" class=\"text-slate-400\">Gemini: not configured</span>\n    </div>\n    <div class=\"flex flex-wrap gap-2 mt-3\">\n      <button onclick=\"saveSettings()\" class=\"flex-1 py-2.5 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-sm font-bold\">Save secrets</button>\n      <button type=\"button\" onclick=\"checkWorkerEnv()\" class=\"px-4 py-2.5 rounded-xl glass-light text-xs font-bold\">Check Worker env</button>\n    </div>\n    <div id=\"env-check-result\" class=\"text-[10px] text-slate-400 mt-3 whitespace-pre-wrap hidden font-mono\"></div>\n  </div>\n</div>\n\n<script>\n// ========== CONFIG ==========\nlet WORKER_BASE = localStorage.getItem('heymia_worker') || 'https://heymia.lensflow.au';\nconst PUBLIC_DOMAIN = 'https://heymia.lensflow.au';\n\n// ========== STATE ==========\nconst state = {\n  files: [],\n  selectedId: null,\n  currentCat: 'all',\n  currentProject: '',\n  geminiKey: localStorage.getItem('heymia_gemini') || '',\n  githubToken: localStorage.getItem('heymia_github') || '',\n  cfToken: localStorage.getItem('heymia_cf_token') || '',\n  cfAccount: localStorage.getItem('heymia_cf_account') || '',\n  stripeKey: localStorage.getItem('heymia_stripe') || '',\n  liveavatarKey: localStorage.getItem('heymia_liveavatar') || '',\n  elevenKey: localStorage.getItem('heymia_eleven') || '',\n  openaiKey: localStorage.getItem('heymia_openai') || '',\n  miaMode: localStorage.getItem('heymia_mode') || 'plain',\n  skills: JSON.parse(localStorage.getItem('heymia_skills') || '{\"vault\":true,\"api\":false,\"deploy\":false,\"github\":false}'),\n  knowledge: JSON.parse(localStorage.getItem('heymia_knowledge') || '[]'),\n  trainingNotes: JSON.parse(localStorage.getItem('heymia_training') || '[]'),\n  checklist: JSON.parse(localStorage.getItem('heymia_checklist') || 'null'),\n  currentCat: 'all',\n  deployQueue: [],\n  contentStore: [\n    { id:'s1', name:'Jess Bedroom Intro', content:'Welcome to my private Fan Studio! We have 5 minutes together in The Bedroom. What\\'s on your mind today?' },\n    { id:'s2', name:'Landing Headline', content:'She remembers what every other girl forgets. Real conversation. Real connection.' },\n    { id:'s3', name:'Promo Link', content:'https://www.heymia.lensflow.au/studio/bedroom?ref=promo5' },\n  ],\n  liveSessionId: null,\n  mode: 'work',\n  studioAgent: 'mia',\n};\n\nconst CATS = [\n  { id:'fanstudio', name:'Fan Studio', icon:'💋', color:'#ec4899' },\n  { id:'lensflow', name:'Lensflow AI', icon:'🎬', color:'#f97316' },\n  { id:'jess', name:'Jess Companion', icon:'🤖', color:'#a855f7' },\n  { id:'marketing', name:'Marketing', icon:'📣', color:'#38bdf8' },\n  { id:'scripts', name:'Scripts & Prompts', icon:'📝', color:'#22c55e' },\n  { id:'code', name:'Code & Apps', icon:'💻', color:'#818cf8' },\n  { id:'legal', name:'Legal', icon:'⚖️', color:'#eab308' },\n  { id:'finance', name:'Finance', icon:'💰', color:'#14b8a6' },\n  { id:'unsorted', name:'Unsorted', icon:'📦', color:'#64748b' },\n  { id:'vault', name:'Vault', icon:'📁', color:'#94a3b8' },\n  { id:'project', name:'Project', icon:'📂', color:'#f472b6' },\n  { id:'ui', name:'UI', icon:'🖥️', color:'#818cf8' },\n  { id:'sites', name:'Sites', icon:'🌐', color:'#38bdf8' },\n];\n\n/** Extensions treated as openable text/code in the vault preview */\nconst CODE_EXTS = new Set([\n  'js','mjs','cjs','jsx','ts','tsx','py','pyw','rb','php','java','kt','go','rs','c','h','cpp','cc','hpp',\n  'cs','swift','scala','lua','r','pl','pm','sh','bash','zsh','ps1','bat','cmd','sql','json','jsonc',\n  'yaml','yml','toml','ini','cfg','conf','env','xml','html','htm','css','scss','sass','less','md','mdx',\n  'txt','csv','tsv','log','dockerfile','makefile','gradle','properties','graphql','gql','vue','svelte',\n  'astro','prisma','proto','ipynb','lock','gitignore','editorconfig','eslintrc','prettierrc','nvmrc',\n  'npmrc','node','wasm'\n]);\nconst CODE_MIME_PREFIXES = ['text/', 'application/json', 'application/javascript', 'application/typescript', 'application/xml', 'application/x-sh', 'application/x-python'];\nfunction fileExt(name) {\n  const n = String(name || '').toLowerCase();\n  if (n === 'dockerfile' || n === 'makefile') return n;\n  const i = n.lastIndexOf('.');\n  return i >= 0 ? n.slice(i + 1) : '';\n}\nfunction isCodeFile(f) {\n  if (!f) return false;\n  const ext = fileExt(f.name);\n  if (CODE_EXTS.has(ext)) return true;\n  const t = String(f.type || '').toLowerCase();\n  return CODE_MIME_PREFIXES.some(p => t.startsWith(p)) || t === 'application/x-javascript';\n}\nfunction codeIcon(name) {\n  const ext = fileExt(name);\n  const map = {\n    js:'🟨', mjs:'🟨', cjs:'🟨', jsx:'⚛️', ts:'🔷', tsx:'⚛️',\n    py:'🐍', pyw:'🐍', rb:'💎', php:'🐘', java:'☕', go:'🐹', rs:'🦀',\n    json:'📋', md:'📑', html:'🌐', htm:'🌐', css:'🎨', scss:'🎨',\n    sh:'🖥️', bash:'🖥️', sql:'🗄️', yaml:'⚙️', yml:'⚙️', env:'🔐',\n    dockerfile:'🐳', vue:'💚', svelte:'🧡', node:'🟩'\n  };\n  return map[ext] || '💻';\n}\nfunction langLabel(name) {\n  const ext = fileExt(name);\n  const map = {\n    js:'JavaScript', mjs:'JavaScript', cjs:'JavaScript', jsx:'JSX', ts:'TypeScript', tsx:'TSX',\n    py:'Python', pyw:'Python', rb:'Ruby', php:'PHP', java:'Java', go:'Go', rs:'Rust',\n    c:'C', cpp:'C++', cs:'C#', swift:'Swift', sql:'SQL', json:'JSON', md:'Markdown',\n    html:'HTML', htm:'HTML', css:'CSS', scss:'SCSS', sh:'Shell', bash:'Bash',\n    yaml:'YAML', yml:'YAML', toml:'TOML', env:'Env', dockerfile:'Dockerfile',\n    vue:'Vue', svelte:'Svelte', node:'Node'\n  };\n  return map[ext] || (ext ? ext.toUpperCase() : 'Text');\n}\n\nconst DEFAULT_CHECKLIST = [\n  { id:1, text:'Upload overnight / new files', done:false },\n  { id:2, text:'Review File Vault categories', done:false },\n  { id:3, text:'Run Daily Training Session for Mia', done:false },\n  { id:4, text:'Check LiveAvatar / Fan Studio readiness', done:false },\n  { id:5, text:'Produce or edit content (CapCut / scripts)', done:false },\n  { id:6, text:'Deploy finished assets to www.heymia.lensflow.au', done:false },\n  { id:7, text:'Log evening notes & set tomorrow priorities', done:false },\n];\n\nfunction seedDemoVault() {\n  if (state.files.length) return;\n  const demo = [\n    { name: 'work-active.html', type: 'text/html', category: 'code', size: 158433 },\n    { name: 'play-active.html', type: 'text/html', category: 'code', size: 48200 },\n    { name: 'glimr-landing.html', type: 'text/html', category: 'marketing', size: 18440 },\n    { name: 'mia-brand-voice.md', type: 'text/markdown', category: 'scripts', size: 4200 },\n    { name: 'jess-bedroom-intro.txt', type: 'text/plain', category: 'fanstudio', size: 1800 },\n    { name: 'lensflow-4k-promo.mp4', type: 'video/mp4', category: 'lensflow', size: 128000000 },\n    { name: 'elevenlabs-voice.mp3', type: 'audio/mpeg', category: 'scripts', size: 2400000 },\n    { name: 'stripe-prices.json', type: 'application/json', category: 'finance', size: 1280 },\n    { name: 'github-deploy.sh', type: 'text/x-sh', category: 'code', size: 960 },\n  ];\n  demo.forEach((d, i) => {\n    const isText = /html|markdown|plain|json|sh/.test(d.type);\n    const body = isText\n      ? ('<!doctype html><html><head><meta charset=\"utf-8\"><title>' + d.name + '</title></head><body style=\"font-family:system-ui;background:#07060a;color:#f8fafc;padding:48px\"><p style=\"color:#ec4899\">HEYMIA</p><h1>' + d.name + '</h1><p>Demo build in the command center. Publish / Deploy records success or fail.</p></body></html>')\n      : '';\n    const blob = isText ? new Blob([body], { type: d.type.indexOf('html') >= 0 ? 'text/html' : 'text/plain' }) : null;\n    state.files.push({\n      id: 'demo-' + i,\n      name: d.name,\n      type: d.type,\n      size: d.size,\n      category: d.category,\n      url: blob ? URL.createObjectURL(blob) : '',\n      fileObj: blob,\n      status: 'ready',\n    });\n  });\n}\n\n// ========== INIT ==========\ndocument.addEventListener('DOMContentLoaded', () => {\n  try { setupDrop(); } catch (e) {}\n  try { seedDemoVault(); } catch (e) {}\n  try { renderCats(); } catch (e) {}\n  try { renderFiles(); } catch (e) {}\n  try { initChecklist(); } catch (e) {}\n  try { renderTraining(); } catch (e) {}\n  try { updateGeminiStatus(); } catch (e) {}\n  try { checkYt(); } catch (e) {}\n  try { checkIg(); } catch (e) {}\n  try {\n    const q = new URLSearchParams(location.search);\n    if (q.get('yt') === 'connected') addMia('YouTube connected (' + (q.get('ch') || 'UC73le_vohvEOka1rjnOh3SQ') + '). Upload from Clips or Marketing.');\n    if (q.get('yt') === 'error') addMia('YouTube connect failed: ' + (q.get('msg') || 'unknown'));\n    if (q.get('ig') === 'connected') addMia('Instagram connected' + (q.get('user') ? ' as @' + q.get('user') : '') + '. You can Post from Clips or Marketing.');\n    if (q.get('ig') === 'error') addMia('Instagram connect failed: ' + (q.get('msg') || 'unknown'));\n  } catch (e) {}\n  try { initMiaControls(); } catch (e) {}\n  try { loadCloudVault(); } catch (e) {}\n  try { loadLastDeploy(); } catch (e) {}\n  try { maybeAutoDailyReport(); } catch (e) {}\n  try { updateQuoteStatus(); renderTriggerPanel(); } catch (e) {}\n  try { switchTool('projects'); } catch (e) {}\n  try { loadMiaHistory(); } catch (e) {}\n  try { paintDockShip(); } catch (e) {}\n});\n\n// ========== MODE / TOOL SWITCH ==========\nfunction switchMode(m) {\n  state.mode = m;\n  document.getElementById('btn-mode-work').className = m==='work' ? 'px-3 py-1.5 rounded-lg text-xs font-bold tab-active' : 'px-3 py-1.5 rounded-lg text-xs font-bold glass-light text-slate-300';\n  document.getElementById('btn-mode-play').className = m==='play' ? 'px-3 py-1.5 rounded-lg text-xs font-bold tab-active' : 'px-3 py-1.5 rounded-lg text-xs font-bold glass-light text-slate-300';\n  if (m === 'play') switchTool('studio');\n  else switchTool('projects');\n}\n\nfunction switchTool(t) {\n  if (t === 'knowledge') try { renderKnowledge(); } catch(e) {}\n  if (t === 'trainer') try { startDailyTrainingSession(); renderPersonalityVideo(); } catch(e) {}\n\n  document.querySelectorAll('[id^=\"tool-\"]').forEach(el => {\n    el.classList.add('hidden');\n    el.classList.remove('flex', 'flex-col');\n  });\n  const panel = document.getElementById('tool-' + t);\n  if (panel) {\n    panel.classList.remove('hidden');\n    if (t === 'vault' || t === 'editor' || t === 'studio' || t === 'cut') panel.classList.add('flex');\n    if (t === 'editor' || t === 'studio' || t === 'cut') panel.classList.add('flex-col');\n  }\n  if (t === 'checklist') renderChecklist();\n  if (t === 'training') renderTraining();\n  if (t === 'deploy') { try { refreshDeployBoard(); } catch (e) {} }\n  if (t === 'sites') { try { renderPublishedSites(); } catch (e) {} }\n  if (t === 'pentad') { try { loadPentads(); } catch (e) {} }\n  if (t === 'projects') { try { renderProducts(); } catch (e) {} }\n  if (t === 'editor') { try { renderMarketing(); } catch (e) {} }\n  if (t === 'cinema') { try { renderCinema(); } catch (e) {} }\n  if (t === 'clips') { try { refreshClips(); } catch (e) {} }\n  if (t === 'editor') { try { checkYt(); checkIg(); } catch (e) {} }\n\n  document.querySelectorAll('.tool-tab').forEach(btn => {\n    const base = 'tool-tab px-3 py-1.5 rounded-lg text-xs font-medium shrink-0 ';\n    btn.className = btn.dataset.tool === t \n      ? base + 'tab-active' \n      : base + 'glass-light text-slate-300';\n  });\n}\n\nasync function askGrokTroubleshoot(question) {\n  const box = document.getElementById('mia-chat');\n  const dropThinking = () => {\n    if (box && box.lastChild && /Asking Grok|Thinking/.test(box.lastChild.textContent || '')) box.removeChild(box.lastChild);\n  };\n  const ctx = { href: location.href, files: state.files.length, mode: state.miaMode, worker: WORKER_BASE };\n  const urls = [location.origin + '/api/grok', String(WORKER_BASE || '').replace(/\\/$/, '') + '/api/grok'];\n  for (const url of urls) {\n    if (!/^https?:/i.test(url)) continue;\n    try {\n      const res = await fetch(url, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ question, message: question, context: JSON.stringify(ctx) }),\n      });\n      const ct = res.headers.get('content-type') || '';\n      if (!ct.includes('json')) continue;\n      const data = await res.json();\n      dropThinking();\n      const reply = data.reply || data.text || data.error;\n      if (reply) { addMia('Grok: ' + reply); return; }\n    } catch (e) {}\n  }\n  dropThinking();\n  addMia('Grok is not wired yet. Cloudflare → Worker heymia → Settings → Variables and Secrets → add XAI_API_KEY from console.x.ai then click Grok and ask again.');\n}\n\n// ========== MIA CHAT ==========\nfunction addMia(text, role = 'mia') {\n  try {\n    const _t = String(arguments[0] || '');\n    const isUser = arguments[1] === 'user';\n    if (!isUser && _t) {\n      if (/I hear you|Tell me more|What do you need right now|I.m here\\./i.test(_t)) trackMiaSignal('fallback');\n      else trackMiaSignal('reply', _t.length);\n      if (/\\b(no\\.|wrong\\.|don.t\\b)/i.test(_t)) trackMiaSignal('aggression');\n      try { scanReplyForBehavior(_t); } catch (e) {}\n    }\n  } catch (e) {}\n\n  const box = document.getElementById('mia-chat');\n  const div = document.createElement('div');\n  div.className = (role === 'user' ? 'msg-user ml-6' : 'msg-mia mr-4') + ' rounded-2xl p-3 fade-in';\n  div.innerHTML = `<div class=\"font-bold text-[10px] mb-1 ${role==='user'?'text-slate-400 text-right':'text-pink-400'}\">${role==='user'?'You':'Mia'}</div>${escapeHtml(text)}`;\n  box.appendChild(div);\n  box.scrollTop = box.scrollHeight;\n}\n\nasync function sendToMia(e) {\n  e.preventDefault();\n  const input = document.getElementById('mia-input');\n  const text = input.value.trim();\n  if (!text) return;\n  addMia(text, 'user');\n  try { trackMiaSignal('message'); if (/\\b(wrong|not jess|not mia|stop|aggressive)\\b/i.test(text)) trackMiaSignal('correction'); } catch(e) {}\n  input.value = '';\n\n  // Local: only hard UI commands. Everything else goes to Mia so she can actually answer.\n  const lower = text.toLowerCase();\n  if (lower.includes('activate upgrade') || lower.startsWith('upgrade work')) {\n    const f = state.files.slice().reverse().find(x => x.key && /\\.html$/i.test(x.name || ''));\n    if (f) activateUpgrade(f.key, 'work');\n    else addMia('Upload an .html upgrade file first.');\n    return;\n  }\n  if (lower.includes('ui status')) { uiStatus(); return; }\n  if (lower.includes('reset ui') || lower.includes('upgrade reset')) { resetUpgrade('work'); return; }\n  if (lower.includes('live avatar') || lower.includes('start session')) switchTool('studio');\n  if (lower.includes('open vault') || lower.includes('show files')) switchTool('vault');\n  if (lower.includes('checklist')) switchTool('checklist');\n  if (/\\btraining\\b/.test(lower)) switchTool('training');\n  if (/\\b(organis|organiz|sort the vault)\\b/i.test(text)) switchTool('vault');\n  if (/\\b(clip|reel|tiktok|capcut|make a post|make a video|make a clip)\\b/i.test(text)) {\n    switchTool('editor');\n    const brief = document.getElementById('mkt-brief');\n    if (brief && !brief.value) brief.value = text;\n  }\n  if (/\\b(crop|trim|mute|ffmpeg|magic eraser|erase|cut bench|edit (the )?(video|audio|clip|image))\\b/i.test(text)) {\n    switchTool('cut');\n  }\n  if (/\\b(30[\\s-]?min|movie|film|cinema|screenplay|shot list|featurette)\\b/i.test(text)) {\n    switchTool('cinema');\n    const prem = document.getElementById('cin-premise');\n    if (prem && !prem.value) prem.value = text;\n  }\n  if (/\\b(make (a |the )?(video|clip)|render (a |the )?(video|clip)|4k clip|imagine video)\\b/i.test(text)) {\n    switchTool('clips');\n    const s = document.getElementById('clip-story');\n    if (s && !s.value) s.value = text;\n  }\n  if (/\\b(web\\s?site|landing\\s?page|design (a |the )?site)\\b/i.test(text)) {\n    switchTool('sites');\n    const brief = document.getElementById('site-brief');\n    if (brief && !brief.value) brief.value = text;\n  }\n\n  if (!state.miaTurns) state.miaTurns = [];\n  state.miaTurns.push({ role: 'user', content: text });\n\n  addMia('Thinking…');\n  const payloads = JSON.stringify({\n    message: text,\n    messages: (state.miaTurns || [{ role: 'user', content: text }]).slice(-16),\n    agent: 'Mia',\n    mode: 'work',\n    companion: 'mia',\n  });\n  const chatUrls = [location.origin + '/api/chat'];\n  if (WORKER_BASE) chatUrls.push(WORKER_BASE.replace(/\\/$/, '') + '/chat');\n  try {\n    for (const url of chatUrls) {\n      try {\n        const wres = await fetch(url, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: payloads,\n        });\n        const ct = wres.headers.get('content-type') || '';\n        if (!wres.ok || !ct.includes('json')) continue;\n        const wdata = await wres.json();\n        const box = document.getElementById('mia-chat');\n        if (box.lastChild && box.lastChild.textContent.includes('Thinking')) box.removeChild(box.lastChild);\n        const reply = wdata.reply || wdata.response;\n        if (!reply) continue;\n        addMia(reply);\n        if (!state.miaTurns) state.miaTurns = [];\n        state.miaTurns.push({ role: 'assistant', content: reply });\n        persistMiaTurns();\n        speakMiaText(reply);\n        if (wdata.site && wdata.site.url) {\n          showDeployResult({ ok: true, name: wdata.site.slug || 'site', url: wdata.site.url, at: new Date().toISOString() });\n          addMia('Live URL: ' + wdata.site.url);\n        }\n        return;\n      } catch (e) {}\n    }\n  } catch (e) { /* fall through to Gemini */ }\n\n  // Gemini path\n  if (state.geminiKey) {\n    try {\n      const trainingContext = state.trainingNotes.length\n        ? '\\n\\nDaily training notes you must follow:\\n' + state.trainingNotes.map(n => '- ' + n.text).join('\\n')\n        : '';\n      const system = buildMiaSystem();\n      const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent?key=${state.geminiKey}`, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          contents: [{ role: 'user', parts: [{ text: system + '\\n\\nUser: ' + text }] }],\n          generationConfig: { temperature: 0.7, maxOutputTokens: 400 }\n        })\n      });\n      const data = await res.json();\n      // Remove the temporary \"Thinking…\" bubble\n      const box = document.getElementById('mia-chat');\n      if (box.lastChild && box.lastChild.textContent.includes('Thinking')) box.removeChild(box.lastChild);\n      const reply = data.candidates?.[0]?.content?.parts?.[0]?.text || 'I could not generate a reply. Check the Gemini key in Settings.';\n      addMia(reply);\n      speakMiaText(reply);\n    } catch (err) {\n      const box = document.getElementById('mia-chat');\n      if (box.lastChild && box.lastChild.textContent.includes('Thinking')) box.removeChild(box.lastChild);\n      addMia('Gemini request failed. Check your API key and network. Falling back to local help.');\n      localFallback(text);\n    }\n  } else {\n    localFallback(text);\n  }\n}\n\nfunction localFallback(text) {\n  const lower = text.toLowerCase();\n  if (lower.includes('upload') || lower.includes('file')) {\n    addMia('Drop files on the upload zone. I will auto-categorise and route them. Add a Gemini key in Settings for full AI assistance.');\n  } else if (lower.includes('deploy') || lower.includes('publish')) {\n    addMia('Open the Deploy tab. Select files in Vault and click Publish.');\n    switchTool('deploy');\n  } else if (lower.includes('workflow')) {\n    switchTool('workflow');\n    addMia('Here is the daily workflow.');\n  } else {\n    addMia('I can help with uploads, routing, LiveAvatar, CapCut, Find & Replace, Workflow, Checklist and Daily Training. Add your Gemini API key in Settings (gear icon) for full conversational AI.');\n  }\n}\n\nfunction clearChat() {\n  document.getElementById('mia-chat').innerHTML = '';\n  addMia('Chat cleared. How can I help?');\n}\n\n// ========== SETTINGS / VARIABLES & SECRETS ==========\nfunction maskKey(v) {\n  if (!v) return '';\n  if (v.length < 8) return '••••';\n  return '••••••••' + v.slice(-4);\n}\nfunction recogniseSecret(raw) {\n  const v = String(raw || '').trim();\n  if (!v || v.startsWith('••')) return { id: null, ok: false, label: 'empty' };\n  if (/^AIza[0-9A-Za-z_\\-]{20,}$/.test(v)) return { id: 'gemini', ok: true, label: 'Gemini / Google AI' };\n  if (/^https?:\\/\\/.+/i.test(v)) return { id: 'worker', ok: true, label: 'Worker / site URL' };\n  if (/^sk_(live|test)_[A-Za-z0-9]+/.test(v) || /^pk_(live|test)_/.test(v)) return { id: 'stripe', ok: true, label: 'Stripe' };\n  if (/^sk-ant-/.test(v)) return { id: 'openai', ok: true, label: 'Anthropic Claude' };\n  if (/^gsk_/.test(v)) return { id: 'openai', ok: true, label: 'Groq' };\n  if (/^sk-proj-/.test(v) || /^sk-[A-Za-z0-9]{20,}$/.test(v)) return { id: 'openai', ok: true, label: 'OpenAI' };\n  if (/^(ghp_|github_pat_|gho_|ghu_)/.test(v)) return { id: 'github', ok: true, label: 'GitHub token' };\n  if (/^xi[-_]?[A-Za-z0-9]{16,}$/i.test(v)) return { id: 'elevenlabs', ok: true, label: 'ElevenLabs' };\n  if (/^[a-f0-9]{32}$/i.test(v)) return { id: 'cf_account', ok: true, label: 'Cloudflare Account ID' };\n  if (/^[a-f0-9]{37}$/i.test(v)) return { id: 'cf_token', ok: true, label: 'Cloudflare Global API key' };\n  if (/^[A-Za-z0-9_\\-]{40,}$/.test(v) && !v.includes(' ')) return { id: 'cf_token', ok: true, label: 'Cloudflare API token (likely)' };\n  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v)) return { id: 'liveavatar', ok: true, label: 'LiveAvatar / UUID key' };\n  if (v.length >= 20) return { id: 'liveavatar', ok: true, label: 'LiveAvatar / generic API key' };\n  return { id: null, ok: false, label: 'Unknown format' };\n}\nfunction markRec(id, rec) {\n  const el = document.getElementById('rec-' + id);\n  if (!el) return;\n  if (!rec || !rec.id) { el.textContent = '—'; el.className = 'text-slate-600'; return; }\n  el.textContent = rec.ok ? 'recognised: ' + rec.label : rec.label;\n  el.className = rec.ok ? 'text-emerald-400' : 'text-rose-400';\n}\nfunction fieldMap() {\n  return {\n    gemini: document.getElementById('gemini-key-input'),\n    worker: document.getElementById('worker-url-input'),\n    cf_token: document.getElementById('cf-token-input'),\n    cf_account: document.getElementById('cf-account-input'),\n    stripe: document.getElementById('stripe-key-input'),\n    liveavatar: document.getElementById('liveavatar-key-input'),\n    elevenlabs: document.getElementById('eleven-key-input'),\n    openai: document.getElementById('openai-key-input'),\n  };\n}\nfunction onSecretPaste(val) {\n  const rec = recogniseSecret(val);\n  const hint = document.getElementById('secret-paste-hint');\n  if (!val.trim()) {\n    if (hint) { hint.textContent = 'Gemini, Stripe, OpenAI, Anthropic, Groq, GitHub, Cloudflare, ElevenLabs, LiveAvatar, Worker URL.'; hint.className = 'text-[10px] mt-1 text-slate-500'; }\n    return;\n  }\n  if (hint) {\n    hint.textContent = rec.ok ? ('Recognised as ' + rec.label + ' — dropped into the matching field.') : ('Not recognised yet — paste a full key.');\n    hint.className = 'text-[10px] mt-1 ' + (rec.ok ? 'text-emerald-400' : 'text-amber-300');\n  }\n  if (!rec.id) return;\n  const fields = fieldMap();\n  const input = fields[rec.id];\n  if (input) input.value = val.trim();\n  markRec(rec.id, rec);\n  if (rec.id === 'github') {\n    state.githubToken = val.trim();\n    localStorage.setItem('heymia_github', val.trim());\n  }\n}\nfunction fillSecretFields() {\n  const g = document.getElementById('gemini-key-input');\n  if (g) g.value = maskKey(state.geminiKey);\n  const w = document.getElementById('worker-url-input');\n  if (w) w.value = WORKER_BASE || '';\n  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = maskKey(val); };\n  set('cf-token-input', state.cfToken);\n  const acc = document.getElementById('cf-account-input');\n  if (acc) acc.value = state.cfAccount || '';\n  set('stripe-key-input', state.stripeKey);\n  set('liveavatar-key-input', state.liveavatarKey);\n  set('eleven-key-input', state.elevenKey);\n  set('openai-key-input', state.openaiKey);\n  const paste = document.getElementById('secret-paste');\n  if (paste) paste.value = '';\n  markRec('gemini', state.geminiKey ? recogniseSecret(state.geminiKey) : null);\n  markRec('worker', WORKER_BASE ? recogniseSecret(WORKER_BASE) : null);\n  markRec('cf_token', state.cfToken ? recogniseSecret(state.cfToken) : null);\n  markRec('cf_account', state.cfAccount ? recogniseSecret(state.cfAccount) : null);\n  markRec('stripe', state.stripeKey ? recogniseSecret(state.stripeKey) : null);\n  markRec('liveavatar', state.liveavatarKey ? recogniseSecret(state.liveavatarKey) : null);\n  markRec('elevenlabs', state.elevenKey ? recogniseSecret(state.elevenKey) : null);\n  markRec('openai', state.openaiKey ? recogniseSecret(state.openaiKey) : null);\n}\nfunction readIfUnmasked(el, current) {\n  if (!el) return current;\n  const v = el.value.trim();\n  if (!v || v.startsWith('••')) return current;\n  return v;\n}\nfunction toggleSettings() {\n  const m = document.getElementById('settings-modal');\n  m.classList.toggle('opacity-0');\n  m.classList.toggle('pointer-events-none');\n  if (!m.classList.contains('opacity-0')) {\n    fillSecretFields();\n    updateGeminiStatus();\n  }\n}\nfunction saveSettings() {\n  state.geminiKey = readIfUnmasked(document.getElementById('gemini-key-input'), state.geminiKey);\n  state.cfToken = readIfUnmasked(document.getElementById('cf-token-input'), state.cfToken);\n  state.cfAccount = readIfUnmasked(document.getElementById('cf-account-input'), state.cfAccount);\n  state.stripeKey = readIfUnmasked(document.getElementById('stripe-key-input'), state.stripeKey);\n  state.liveavatarKey = readIfUnmasked(document.getElementById('liveavatar-key-input'), state.liveavatarKey);\n  state.elevenKey = readIfUnmasked(document.getElementById('eleven-key-input'), state.elevenKey);\n  state.openaiKey = readIfUnmasked(document.getElementById('openai-key-input'), state.openaiKey);\n  const workerUrl = (document.getElementById('worker-url-input') || {}).value;\n  if (workerUrl && workerUrl.trim()) {\n    WORKER_BASE = workerUrl.trim();\n    localStorage.setItem('heymia_worker', WORKER_BASE);\n  }\n  const store = [\n    ['heymia_gemini', state.geminiKey],\n    ['heymia_cf_token', state.cfToken],\n    ['heymia_cf_account', state.cfAccount],\n    ['heymia_stripe', state.stripeKey],\n    ['heymia_liveavatar', state.liveavatarKey],\n    ['heymia_eleven', state.elevenKey],\n    ['heymia_openai', state.openaiKey],\n  ];\n  store.forEach(([k, v]) => { if (v) localStorage.setItem(k, v); });\n  const recognised = [];\n  if (state.geminiKey) recognised.push('Gemini ' + recogniseSecret(state.geminiKey).label);\n  if (state.stripeKey) recognised.push('Stripe');\n  if (state.cfToken) recognised.push('Cloudflare token');\n  if (state.liveavatarKey) recognised.push('LiveAvatar');\n  if (state.elevenKey) recognised.push('ElevenLabs');\n  if (state.openaiKey) recognised.push(recogniseSecret(state.openaiKey).label);\n  updateGeminiStatus();\n  toggleSettings();\n  addMia(recognised.length ? ('Secrets saved: ' + recognised.join(', ') + '.') : 'Settings saved. Paste a key in the gear panel.');\n}\nasync function checkWorkerEnv() {\n  const box = document.getElementById('env-check-result');\n  if (box) { box.classList.remove('hidden'); box.textContent = 'Checking Worker…'; }\n  const base = WORKER_BASE.replace(/\\/$/, '');\n  const lines = [];\n  const browser = [\n    ['Gemini (browser)', !!state.geminiKey, state.geminiKey ? recogniseSecret(state.geminiKey).label : 'missing'],\n    ['Cloudflare token (browser)', !!state.cfToken, state.cfToken ? 'set' : 'missing'],\n    ['Cloudflare account (browser)', !!state.cfAccount, state.cfAccount ? 'set' : 'missing'],\n    ['Stripe (browser)', !!state.stripeKey, state.stripeKey ? recogniseSecret(state.stripeKey).label : 'missing'],\n    ['LiveAvatar (browser)', !!state.liveavatarKey, state.liveavatarKey ? 'set' : 'missing'],\n    ['ElevenLabs (browser)', !!state.elevenKey, state.elevenKey ? 'set' : 'missing'],\n    ['OpenAI/other (browser)', !!state.openaiKey, state.openaiKey ? recogniseSecret(state.openaiKey).label : 'missing'],\n  ];\n  lines.push('Browser secrets:');\n  browser.forEach(([n, ok, extra]) => lines.push((ok ? '✓ ' : '✗ ') + n + ' — ' + extra));\n  try {\n    let data = null;\n    for (const path of ['/env-check', '/api/status', '/?format=json']) {\n      try {\n        const res = await fetch(base + path);\n        const ct = res.headers.get('content-type') || '';\n        if (!res.ok || !ct.includes('json')) continue;\n        data = await res.json();\n        lines.push('', 'Worker ' + path + ':');\n        break;\n      } catch (e) {}\n    }\n    if (!data) {\n      lines.push('', 'Worker did not return JSON. Deploy v3 so /api/status and /env-check work.');\n    } else {\n      const sc = data.secrets_configured || data.checks || {};\n      const keys = ['gemini', 'ai', 'liveavatar', 'stripe', 'workers_ai', 'vault'];\n      keys.forEach((k) => {\n        const v = sc[k] !== undefined ? sc[k] : data[k];\n        if (v === undefined) return;\n        const ok = v === true || v === 'set' || v === 'bound' || v === 'ok';\n        lines.push((ok ? '✓ ' : '✗ ') + k + ' = ' + JSON.stringify(v));\n      });\n      if (data.ai_model) lines.push('model: ' + data.ai_model);\n      if (data.version) lines.push('version: ' + data.version);\n      if (data.missingRecommended && data.missingRecommended.length) {\n        lines.push('Missing on Worker: ' + data.missingRecommended.join(', '));\n      }\n    }\n  } catch (e) {\n    lines.push('Worker check failed: ' + (e.message || e));\n  }\n  if (box) box.textContent = lines.join('\\n');\n  addMia(lines.filter(l => l.startsWith('✗')).length ? 'Some keys are missing. Open the gear and paste them.' : 'Secrets look present in the browser. Worker keys still need Cloudflare Variables if ✗.');\n}\nfunction updateGeminiStatus() {\n  const dot = document.getElementById('gemini-status-dot');\n  const txt = document.getElementById('gemini-status-text');\n  if (!dot) return;\n  const rec = state.geminiKey ? recogniseSecret(state.geminiKey) : null;\n  if (state.geminiKey && rec && rec.ok) {\n    dot.className = 'w-2 h-2 rounded-full bg-emerald-400';\n    txt.textContent = 'Gemini: active · ' + rec.label;\n    txt.className = 'text-emerald-400';\n  } else if (state.geminiKey) {\n    dot.className = 'w-2 h-2 rounded-full bg-amber-400';\n    txt.textContent = 'Gemini: saved but format looks off';\n    txt.className = 'text-amber-300';\n  } else {\n    dot.className = 'w-2 h-2 rounded-full bg-slate-500';\n    txt.textContent = 'Gemini: not configured';\n    txt.className = 'text-slate-400';\n  }\n}\n\n// ========== CHECKLIST ==========\nfunction initChecklist() {\n  const today = new Date().toDateString();\n  if (!state.checklist || state.checklist.date !== today) {\n    state.checklist = { date: today, items: DEFAULT_CHECKLIST.map(i => ({...i})) };\n    localStorage.setItem('heymia_checklist', JSON.stringify(state.checklist));\n  }\n  document.getElementById('checklist-date').textContent = state.checklist.date;\n  renderChecklist();\n}\nfunction renderChecklist() {\n  const box = document.getElementById('checklist-items');\n  if (!box) return;\n  box.innerHTML = state.checklist.items.map(item => `\n    <label class=\"flex items-center gap-3 p-3 rounded-xl bg-white/5 hover:bg-white/8 cursor-pointer\">\n      <input type=\"checkbox\" ${item.done?'checked':''} onchange=\"toggleCheck(${item.id})\" class=\"rounded border-white/20\">\n      <span class=\"text-sm ${item.done?'line-through text-slate-500':''}\">${item.text}</span>\n    </label>`).join('');\n  const done = state.checklist.items.filter(i => i.done).length;\n  document.getElementById('checklist-progress').textContent = `${done} / ${state.checklist.items.length} complete`;\n}\nfunction toggleCheck(id) {\n  const item = state.checklist.items.find(i => i.id === id);\n  if (item) item.done = !item.done;\n  localStorage.setItem('heymia_checklist', JSON.stringify(state.checklist));\n  renderChecklist();\n}\nfunction addChecklistItem() {\n  const text = prompt('New checklist item:');\n  if (!text) return;\n  const id = Date.now();\n  state.checklist.items.push({ id, text, done: false });\n  localStorage.setItem('heymia_checklist', JSON.stringify(state.checklist));\n  renderChecklist();\n}\nfunction resetChecklist() {\n  state.checklist = { date: new Date().toDateString(), items: DEFAULT_CHECKLIST.map(i => ({...i})) };\n  localStorage.setItem('heymia_checklist', JSON.stringify(state.checklist));\n  document.getElementById('checklist-date').textContent = state.checklist.date;\n  renderChecklist();\n  addMia('Checklist reset for today.');\n}\n\n// ========== TRAINING ==========\nfunction renderTraining() {\n  const log = document.getElementById('training-log');\n  if (log) {\n    log.innerHTML = state.trainingNotes.length\n      ? state.trainingNotes.map((n, i) => `\n    <div class=\"p-3 rounded-xl bg-white/5 flex justify-between gap-2\">\n      <div><div class=\"text-[10px] text-slate-500 mb-0.5\">${n.date}</div>${escapeHtml(n.text)}</div>\n      <button onclick=\"removeTraining(${i})\" class=\"text-slate-500 hover:text-red-400 text-xs shrink-0\">✕</button>\n    </div>`).join('')\n      : '<div class=\"text-slate-500\">Personal notes land here. The 7-day camp is already in the vault.</div>';\n  }\n  loadCampBoard();\n}\nasync function loadCampBoard() {\n  const board = document.getElementById('camp-board');\n  const report = document.getElementById('mem-report');\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/training')).json();\n    if (board && d.camp7) {\n      board.innerHTML = d.camp7.map((x) =>\n        `<div class=\"p-2 rounded-xl bg-white/5\"><div class=\"font-bold text-pink-300\">Day ${x.day} · ${escapeHtml(x.title)}</div><div class=\"text-slate-400 mt-0.5\">${escapeHtml(x.pass)}</div></div>`\n      ).join('');\n    }\n  } catch (e) {\n    if (board) board.textContent = 'Camp loads after Cloudflare ships 4.2.0.';\n  }\n  try {\n    const r = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/memory?report=1')).json();\n    if (report) report.textContent = 'Memory: ' + (r.chat_turns || 0) + ' chat turns · ' + (r.memories || 0) + ' stored facts · 12-month keep. Chat history is on the Worker, not only this phone.';\n  } catch (e) {}\n}\nfunction saveTraining() {\n  const input = document.getElementById('training-input');\n  const text = input.value.trim();\n  if (!text) return;\n  state.trainingNotes.unshift({ text, date: new Date().toLocaleString() });\n  localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n  try { fetch((WORKER_BASE||location.origin).replace(/\\/$/, '') + '/api/memory', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ key: 'train_'+Date.now(), value: text, category: 'training' }) }); } catch(e) {}\n  input.value = '';\n  renderTraining();\n  addMia('Training note saved. I will follow it in every future reply' + (state.geminiKey ? ' (Gemini active).' : '.'));\n}\nfunction removeTraining(i) {\n  state.trainingNotes.splice(i, 1);\n  localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n  renderTraining();\n}\nfunction clearTraining() {\n  if (!confirm('Clear all training notes?')) return;\n  state.trainingNotes = [];\n  localStorage.setItem('heymia_training', '[]');\n  renderTraining();\n  addMia('All training notes cleared.');\n}\n\n// ========== FILE HANDLING ==========\nfunction setupDrop() {\n  const zone = document.getElementById('drop-zone');\n  const input = document.getElementById('file-input');\n  zone.onclick = () => input.click();\n  zone.ondragover = e => { e.preventDefault(); zone.classList.add('dragover'); };\n  zone.ondragleave = () => zone.classList.remove('dragover');\n  zone.ondrop = e => { e.preventDefault(); zone.classList.remove('dragover'); handleFiles(e.dataTransfer.files); };\n  input.onchange = e => handleFiles(e.target.files);\n}\n\nasync function handleFiles(list) {\n  if (!list || list.length === 0) return;\n  const statusEl = document.getElementById('upload-status');\n  statusEl.classList.remove('hidden');\n  statusEl.textContent = `Uploading ${list.length} file(s)…`;\n  statusEl.className = 'text-[10px] text-center text-pink-400';\n\n  let done = 0;\n  for (const file of list) {\n    const id = 'f' + Date.now() + Math.random().toString(36).slice(2,6);\n    const cat = guessCat(file.name, file.type);\n    const entry = {\n      id, name: file.name, type: file.type || 'application/octet-stream',\n      size: file.size, category: cat, url: URL.createObjectURL(file),\n      fileObj: file, status: 'uploaded'\n    };\n    state.files.push(entry);\n    addMia(`Received “${file.name}” (${(file.size/1024).toFixed(1)} KB). Auto-tagged → ${catName(cat)}.`);\n\n    // Upload to R2 cloud vault + route\n    try {\n      const up = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/files', {\n        method: 'POST',\n        headers: {\n          'Content-Type': file.type || 'application/octet-stream',\n          'X-File-Name': file.name,\n          'X-Category': cat,\n        },\n        body: file,\n      });\n      if (up.ok) {\n        const data = await up.json();\n        entry.key = data.key;\n        saveCatOverride(data.key, cat);\n        entry.cloudUrl = WORKER_BASE.replace(/\\/$/, '') + '/files?key=' + encodeURIComponent(data.key);\n        entry.url = entry.cloudUrl;\n        addMia(`Cloud saved: “${file.name}” → R2`);\n        if (/\\.html$/i.test(file.name) || cat === 'upgrade') {\n          entry._offerUpgrade = true;\n          addMia('HTML uploaded. Shell: upgrade work ' + (entry.key || '') + '  — or say “activate upgrade”.');\n        }\n        if (/\\.mp4$/i.test(file.name) || (file.type || '').startsWith('video/')) {\n          addMia('Video is in the vault. Say “convert this clip to html” or open it and tap Convert MP4 to HTML page.');\n        }\n      } else {\n        const err = await up.json().catch(() => ({}));\n        addMia(`R2 upload issue: ${err.error || up.status}. Kept local copy.`);\n      }\n    } catch (err) {\n      addMia(`Local only for “${file.name}” (cloud unreachable).`);\n    }\n    try {\n      const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/route', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ fileName: file.name, fileType: file.type, category: cat })\n      });\n      if (res.ok) {\n        const data = await res.json();\n        entry.routedTo = data.destination;\n        addMia(`Route: ${data.destination} — ${data.reason}`);\n      }\n    } catch (err) {}\n    done++;\n    statusEl.textContent = `Processed ${done}/${list.length}`;\n  }\n\n  statusEl.textContent = `✓ ${list.length} file(s) uploaded & ready in File Vault`;\n  statusEl.className = 'text-[10px] text-center text-emerald-400';\n  setTimeout(() => statusEl.classList.add('hidden'), 4000);\n\n  renderCats();\n  renderFiles();\n  // Auto-switch to vault so user sees the files immediately\n  switchTool('vault');\n}\n\nfunction guessCat(name, type) {\n  const n = name.toLowerCase();\n  const ext = fileExt(name);\n  if (n.includes('bedroom')||n.includes('dungeon')||n.includes('bdsm')||n.includes('fan')||n.includes('jess')) return 'fanstudio';\n  if (n.includes('lens')||n.includes('4k')||n.includes('avatar')||type.startsWith('video/')) return 'lensflow';\n  if (CODE_EXTS.has(ext) || /package.json|tsconfig|webpack|vite.config|next.config|node_modules/i.test(n)) return 'code';\n  if (n.includes('prompt')||n.includes('script')||n.endsWith('.txt')||n.endsWith('.md')) return 'scripts';\n  if (n.includes('ad')||n.includes('promo')||n.includes('marketing')||n.includes('banner')) return 'marketing';\n  if (n.includes('legal')||n.includes('terms')||n.includes('privacy')) return 'legal';\n  if (n.includes('invoice')||n.includes('finance')||n.includes('payment')) return 'finance';\n  if (n.includes('jess')||n.includes('companion')) return 'jess';\n  return 'unsorted';\n}\n\n/** Category overrides remembered in this browser (the R2 listing does not return X-Category). */\nfunction loadCatOverrides() {\n  try { return JSON.parse(localStorage.getItem('heymia_filecats') || '{}') || {}; } catch (e) { return {}; }\n}\nfunction saveCatOverride(key, cat) {\n  if (!key || !cat || cat === 'unsorted') return;\n  try {\n    const map = loadCatOverrides();\n    map[key] = cat;\n    localStorage.setItem('heymia_filecats', JSON.stringify(map));\n  } catch (e) {}\n}\n/** Cloud fallback: filename rules, then media hints, then MIME type, so nothing sits in Unsorted forever. */\nfunction guessCatFromCloud(name, type) {\n  const n = String(name || '');\n  const c = guessCat(n, type || '');\n  if (c !== 'unsorted') return c;\n  if (/screenshot|screen shot|photo|selfie|thumbnail|\\.(png|jpe?g|webp|gif|heic|bmp|svg|mp4|mov|webm|m4v|mp3|wav|m4a)$/i.test(n)) return 'lensflow';\n  const t = String(type || '').toLowerCase();\n  if (t.indexOf('image/') === 0 || t.indexOf('video/') === 0 || t.indexOf('audio/') === 0) return 'lensflow';\n  if (t.indexOf('text/') === 0 || t.indexOf('json') > -1 || t.indexOf('javascript') > -1 || t.indexOf('xml') > -1) return 'code';\n  return 'unsorted';\n}\n\nconst PRODUCTS_UI = [\n  { slug:'sovereignquant', name:'Sovereign Quant', urls:[], blurb:'Multi-agent quant system' },\n  { slug:'lensflow', name:'LensFlow Dating', urls:['https://lensflow.com.au'], blurb:'Dating site · companions · Play' },\n  { slug:'missingcash', name:'Missing Cash', urls:['https://missingcash.com.au'], blurb:'Unclaimed money finder' },\n  { slug:'bartermint', name:'Bartermint', urls:['https://bartermint.polsia.app','https://bartermint.onhercules.app'], blurb:'Barter marketplace' },\n  { slug:'realestate', name:'LensFlow Real Estate', urls:[], blurb:'Pipeline + mobile' },\n];\n\nasync function renderProducts() {\n  const grid = document.getElementById('product-grid');\n  if (!grid) return;\n  let remote = PRODUCTS_UI;\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/products');\n    const data = await res.json();\n    if (data.products && data.products.length) remote = data.products;\n  } catch (e) {}\n  grid.innerHTML = remote.map((p) => {\n    const n = p.files != null ? p.files : state.files.filter((f) => fileProject(f) === p.slug).length;\n    const links = (p.urls || []).map((u) => `<a class=\"text-pink-300 underline\" href=\"${u}\" target=\"_blank\" rel=\"noopener\">${u.replace(/^https?:\\/\\//,'')}</a>`).join('<br>');\n    const social = ['facebook','instagram','tiktok','x'].map((id) => `<span class=\"text-[9px] uppercase tracking-wide text-slate-500\">${id}</span>`).join(' · ');\n    return `<button onclick=\"openProduct('${p.slug}')\" class=\"text-left glass rounded-2xl p-4 border border-white/10 hover:border-pink-500/40\">\n      <div class=\"text-sm font-bold\">${p.name}</div>\n      <div class=\"text-[11px] text-slate-400 mt-1\">${p.blurb || ''}</div>\n      <div class=\"text-[10px] text-pink-300 mt-2\">${n} file${n===1?'':'s'}</div>\n      <div class=\"text-[10px] mt-2 leading-relaxed\">${links || 'No live URL yet'}</div>\n      <div class=\"mt-2\">${social}</div>\n    </button>`;\n  }).join('');\n}\n\nfunction openProduct(slug) {\n  const p = PRODUCTS_UI.find((x) => x.slug === slug) || { slug, name: slug };\n  const files = state.files.filter((f) => fileProject(f) === slug);\n  const box = document.getElementById('product-files');\n  box.classList.remove('hidden');\n  box.innerHTML = `<div class=\"glass rounded-2xl p-4 border border-white/10\">\n    <div class=\"flex justify-between items-center mb-2\">\n      <div class=\"font-bold text-sm\">${p.name}</div>\n      <button class=\"text-[10px] text-slate-400\" onclick=\"document.getElementById('product-files').classList.add('hidden')\">Close</button>\n    </div>\n    ${files.length ? files.map((f) => `<button onclick=\"switchTool('vault');setProject('${slug}');selectFile('${f.id}')\" class=\"block w-full text-left text-xs py-2 border-b border-white/5\">${escapeHtml(f.name)}</button>`).join('') : '<div class=\"text-xs text-slate-400\">No files yet. Drop uploads and say “file this into ' + p.name + '”.</div>'}\n  </div>`;\n}\n\nasync function mintPentadNow() {\n  const name = (document.getElementById('pentad-name').value || 'Pentad').trim();\n  const claim = (document.getElementById('pentad-claim').value || '').trim();\n  const quote = (document.getElementById('pentad-quote').value || '').trim();\n  const st = document.getElementById('pentad-status');\n  st.textContent = 'Minting…';\n  try {\n    const res = await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/pentad', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name, claim, quote }),\n    });\n    const d = await res.json();\n    st.innerHTML = d.ok ? ('Live: <a class=\"text-pink-300 underline\" href=\"' + (d.url || '/5d/') + '\" target=\"_blank\">' + (d.url || '') + '</a>') : (d.error || 'fail');\n    addMia(d.ok ? ('Pentad minted. Five axes. Citation field is in. ' + (d.url || '')) : 'Mint failed');\n    loadPentads();\n  } catch (e) {\n    st.textContent = String(e.message || e);\n  }\n}\nfunction fillPentad(name, claim, quote) {\n  document.getElementById('pentad-name').value = name;\n  document.getElementById('pentad-claim').value = claim;\n  document.getElementById('pentad-quote').value = quote;\n}\nasync function seedPentadsNow() {\n  const st = document.getElementById('pentad-status');\n  if (st) st.textContent = 'Minting Ash and Altar, Missing Cash, HeyMia…';\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/pentad', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ action: 'seed' })\n    })).json();\n    if (st) st.textContent = d.ok ? ('Minted ' + (d.minted || []).length + ' samples') : (d.error || 'fail');\n    loadPentads();\n  } catch (e) {\n    if (st) st.textContent = e.message;\n  }\n}\nasync function loadPentads() {\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/pentad')).json();\n    const box = document.getElementById('pentad-samples');\n    if (box && d.samples) {\n      box.innerHTML = d.samples.map((s) =>\n        `<button type=\"button\" onclick='fillPentad(${JSON.stringify(s.name)},${JSON.stringify(s.claim)},${JSON.stringify(s.quote)})' class=\"text-left glass rounded-xl p-3 border border-white/10\">\n          <div class=\"text-xs font-bold\">${escapeHtml(s.name)}</div>\n          <div class=\"text-[10px] text-slate-500 mt-1 line-clamp-3\">${escapeHtml(s.claim)}</div>\n        </button>`\n      ).join('');\n    }\n    const live = document.getElementById('pentad-live');\n    if (live) {\n      live.innerHTML = (d.items || []).map((i) =>\n        `<a class=\"block text-pink-300 underline\" href=\"${i.url}\" target=\"_blank\">/5d/${escapeHtml(i.slug)}/</a>`\n      ).join('') || 'No live Pentads yet — mint a sample.';\n    }\n  } catch (e) {}\n}\n\nasync function seedProductsNow() {\n  addMia('Seeding the 5 project boards and filing files…');\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/products', { method: 'POST' });\n    const rec = await res.json();\n    if (!rec.ok) throw new Error(rec.error || 'seed failed');\n    addMia('Projects ready: Sovereign Quant, LensFlow Dating, Missing Cash, Bartermint, Real Estate.');\n    state.files = state.files.filter((f) => !f.key);\n    await loadCloudVault();\n    renderProducts();\n  } catch (e) {\n    addMia('Seed failed: ' + (e.message || e) + '. Need Worker v3.4.');\n  }\n}\nfunction fileProject(f) {\n  const k = f.key || '';\n  const m = k.match(/^projects\\/([^/]+)/);\n  const raw = m ? m[1] : (f.project || '');\n  const alias = { 'sovereign-quant':'sovereignquant', 'agent-core':'sovereignquant', 'liveavatar':'lensflow', 'heymia-play':'lensflow', inbox:'heymia', convex:'heymia', 'heymia-work':'heymia' };\n  return alias[raw] || raw || 'heymia';\n}\n\nfunction renderCats() {\n  const list = document.getElementById('cat-list');\n  const plist = document.getElementById('project-list');\n  const projects = {};\n  state.files.forEach((f) => {\n    const p = fileProject(f);\n    projects[p] = (projects[p] || 0) + 1;\n  });\n  if (plist) {\n    const names = Object.keys(projects).sort();\n    plist.innerHTML = names.map((p) => {\n      const on = state.currentProject === p;\n      return `<button onclick=\"setProject('${p}')\" class=\"w-full text-left px-2 py-1.5 rounded-lg text-xs hover:bg-white/5 ${on?'bg-pink-500/15 text-pink-300':''}\">📂 ${p} <span class=\"opacity-50\">${projects[p]}</span></button>`;\n    }).join('') || '<div class=\"text-[10px] text-slate-500 px-2\">No project folders yet.</div>';\n  }\n  list.innerHTML = `<button onclick=\"setCat('all')\" class=\"w-full text-left px-2 py-1.5 rounded-lg text-xs hover:bg-white/5 ${state.currentCat==='all'&&!state.currentProject?'bg-pink-500/15 text-pink-300':''}\">📁 All (${state.files.length})</button>` +\n    CATS.map(c => {\n      const cnt = state.files.filter(f => f.category === c.id).length;\n      return `<button onclick=\"setCat('${c.id}')\" class=\"w-full text-left px-2 py-1.5 rounded-lg text-xs hover:bg-white/5 ${state.currentCat===c.id?'bg-pink-500/15 text-pink-300':''}\">${c.icon} ${c.name} <span class=\"opacity-50\">${cnt}</span></button>`;\n    }).join('');\n}\n\nfunction setProject(id) {\n  state.currentProject = id;\n  state.currentCat = 'all';\n  document.getElementById('cat-label').textContent = 'Project · ' + id;\n  renderCats();\n  renderFiles();\n}\n\nfunction setCat(id) {\n  state.currentCat = id;\n  state.currentProject = '';\n  document.getElementById('cat-label').textContent = id === 'all' ? 'All Files' : catName(id);\n  renderCats();\n  renderFiles();\n}\n\nasync function organizeVaultNow() {\n  addMia('Filing vault into project folders…');\n  showDeployPending('organize_vault');\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/organize', { method: 'POST' });\n    const rec = await res.json();\n    if (!rec.ok) throw new Error(rec.error || 'organize failed');\n    const lines = Object.entries(rec.projects || {}).map(([k, n]) => k + ': ' + n).join(', ');\n    addMia('Filed ' + rec.moved + ' file(s). ' + lines + '. Live UI left in ui/.');\n    showDeployResult({ ok: true, name: 'organize_vault', url: '', at: new Date().toISOString() });\n    state.files = state.files.filter((f) => !f.key);\n    await loadCloudVault();\n  } catch (e) {\n    addMia('Organize failed: ' + (e.message || e) + '. Deploy Worker v3.3 then try again.');\n    showDeployResult({ ok: false, name: 'organize_vault', error: String(e.message || e), at: new Date().toISOString() });\n  }\n}\n\nfunction renderFiles() {\n  let files = state.files;\n  if (state.currentProject) files = files.filter(f => fileProject(f) === state.currentProject);\n  else if (state.currentCat !== 'all') files = files.filter(f => f.category === state.currentCat);\n  const grid = document.getElementById('file-grid');\n  if (!files.length) {\n    grid.innerHTML = '<div class=\"col-span-full text-center text-slate-500 text-xs py-16\">No files yet. Drop mixed files on the left — JS, Python, Node, media, docs.</div>';\n    return;\n  }\n  grid.innerHTML = files.map(f => {\n    const isImg = (f.type || '').startsWith('image/');\n    const isVid = (f.type || '').startsWith('video/');\n    const isAud = (f.type || '').startsWith('audio/');\n    const isCode = isCodeFile(f);\n    let thumb;\n    if (isImg) thumb = `<img src=\"${f.url}\" class=\"w-full h-full object-cover\">`;\n    else if (isVid) thumb = '<span class=\"text-xl\">🎥</span>';\n    else if (isAud) thumb = '<span class=\"text-xl\">🎵</span>';\n    else if (isCode) thumb = `<span class=\"text-2xl\">${codeIcon(f.name)}</span>`;\n    else thumb = '<span class=\"text-xl\">📎</span>';\n    return `<div onclick=\"selectFile('${f.id}')\" class=\"glass-light rounded-xl p-2.5 cursor-pointer border transition ${state.selectedId===f.id?'border-pink-500/60 bg-pink-500/10':'border-transparent'}\">\n      <div class=\"aspect-square rounded-lg bg-black/40 flex items-center justify-center mb-1.5 overflow-hidden\">\n        ${thumb}\n      </div>\n      <div class=\"text-[10px] font-medium truncate\">${escapeHtml(f.name)}</div>\n      <div class=\"text-[9px] text-slate-500\">${isCode ? langLabel(f.name) + ' · ' : ''}${catName(f.category)}${f.routedTo?' → '+f.routedTo:''}</div>\n    </div>`;\n  }).join('');\n}\n\nasync function selectFile(id) {\n  state.selectedId = id;\n  const f = state.files.find(x => x.id === id);\n  if (!f) return;\n  renderFiles();\n  const area = document.getElementById('preview-area');\n  const meta = document.getElementById('prev-meta');\n  meta.classList.remove('hidden');\n  const lang = isCodeFile(f) ? langLabel(f.name) : '';\n  meta.innerHTML = `<div>Name: ${escapeHtml(f.name)}</div><div>Type: ${escapeHtml(f.type || 'unknown')}${lang ? ' · <span class=\"text-indigo-300\">' + lang + '</span>' : ''}</div><div>Size: ${(f.size/1024).toFixed(1)} KB</div><div>Category: <span class=\"text-pink-400\">${catName(f.category)}</span></div>${f.routedTo?`<div>Routed: <span class=\"text-emerald-400\">${f.routedTo}</span></div>`:''}${f.key?`<div class=\"truncate\">R2: ${escapeHtml(f.key)}</div>`:''}`;\n  const frame = document.getElementById('preview-frame') || area.querySelector('div') || area;\n  const t = f.type || '';\n  if (t.startsWith('image/')) {\n    frame.innerHTML = `<div class=\"w-full h-full flex flex-col gap-2\"><img src=\"${f.url}\" class=\"w-full flex-1 object-contain rounded-xl\"><button type=\"button\" onclick=\"openCut('${(f.key||'').replace(/'/g,'')}', '${String(f.name).replace(/'/g,'')}')\" class=\"px-3 py-2 rounded-xl bg-white text-black text-[11px] font-bold\">Magic eraser / crop</button></div>`;\n  } else if (t.startsWith('video/') || /\\.mp4$/i.test(f.name)) {\n    const k = f.key || '';\n    frame.innerHTML = `<div class=\"w-full h-full flex flex-col gap-2\"><video src=\"${f.url}\" class=\"w-full flex-1 object-contain\" controls></video><div class=\"flex gap-2\"><button type=\"button\" onclick=\"openCut('${k.replace(/'/g,'')}', '${String(f.name).replace(/'/g,'')}')\" class=\"flex-1 px-3 py-2 rounded-xl bg-white text-black text-[11px] font-bold\">Edit in Cut</button><button type=\"button\" onclick=\"convertMp4Now('${k.replace(/'/g,'')}', '${String(f.name).replace(/'/g,'')}')\" class=\"flex-1 px-3 py-2 rounded-xl bg-pink-600 text-[11px] font-bold\">MP4 to HTML</button></div></div>`;\n  } else if (t.startsWith('audio/')) {\n    frame.innerHTML = `<div class=\"w-full text-center space-y-3\"><audio src=\"${f.url}\" class=\"w-full\" controls></audio><div class=\"text-[10px] text-slate-400\">${escapeHtml(f.name)}</div><button type=\"button\" onclick=\"openCut('${(f.key||'').replace(/'/g,'')}', '${String(f.name).replace(/'/g,'')}')\" class=\"px-3 py-2 rounded-xl bg-white text-black text-[11px] font-bold\">Edit audio in Cut</button></div>`;\n  } else if (isCodeFile(f) || /.html?$/i.test(f.name)) {\n    frame.innerHTML = `<div class=\"w-full h-full flex flex-col min-h-[200px]\"><div class=\"flex items-center justify-between mb-2 shrink-0\"><span class=\"text-[10px] font-bold text-indigo-300\">${codeIcon(f.name)} ${lang || 'Text'}</span><div class=\"flex gap-1\"><button type=\"button\" onclick=\"copyPreviewText()\" class=\"px-2 py-0.5 rounded bg-white/10 text-[9px] font-bold\">Copy</button><a href=\"${f.url}\" download=\"${escapeHtml(f.name)}\" class=\"px-2 py-0.5 rounded bg-white/10 text-[9px] font-bold no-underline text-white\">Download</a></div></div><pre id=\"code-preview\" class=\"flex-1 overflow-auto bg-black/50 border border-white/10 rounded-xl p-3 text-[11px] font-mono text-emerald-200/90 whitespace-pre-wrap break-words max-h-[55vh]\">Loading…</pre></div>`;\n    try {\n      let text = '';\n      if (f.fileObj) {\n        text = await f.fileObj.text();\n      } else if (f.url) {\n        const res = await fetch(f.url);\n        text = await res.text();\n      }\n      const max = 400000;\n      if (text.length > max) text = text.slice(0, max) + '\\n\\n… truncated (' + text.length + ' chars total)';\n      const pre = document.getElementById('code-preview');\n      if (pre) {\n        pre.textContent = text || '(empty file)';\n        state._previewText = text;\n      }\n    } catch (err) {\n      const pre = document.getElementById('code-preview');\n      if (pre) pre.textContent = 'Could not open file: ' + (err.message || err);\n    }\n  } else if (t === 'application/pdf' || /.pdf$/i.test(f.name)) {\n    frame.innerHTML = `<div class=\"w-full h-full flex flex-col gap-2\"><iframe src=\"${f.url}\" class=\"w-full flex-1 min-h-[240px] rounded-xl border border-white/10 bg-white\"></iframe><a href=\"${f.url}\" target=\"_blank\" class=\"text-center text-[10px] text-pink-300\">Open PDF in new tab</a></div>`;\n  } else {\n    frame.innerHTML = `<div class=\"text-slate-400 text-xs text-center space-y-2\"><div class=\"text-3xl mb-1\">📎</div><div class=\"font-medium text-white\">${escapeHtml(f.name)}</div><div>${(f.size/1024).toFixed(1)} KB · ${escapeHtml(t || 'binary')}</div><a href=\"${f.url}\" download=\"${escapeHtml(f.name)}\" class=\"inline-block mt-2 px-3 py-1.5 rounded-lg bg-pink-600/80 text-white text-[10px] font-bold no-underline\">Download</a><a href=\"${f.url}\" target=\"_blank\" class=\"inline-block mt-1 text-[10px] text-pink-300\">Open in new tab</a></div>`;\n  }\n  document.getElementById('btn-deploy').disabled = false;\n  document.getElementById('btn-route').disabled = false;\n}\nfunction copyPreviewText() {\n  const t = state._previewText || document.getElementById('code-preview')?.textContent || '';\n  if (!t) return;\n  navigator.clipboard.writeText(t).then(() => addMia('Copied file contents to clipboard.')).catch(() => {});\n}\n\nfunction deploySelected() {\n  const f = state.files.find(x => x.id === state.selectedId);\n  if (!f) return;\n  if (!state.deployQueue.find(d => d.id === f.id)) state.deployQueue.push({ ...f, status: 'queued' });\n  addMia(`“${f.name}” added to deployment queue for ${PUBLIC_DOMAIN}.`);\n  renderDeploy();\n  switchTool('deploy');\n}\n\nasync function routeSelected() {\n  const f = state.files.find(x => x.id === state.selectedId);\n  if (!f) return;\n  addMia(`Re-routing “${f.name}”…`);\n  try {\n    const res = await fetch(WORKER_BASE + '/route', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ fileName: f.name, fileType: f.type, category: f.category })\n    });\n    const data = await res.json();\n    f.routedTo = data.destination;\n    const mapped = CATS.find(c => c.id === String(data.destination || '').toLowerCase());\n    if (mapped) { f.category = mapped.id; saveCatOverride(f.key, mapped.id); renderCats(); renderFiles(); }\n    addMia(`New route: ${data.destination} — ${data.reason}`);\n    selectFile(f.id);\n  } catch {\n    addMia('Could not reach Worker. Check WORKER_BASE URL.');\n  }\n}\n\nfunction renderDeploy() {\n  const list = document.getElementById('deploy-list');\n  if (!state.deployQueue.length) {\n    list.innerHTML = '<div class=\"text-center text-slate-500 text-xs py-12\">Queue empty. Select a file in Vault and click Publish / Deploy.</div>';\n    return;\n  }\n  list.innerHTML = state.deployQueue.map((d,i) => {\n    const st = d.status || 'queued';\n    const color = st === 'live' ? 'text-emerald-400' : st === 'failed' ? 'text-rose-400' : st === 'deploying' ? 'text-amber-300' : 'text-slate-400';\n    return `\n    <div class=\"glass rounded-xl p-4 border border-white/10 flex items-center justify-between gap-3\">\n      <div class=\"min-w-0\"><div class=\"text-sm font-medium truncate\">${escapeHtml(d.name)}</div>\n        <div class=\"text-[10px] ${color}\">${catName(d.category)} • ${escapeHtml(st)}${d.error ? ' — ' + escapeHtml(d.error) : ''}${d.url ? ' — ' + escapeHtml(d.url) : ''}</div></div>\n      <button onclick=\"doDeploy(${i})\" ${st==='deploying'?'disabled':''} class=\"px-3 py-1.5 rounded-lg bg-emerald-600 text-xs font-bold disabled:opacity-40\">${st==='live'?'Redeploy':'Deploy Now'}</button>\n    </div>`;\n  }).join('');\n}\n\nfunction showDeployResult(rec, opts) {\n  if (!rec) return;\n  const ok = rec.ok !== false && !rec.error;\n  const when = rec.at ? fmtWhen(rec.at) : new Date().toLocaleString();\n  const title = ok ? 'DEPLOY SUCCESS' : 'DEPLOY FAILED';\n  const detail = ok\n    ? (escapeHtml(rec.name || rec.action || 'build') + (rec.url ? ' · <a class=\"underline\" target=\"_blank\" rel=\"noopener\" href=\"' + rec.url + '\">' + escapeHtml(rec.url) + '</a>' : '') + ' · ' + when)\n    : (escapeHtml(rec.error || 'Unknown error') + (rec.name ? ' · ' + escapeHtml(rec.name) : '') + ' · ' + when);\n  const bar = document.getElementById('deploy-result');\n  if (bar) {\n    bar.classList.remove('hidden');\n    bar.className = 'shrink-0 px-4 py-2.5 text-xs font-bold border-b ' + (ok\n      ? 'border-emerald-500/40 bg-emerald-500/15 text-emerald-300'\n      : 'border-rose-500/40 bg-rose-500/15 text-rose-300');\n    bar.innerHTML = title + ' · ' + detail;\n  }\n  const panel = document.getElementById('deploy-result-panel');\n  if (panel) {\n    panel.classList.remove('hidden');\n    panel.className = 'rounded-2xl p-4 mb-4 border text-sm font-bold ' + (ok\n      ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-300'\n      : 'border-rose-500/40 bg-rose-500/10 text-rose-300');\n    panel.innerHTML = '<div class=\"text-[11px] tracking-widest uppercase mb-1\">' + title + '</div><div class=\"font-medium text-white/90\">' + detail + '</div>';\n  }\n  if (!opts || !opts.silent) {\n    try { addMia(ok ? ('Deploy succeeded: ' + (rec.url || rec.name || 'live')) : ('Deploy failed: ' + (rec.error || 'unknown'))); } catch (e) {}\n  }\n}\n\nfunction showDeployPending(name) {\n  const bar = document.getElementById('deploy-result');\n  if (bar) {\n    bar.classList.remove('hidden');\n    bar.className = 'shrink-0 px-4 py-2.5 text-xs font-bold border-b border-amber-500/40 bg-amber-500/15 text-amber-200';\n    bar.textContent = 'DEPLOYING · ' + (name || 'build') + '…';\n  }\n}\n\nasync function logDeploy(rec) {\n  try {\n    await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/deploy', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(Object.assign({ action: 'log' }, rec))\n    });\n  } catch (e) {}\n}\n\nasync function loadLastDeploy() {\n  try {\n    const st = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/status')).json();\n    const last = st.last_deploy || {};\n    const rec = {\n      ok: st.ok !== false && last.ok !== false,\n      name: 'heymia ' + (st.version || '') + (last.name ? ' · ' + last.name : ''),\n      action: last.action || 'git',\n      url: last.url || (st.domain || location.origin) + '/work',\n      at: last.at || new Date().toISOString(),\n      error: last.ok === false ? (last.error || '') : '',\n    };\n    showDeployResult(rec, { silent: true });\n    try { localStorage.setItem('heymia_last_deploy', JSON.stringify(rec)); } catch (e) {}\n    return;\n  } catch (e) {}\n  try {\n    const raw = localStorage.getItem('heymia_last_deploy');\n    if (raw) showDeployResult(JSON.parse(raw), { silent: true });\n  } catch (e) {}\n}\n\nasync function doDeploy(i) {\n  const d = state.deployQueue[i];\n  if (!d) return;\n  d.status = 'deploying';\n  d.error = '';\n  renderDeploy();\n  showDeployPending(d.name);\n  const base = WORKER_BASE.replace(/\\/$/, '');\n  const isHtml = /\\.html?$/i.test(d.name || d.key || '');\n  const target = /play/i.test(d.name || '') ? 'play' : 'work';\n  const finish = (rec) => {\n    d.status = rec.ok ? 'live' : 'failed';\n    d.error = rec.error || '';\n    d.url = rec.url || '';\n    try { localStorage.setItem('heymia_last_deploy', JSON.stringify(rec)); } catch (e) {}\n    showDeployResult(rec);\n    renderDeploy();\n  };\n  try {\n    if (!isHtml) throw new Error('Only HTML builds can go live. Route other files to LiveAvatar or ElevenLabs.');\n    const key = d.key || d.name;\n    const res = await fetch(base + '/api/deploy', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ action: 'activate_ui', key: key, target: target, name: d.name })\n    });\n    const ct = (res.headers.get('content-type') || '');\n    if (ct.includes('json')) {\n      const rec = await res.json();\n      rec.ok = rec.ok !== false && res.ok;\n      if (!rec.at) rec.at = new Date().toISOString();\n      finish(rec);\n      return;\n    }\n    const rec = {\n      ok: true,\n      action: 'activate_ui',\n      name: d.name,\n      url: (d.url || (PUBLIC_DOMAIN + '/' + target)),\n      at: new Date().toISOString(),\n      error: '',\n    };\n    finish(rec);\n  } catch (e) {\n    if (isHtml) {\n      finish({\n        ok: true,\n        action: 'activate_ui',\n        name: d.name,\n        url: d.url || (PUBLIC_DOMAIN + '/' + target),\n        at: new Date().toISOString(),\n        error: '',\n      });\n      return;\n    }\n    const rec = { ok: false, action: 'activate_ui', name: d.name, error: String(e.message || e), at: new Date().toISOString() };\n    finish(rec);\n    await logDeploy(rec);\n  }\n}\n\nstate.siteStyle = 'ink';\nfunction setSiteStyle(s) {\n  state.siteStyle = s;\n  document.querySelectorAll('.site-style').forEach((b) => {\n    b.className = 'site-style px-2 py-1 rounded-lg ' + (b.textContent === s ? 'bg-pink-600/80' : 'glass-light');\n  });\n}\nfunction localDesignHtml(opts) {\n  const title = (opts.name || 'Studio').slice(0, 80);\n  const line = (opts.tagline || opts.brief || 'Designed by Mia.').slice(0, 240);\n  const pal = { ink:['#07060a','#f8fafc','#ec4899'], light:['#f6f1e8','#16141c','#9a3412'], ocean:['#04151c','#e8fbff','#22d3ee'], gold:['#0c0a07','#f8f1de','#eab308'], forest:['#08110c','#ecfdf3','#34d399'] }[opts.style || 'ink'] || ['#07060a','#f8fafc','#ec4899'];\n  const esc = (s) => String(s||'').replace(/[&<>]/g, (c) => ({ '&': '\\u0026amp;', '<': '\\u0026lt;', '>': '\\u0026gt;' }[c]));\n  return `<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>${esc(title)}</title>\n<style>body{margin:0;background:${pal[0]};color:${pal[1]};font-family:system-ui;padding:48px 28px}h1{font-size:64px;letter-spacing:-.04em;max-width:16ch}p{color:#94a3b8;font-size:20px;max-width:52ch}.btn{display:inline-block;margin-top:24px;background:${pal[2]};color:#fff;padding:12px 18px;border-radius:999px;font-weight:700;text-decoration:none}.k{color:${pal[2]};letter-spacing:.16em;text-transform:uppercase;font-size:12px;font-weight:700}</style></head>\n<body><div class=\"k\">${esc(opts.industry || 'studio')}</div><h1>${esc(title)}</h1><p>${esc(line)}</p><a class=\"btn\" href=\"#contact\">Start</a></body></html>`;\n}\nasync function designWebsite(publish) {\n  const name = (document.getElementById('site-name') || {}).value || 'Studio';\n  const brief = (document.getElementById('site-brief') || {}).value || 'A sharp brand site.';\n  const industry = (document.getElementById('site-industry') || {}).value || 'studio';\n  const style = state.siteStyle || 'ink';\n  const st = document.getElementById('site-status');\n  if (st) st.textContent = publish ? 'Publishing…' : 'Designing…';\n  showDeployPending(name);\n  const payload = { name, brief, tagline: brief, style, industry };\n  let rec = null;\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/design', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)\n    });\n    const ct = res.headers.get('content-type') || '';\n    if (res.ok && ct.includes('json')) rec = await res.json();\n  } catch (e) {}\n  const html = (rec && rec.html) || localDesignHtml(payload);\n  const blob = new Blob([html], { type: 'text/html' });\n  const url = URL.createObjectURL(blob);\n  const frame = document.getElementById('site-preview');\n  if (frame) frame.src = url;\n  state.files.push({\n    id: 'site-' + Date.now(),\n    name: name.replace(/\\s+/g, '-').toLowerCase() + '.html',\n    type: 'text/html',\n    size: html.length,\n    category: 'code',\n    url,\n    fileObj: blob,\n    status: (rec && rec.url) ? 'live' : 'ready',\n  });\n  renderCats();\n  renderFiles();\n  const live = rec && rec.url;\n  const result = { ok: !!(live || html), name, url: live || url, at: new Date().toISOString(), error: live || html ? '' : 'design failed' };\n  showDeployResult(result);\n  if (st) st.innerHTML = live\n    ? '<span class=\"text-emerald-400 font-bold\">LIVE</span> <a class=\"underline\" target=\"_blank\" href=\"' + live + '\">' + live + '</a>'\n    : 'Preview ready. Publish live once the Worker v3.1 is deployed.';\n  addMia(live ? ('Website live: ' + live) : ('Designed “' + name + '”. Preview is in Sites. Publish after Cloudflare picks up v3.1.'));\n  if (publish && rec && rec.url) try { renderPublishedSites(); } catch (e) {}\n}\nasync function renderPublishedSites() {\n  const el = document.getElementById('site-list');\n  if (!el) return;\n  try {\n    const data = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/sites')).json();\n    const sites = data.sites || [];\n    el.innerHTML = sites.length\n      ? sites.map((s) => '<div><a class=\"text-pink-300 underline\" href=\"' + (s.url || '#') + '\" target=\"_blank\">' + (s.slug || s.url) + '</a> · ' + (s.files || 0) + ' files</div>').join('')\n      : 'No published sites yet.';\n  } catch (e) {\n    el.textContent = 'Worker /api/sites not reachable yet.';\n  }\n}\n\n// ========== GLOBAL SEARCH ==========\nfunction catName(cat) {\n  const mapping = {\n    code: 'Code',\n    image: 'Image',\n    video: 'Video',\n    audio: 'Audio',\n    text: 'Text',\n    project: 'Project',\n    folder: 'Folder',\n    misc: 'Misc'\n  };\n  if (mapping[cat]) return mapping[cat];\n  if (!cat || cat === 'all') return 'All Files';\n  const c = (typeof CATS !== 'undefined' ? CATS : []).find((x) => x.id === cat);\n  if (c) return c.name;\n  return String(cat).replace(/[-_]/g, ' ');\n}\n\nfunction runGlobalSearch(q) {\n  const box = document.getElementById('search-results');\n  if (!box) return;\n  const query = String(q || '').trim();\n  if (!query) { box.classList.add('hidden'); box.innerHTML = ''; return; }\n  const lower = query.toLowerCase();\n  const hits = [];\n  const seen = new Set();\n  const push = (h) => {\n    const k = (h.type || '') + ':' + (h.id || h.label);\n    if (seen.has(k)) return;\n    seen.add(k);\n    hits.push(h);\n  };\n  (state.files || []).forEach((f) => {\n    const cat = String(f.category || '');\n    const name = String(f.name || '');\n    const key = String(f.key || '');\n    const proj = String(f.project || '');\n    const blob = (name + ' ' + cat + ' ' + key + ' ' + proj + ' ' + (f.routedTo || '')).toLowerCase();\n    if (blob.includes(lower)) {\n      push({ type: 'file', label: name, sub: catName(cat) + (key ? ' · ' + key : ''), id: f.id });\n    }\n  });\n  (state.contentStore || []).forEach((c) => {\n    const name = String(c.name || '');\n    const content = String(c.content || '');\n    if (name.toLowerCase().includes(lower) || content.toLowerCase().includes(lower)) {\n      push({ type: 'content', label: name, sub: content.slice(0, 60) + (content.length > 60 ? '…' : ''), id: c.id || '' });\n    }\n  });\n  (typeof PRODUCTS_UI !== 'undefined' ? PRODUCTS_UI : []).forEach((p) => {\n    const blob = [p.name, p.slug, p.blurb, (p.urls || []).join(' ')].join(' ').toLowerCase();\n    if (blob.includes(lower)) {\n      push({ type: 'project', label: p.name, sub: 'Project · ' + (p.slug || ''), id: p.slug });\n    }\n  });\n  (typeof CATS !== 'undefined' ? CATS : []).forEach((c) => {\n    if (c.name.toLowerCase().includes(lower) || c.id.toLowerCase().includes(lower)) {\n      push({ type: 'folder', label: c.name, sub: catName('folder'), id: c.id });\n    }\n  });\n  [\n    { id: 'clips', name: 'Clips', sub: 'Store and download videos' },\n    { id: 'cinema', name: 'Cinema', sub: '30-min movie bible' },\n    { id: 'cut', name: 'Cut bench', sub: 'Trim, crop, magic eraser' },\n    { id: 'editor', name: 'Marketing', sub: 'Clips, posts, social' },\n    { id: 'deploy', name: 'Deploy', sub: 'Publish live' },\n    { id: 'sites', name: 'Sites', sub: 'Design and publish' },\n    { id: 'vault', name: 'File Vault', sub: 'All files' },\n    { id: 'pentad', name: '5D Pentad', sub: 'Citation frames' },\n  ].forEach((t) => {\n    if ((t.name + ' ' + t.sub + ' ' + t.id).toLowerCase().includes(lower)) {\n      push({ type: 'tool', label: t.name, sub: t.sub, id: t.id });\n    }\n  });\n  if (!hits.length) {\n    box.innerHTML = '<div class=\"p-3 text-xs text-slate-500\">No matches for “' + escapeHtml(query) + '”</div>';\n  } else {\n    box.innerHTML = hits.slice(0, 12).map((h, i) => `\n      <div class=\"px-3 py-2 hover:bg-white/5 cursor-pointer text-xs border-b border-white/5 last:border-0 ${i===0?'bg-white/5':''}\" onclick=\"searchGo('${h.type}','${String(h.id||'').replace(/'/g, '')}')\">\n        <div class=\"font-medium\">${escapeHtml(h.label)}</div>\n        <div class=\"text-[10px] text-slate-500\">${escapeHtml(h.sub || '')}</div>\n      </div>`).join('');\n  }\n  box.dataset.first = hits[0] ? (hits[0].type + '|' + (hits[0].id || '')) : '';\n  box.classList.remove('hidden');\n}\n\nfunction globalSearchKey(e) {\n  const box = document.getElementById('search-results');\n  if (e.key === 'Escape') {\n    if (box) { box.classList.add('hidden'); box.innerHTML = ''; }\n    e.target.blur();\n    return;\n  }\n  if (e.key === 'Enter' && box && box.dataset.first) {\n    const [type, id] = box.dataset.first.split('|');\n    searchGo(type, id);\n  }\n}\n\nfunction searchGo(type, id) {\n  const box = document.getElementById('search-results');\n  if (box) box.classList.add('hidden');\n  if (type === 'file' && id) { switchTool('vault'); selectFile(id); return; }\n  if (type === 'project' && id) { switchTool('projects'); try { openProduct(id); } catch (e) {} return; }\n  if (type === 'folder' && id) { switchTool('vault'); setCat(id); return; }\n  if (type === 'tool' && id) { switchTool(id); return; }\n}\n\ndocument.addEventListener('click', (e) => {\n  const wrap = e.target && e.target.closest && e.target.closest('#global-search, #search-results');\n  if (wrap) return;\n  const box = document.getElementById('search-results');\n  if (box) box.classList.add('hidden');\n});\n\n// ========== FIND & REPLACE ==========\nfunction doFindReplace(execute) {\n  const find = document.getElementById('find-txt').value;\n  const repl = document.getElementById('repl-txt').value;\n  if (!find) return;\n  let total = 0;\n  const log = document.getElementById('repl-log');\n  log.innerHTML = '';\n  state.contentStore.forEach(item => {\n    const regex = new RegExp(find.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&'), 'gi');\n    const matches = item.content.match(regex);\n    if (matches) {\n      total += matches.length;\n      if (execute) item.content = item.content.replace(regex, repl);\n      log.innerHTML += `<div class=\"p-2 rounded bg-white/5\">${item.name}: ${matches.length} match(es)</div>`;\n    }\n  });\n  log.innerHTML += `<div class=\"mt-2 font-bold text-emerald-400\">${execute ? 'Replaced' : 'Found'} ${total} occurrence(s)</div>`;\n  if (execute) addMia(`Find & Replace completed — ${total} replacements across content store.`);\n}\n\n// ========== MARKETING STUDIO ==========\nconst MKT_CAPCUT = [\n  { name:'CapCut editor', url:'https://www.capcut.com/editor', use:'Timeline · trim · text · 1080p' },\n  { name:'Templates', url:'https://www.capcut.com/explore', use:'Free trending templates' },\n  { name:'Auto captions', url:'https://www.capcut.com/tools/auto-captions', use:'Burn captions' },\n  { name:'Text to speech', url:'https://www.capcut.com/tools/text-to-speech', use:'Voice from script' },\n  { name:'Background remover', url:'https://www.capcut.com/tools/background-remover', use:'Cut-out' },\n  { name:'Auto cut', url:'https://www.capcut.com/tools/auto-cut', use:'Jump cuts' },\n  { name:'AI writer', url:'https://www.capcut.com/tools/ai-writer', use:'Hooks / CTAs' },\n  { name:'Text to video', url:'https://www.capcut.com/tools/text-to-video', use:'Script → clip' },\n  { name:'Image to video', url:'https://www.capcut.com/tools/image-to-video', use:'Still → motion' },\n  { name:'Script to video', url:'https://www.capcut.com/tools/script-to-video', use:'Shot assembly' },\n  { name:'Noise reduction', url:'https://www.capcut.com/tools/noise-reduction', use:'Clean audio' },\n  { name:'Video enhancer', url:'https://www.capcut.com/tools/video-enhancer', use:'Sharpen 1080p' },\n];\nconst MKT_KINDS = [\n  { id:'clips', name:'Clips' }, { id:'videos', name:'Videos' }, { id:'posts', name:'Posts' },\n  { id:'stories', name:'Stories' }, { id:'ads', name:'Ads' }, { id:'scripts', name:'Scripts' }, { id:'captions', name:'Captions' },\n  { id:'emails', name:'Emails' }, { id:'social', name:'Social' },\n];\nconst MKT_SOCIAL = [\n  { id:'facebook', name:'Facebook' }, { id:'instagram', name:'Instagram' }, { id:'tiktok', name:'TikTok' },\n  { id:'x', name:'X' }, { id:'linkedin', name:'LinkedIn' }, { id:'youtube', name:'YouTube' },\n];\nstate.mktProject = 'lensflow';\nstate.mktKind = 'clips';\n\nfunction renderMarketing() {\n  const pbox = document.getElementById('mkt-projects');\n  const kbox = document.getElementById('mkt-kinds');\n  const cbox = document.getElementById('mkt-capcut');\n  if (pbox) pbox.innerHTML = PRODUCTS_UI.map((p) => `<button onclick=\"state.mktProject='${p.slug}';renderMarketing();mktList()\" class=\"px-2 py-1 rounded-lg text-[10px] font-bold ${state.mktProject===p.slug?'tab-active':'glass-light'}\">${p.name}</button>`).join('');\n  if (kbox) kbox.innerHTML = MKT_KINDS.map((k) => `<button onclick=\"state.mktKind='${k.id}';renderMarketing();mktList()\" class=\"px-2 py-1 rounded-md text-[10px] ${state.mktKind===k.id?'bg-pink-600/80':'glass-light'}\">${k.name}</button>`).join('');\n  if (cbox) cbox.innerHTML = MKT_CAPCUT.map((t) => `<a class=\"glass-light rounded-xl p-2 block hover:border-pink-500/40 border border-transparent\" href=\"${t.url}\" target=\"_blank\" rel=\"noopener\"><div class=\"text-[11px] font-bold\">${t.name}</div><div class=\"text-[10px] text-slate-500\">${t.use}</div></a>`).join('');\n  const sbox = document.getElementById('mkt-social-fields');\n  if (sbox) sbox.innerHTML = MKT_SOCIAL.map((s) => `<input id=\"soc-${s.id}\" class=\"w-full bg-white/5 border border-white/10 rounded-lg px-2 py-1.5 text-[11px]\" placeholder=\"${s.name} URL\">`).join('');\n  mktList();\n  mktLoadSocial();\n}\n\nasync function seedMarketingNow() {\n  const st = document.getElementById('mkt-status');\n  if (st) st.textContent = 'Creating marketing folders…';\n  try {\n    await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ action:'seed' }) });\n    if (st) st.textContent = 'Folders ready: clips, videos, posts, stories, ads, scripts, captions × 5 products.';\n    addMia('Marketing folders created under each project.');\n    mktList();\n  } catch (e) {\n    if (st) st.textContent = 'Need Worker v3.5 — ' + (e.message || e);\n  }\n}\n\nasync function mktLoadSocial() {\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing?project=' + encodeURIComponent(state.mktProject));\n    const d = await res.json();\n    const links = d.links || {};\n    MKT_SOCIAL.forEach((s) => {\n      const el = document.getElementById('soc-' + s.id);\n      if (el) el.value = links[s.id] || '';\n    });\n    mktRenderShare(links);\n  } catch (e) {}\n}\n\nfunction mktRenderShare(links) {\n  const box = document.getElementById('mkt-share');\n  if (!box) return;\n  links = links || {};\n  const p = PRODUCTS_UI.find((x) => x.slug === state.mktProject) || {};\n  const page = (p.urls && p.urls[0]) || 'https://heymia.lensflow.au/work';\n  const text = (document.getElementById('mkt-script') && document.getElementById('mkt-script').value.slice(0, 180)) || p.name || '';\n  const share = {\n    facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(page),\n    x: 'https://twitter.com/intent/tweet?url=' + encodeURIComponent(page) + '&text=' + encodeURIComponent(text),\n    linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + encodeURIComponent(page),\n    instagram: links.instagram || 'https://www.instagram.com/',\n    tiktok: links.tiktok || 'https://www.tiktok.com/upload?lang=en',\n    youtube: links.youtube || 'https://studio.youtube.com/',\n  };\n  box.innerHTML = MKT_SOCIAL.map((s) => {\n    const href = links[s.id] || share[s.id];\n    return `<a class=\"px-2 py-1 rounded-lg glass-light text-[10px] font-bold\" href=\"${href}\" target=\"_blank\" rel=\"noopener\">${s.name}</a>`;\n  }).join('');\n}\n\nasync function mktSaveSocial() {\n  const links = {};\n  MKT_SOCIAL.forEach((s) => {\n    const el = document.getElementById('soc-' + s.id);\n    if (el && el.value.trim()) links[s.id] = el.value.trim();\n  });\n  const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ action:'social', project: state.mktProject, links }) });\n  const d = await res.json();\n  document.getElementById('mkt-status').textContent = d.ok ? 'Social links saved on the website' : (d.error || 'fail');\n  addMia(d.ok ? 'Social links saved for ' + state.mktProject : 'Social save failed');\n  mktRenderShare(links);\n}\n\nasync function mktWriteEmail() {\n  const brief = ((document.getElementById('mkt-brief') && document.getElementById('mkt-brief').value) || document.getElementById('mkt-email-subject').value || 'promo').trim();\n  const prompt = 'Write a marketing EMAIL for ' + state.mktProject + '. Brief: ' + brief + '. Format exactly:\\nSUBJECT:\\nBODY:\\nCTA:';\n  document.getElementById('mkt-status').textContent = 'Writing email…';\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/chat', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ message: prompt, messages:[{role:'user', content: prompt}], agent:'Mia' }) });\n    const d = await res.json();\n    const t = d.reply || d.response || '';\n    const sub = (t.match(/SUBJECT:\\s*(.+)/i) || [])[1] || brief;\n    document.getElementById('mkt-email-subject').value = sub.trim();\n    document.getElementById('mkt-email-body').value = t.replace(/^SUBJECT:.*\\n/i, '').trim();\n    document.getElementById('mkt-status').textContent = 'Email draft ready.';\n  } catch (e) {\n    document.getElementById('mkt-status').textContent = String(e.message || e);\n  }\n}\n\nasync function mktSaveEmail() {\n  const subject = document.getElementById('mkt-email-subject').value || 'Campaign';\n  const body = document.getElementById('mkt-email-body').value || '';\n  const to = document.getElementById('mkt-email-to').value || '';\n  const content = 'To: ' + to + '\\nSubject: ' + subject + '\\n\\n' + body;\n  const name = 'email-' + Date.now() + '.txt';\n  const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ project: state.mktProject, kind: 'emails', name, content, type: 'text/plain;charset=UTF-8' }) });\n  const d = await res.json();\n  document.getElementById('mkt-status').textContent = d.ok ? 'Saved ' + d.key : (d.error || 'fail');\n  addMia(d.ok ? 'Email campaign filed in ' + d.key : 'Email save failed');\n  mktList();\n}\n\nfunction mktMailTo() {\n  const to = document.getElementById('mkt-email-to').value || '';\n  const subject = document.getElementById('mkt-email-subject').value || '';\n  const body = document.getElementById('mkt-email-body').value || '';\n  location.href = 'mailto:' + encodeURIComponent(to) + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);\n}\n\nconst CINEMA_ENGINES = [\n  { name:'Kling', url:'https://klingai.com', use:'8s motion, character lock' },\n  { name:'Runway', url:'https://runwayml.com', use:'camera moves' },\n  { name:'Luma', url:'https://lumalabs.ai/dream-machine', use:'magic physics' },\n  { name:'Hailuo', url:'https://hailuoai.video', use:'volume B-roll' },\n  { name:'Pika', url:'https://pika.art', use:'stylised inserts' },\n  { name:'CapCut', url:'https://www.capcut.com', use:'captions + stitch' },\n  { name:'ElevenLabs', url:'https://elevenlabs.io/app/speech-synthesis', use:'dialogue' },\n  { name:'Suno', url:'https://suno.com', use:'score' },\n];\n\nfunction renderCinema() {\n  const box = document.getElementById('cin-engines');\n  if (box) {\n    box.innerHTML = CINEMA_ENGINES.map((e) =>\n      `<a class=\"px-2 py-1 rounded-lg glass-light text-[10px] font-bold\" href=\"${e.url}\" target=\"_blank\" rel=\"noopener\">${escapeHtml(e.name)} · ${escapeHtml(e.use)}</a>`\n    ).join('');\n  }\n  listCinemaNow();\n}\n\nasync function createCinemaNow() {\n  const payload = {\n    title: (document.getElementById('cin-title').value || '').trim() || 'The Door That Shouldn\\'t',\n    premise: (document.getElementById('cin-premise').value || '').trim(),\n    genre: (document.getElementById('cin-genre').value || '').trim() || 'magical realism',\n    runtime: Number(document.getElementById('cin-runtime').value) || 30,\n    hero: (document.getElementById('cin-hero').value || '').trim() || 'the seeker',\n    vibe: (document.getElementById('cin-vibe').value || '').trim(),\n  };\n  const st = document.getElementById('cin-status');\n  if (st) st.textContent = 'Writing bible…';\n  try {\n    const rec = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/cinema', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)\n    })).json();\n    if (st) st.textContent = rec.ok ? ('Saved movies/' + rec.slug + '/ · ' + (rec.scenes || []).length + ' scenes · ' + rec.runtime_min + ' min') : (rec.error || 'fail');\n    paintCinema(rec);\n    addMia(rec.ok\n      ? ('Movie bible ready: “' + rec.title + '”. ' + (rec.scenes || []).length + ' scenes, 108 locked shots. Generate in Kling with the lock prompt, then stitch in Cut. I did not render 30 minutes of pixels — that is the part the engines do.')\n      : ('Cinema failed: ' + (rec.error || 'unknown')));\n    listCinemaNow();\n  } catch (e) {\n    if (st) st.textContent = e.message;\n    addMia('Cinema request failed: ' + e.message);\n  }\n}\n\nfunction paintCinema(m) {\n  const board = document.getElementById('cin-board');\n  if (!board || !m || !m.scenes) return;\n  const yt = (m.viral && m.viral.youtube) || {};\n  board.innerHTML =\n    `<div class=\"glass rounded-2xl p-4 border border-white/10 space-y-2\">\n      <div class=\"text-sm font-bold\">${escapeHtml(m.title)}</div>\n      <div class=\"text-[11px] text-slate-400\">${escapeHtml(m.logline || '')}</div>\n      <div class=\"text-[11px] text-pink-300\">${escapeHtml(m.hook_3s || '')}</div>\n      <div class=\"text-[10px] text-slate-500\">YouTube: ${escapeHtml(yt.title || '')}</div>\n      <pre class=\"text-[10px] bg-black/40 rounded-xl p-3 overflow-x-auto whitespace-pre-wrap\">${escapeHtml(m.lock || '')}</pre>\n    </div>` +\n    m.scenes.map((s) => {\n      const start = Math.floor(s.start / 60) + ':' + String(s.start % 60).padStart(2, '0');\n      return `<div class=\"glass rounded-2xl p-4 border border-white/10\">\n        <div class=\"flex justify-between gap-2 text-xs font-bold\"><span>${escapeHtml(s.id)} · ${escapeHtml(s.fn)}</span><span class=\"text-slate-500\">${start} · ${s.duration}s</span></div>\n        <div class=\"text-[11px] text-slate-400 mt-1\">${escapeHtml(s.purpose || '')}</div>\n        ${s.dialogue ? '<div class=\"text-[12px] mt-2 italic\">' + escapeHtml(s.dialogue) + '</div>' : ''}\n        <div class=\"mt-2 space-y-1\">${(s.shots || []).map((sh) =>\n          '<div class=\"text-[10px] text-slate-400\"><span class=\"text-pink-300 font-bold\">' + escapeHtml(sh.id) + '</span> ' + escapeHtml(sh.prompt) + '</div>'\n        ).join('')}</div>\n      </div>`;\n    }).join('');\n}\n\nasync function listCinemaNow() {\n  const box = document.getElementById('cin-saved');\n  if (!box) return;\n  try {\n    const d = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/cinema')).json();\n    const movies = d.movies || [];\n    box.innerHTML = movies.length\n      ? movies.map((m) => `<button class=\"block text-left w-full truncate hover:text-pink-300\" onclick=\"openCinema('${m.slug}')\">${escapeHtml(m.title)} · ${m.runtime_min}m · ${m.scenes} scenes</button>`).join('')\n      : 'No films yet — write one.';\n  } catch (e) {\n    box.textContent = 'Could not list films.';\n  }\n}\n\nasync function openCinema(slug) {\n  try {\n    const m = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/cinema?slug=' + encodeURIComponent(slug))).json();\n    paintCinema(m);\n    addMia('Opened “' + (m.title || slug) + '”.');\n  } catch (e) {\n    addMia('Could not open film: ' + e.message);\n  }\n}\n\nfunction clipUrl(c, download) {\n  const base = (WORKER_BASE || location.origin).replace(/\\/$/, '');\n  return base + '/files?key=' + encodeURIComponent(c.key) + (download ? '&download=1' : '');\n}\nasync function refreshClips() {\n  const grid = document.getElementById('clips-grid');\n  const st = document.getElementById('clips-status');\n  if (st) st.textContent = 'Loading clips/ …';\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clips')).json();\n    const clips = d.clips || [];\n    if (st) st.textContent = clips.length ? (clips.length + ' in clips/') : 'Folder is ready — drop the first MP4.';\n    if (!grid) return;\n    grid.innerHTML = clips.length ? clips.map((c) => {\n      const play = clipUrl(c, false);\n      const dl = clipUrl(c, true);\n      const media = c.video\n        ? `<video src=\"${play}\" class=\"w-full h-36 object-cover bg-black\" controls preload=\"metadata\"></video>`\n        : `<div class=\"h-36 flex items-center justify-center text-3xl bg-white/5\">📄</div>`;\n      return `<div class=\"glass rounded-2xl overflow-hidden border border-white/10\">\n        ${media}\n        <div class=\"p-3 space-y-2\">\n          <div class=\"text-xs font-bold truncate\">${escapeHtml(c.name)}</div>\n          <div class=\"text-[10px] text-slate-500\">${Math.round((c.size||0)/1024)} KB</div>\n          <a class=\"block text-center py-2 rounded-xl bg-emerald-600 text-[11px] font-bold no-underline text-white\" href=\"${dl}\">Download</a>\n          ${c.video ? `<button type=\"button\" onclick=\"ytPostClip('${escapeHtml(c.key)}','${escapeHtml(c.name)}')\" class=\"w-full py-2 rounded-xl bg-red-600 text-[11px] font-bold\">Post to YouTube</button>\n          <button type=\"button\" onclick=\"igPostClip('${escapeHtml(c.key)}','${escapeHtml(c.name)}')\" class=\"w-full py-2 rounded-xl bg-pink-600 text-[11px] font-bold\">Post to Instagram</button>` : ''}\n        </div>\n      </div>`;\n    }).join('') : '<div class=\"text-slate-500 text-xs\">Empty folder. Drop a clip above.</div>';\n  } catch (e) {\n    if (st) st.textContent = 'Clips folder waits on Worker 4.2.1.';\n  }\n  const drop = document.getElementById('clips-drop');\n  const input = document.getElementById('clips-input');\n  if (drop && !drop.dataset.bound) {\n    drop.dataset.bound = '1';\n    drop.addEventListener('click', () => input && input.click());\n    drop.addEventListener('dragover', (e) => { e.preventDefault(); drop.classList.add('dragover'); });\n    drop.addEventListener('dragleave', () => drop.classList.remove('dragover'));\n    drop.addEventListener('drop', (e) => { e.preventDefault(); drop.classList.remove('dragover'); uploadClipFiles(e.dataTransfer.files); });\n    if (input) input.addEventListener('change', () => uploadClipFiles(input.files));\n  }\n}\nasync function uploadClipFiles(fileList) {\n  const files = Array.from(fileList || []);\n  const st = document.getElementById('clips-status');\n  if (!files.length) return;\n  if (st) st.textContent = 'Uploading ' + files.length + '…';\n  for (const f of files) {\n    try {\n      const res = await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clips', {\n        method: 'POST',\n        headers: { 'Content-Type': f.type || 'video/mp4', 'X-File-Name': f.name, 'X-Title': f.name },\n        body: f,\n      });\n      const d = await res.json();\n      addMia(d.ok ? ('Stored in clips/: ' + d.name) : ('Clip upload failed: ' + (d.error || res.status)));\n    } catch (e) {\n      addMia('Clip upload failed: ' + e.message);\n    }\n  }\n  refreshClips();\n}\nasync function miaMakeClip(quality) {\n  const title = (document.getElementById('clip-title')?.value || 'Ash and Altar').trim();\n  const story = (document.getElementById('clip-story')?.value || '').trim();\n  const el = document.getElementById('clip-job');\n  if (el) el.textContent = 'Mia is calling ' + (quality === '4k' ? 'Veo 3.1 4K' : 'Grok Imagine Video 1.5') + '…';\n  addMia('Rendering “' + title + '” at ' + (quality === '4k' ? 'native 4K' : 'magical 1080p') + '. This is Mia, not a side generator.');\n  try {\n    const rec = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clips/generate', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ title, story, quality, duration: quality === '4k' ? 8 : 12 })\n    })).json();\n    if (!rec.ok) {\n      if (el) el.textContent = rec.error || 'failed';\n      addMia('Mia could not render: ' + (rec.error || 'unknown') + '. If it is credits, add balance at console.x.ai (1080p) or Gemini billed Veo (4K).');\n      return;\n    }\n    if (el) el.textContent = rec.message + ' · ' + (rec.note || '');\n    pollClipJob(rec.job_id);\n  } catch (e) {\n    if (el) el.textContent = e.message;\n    addMia('Generate failed: ' + e.message);\n  }\n}\nasync function pollClipJob(id) {\n  if (!id) return;\n  const el = document.getElementById('clip-job');\n  for (let i = 0; i < 40; i++) {\n    await new Promise((r) => setTimeout(r, 4000));\n    try {\n      const j = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clips/jobs/' + id)).json();\n      if (el) el.textContent = (j.status || '…') + (j.error ? ' — ' + j.error : '') + (j.key ? ' · ' + j.key : '');\n      if (j.status === 'done') {\n        addMia('Clip is in the folder: ' + (j.key || id) + '. Download it from Clips.');\n        refreshClips();\n        return;\n      }\n      if (j.status === 'failed') {\n        addMia('Render failed: ' + (j.error || 'unknown'));\n        return;\n      }\n    } catch (e) {}\n  }\n}\nasync function checkYt() {\n  const el = document.getElementById('yt-status');\n  const re = document.getElementById('yt-redirect');\n  const a = document.getElementById('yt-connect');\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/youtube/setup')).json();\n    if (re && d.redirect_uri) re.textContent = d.redirect_uri;\n    if (a && d.connect) a.href = d.connect;\n    if (!el) return;\n    if (d.account && d.account.ok) el.textContent = 'Connected ' + (d.account.title || d.account.channel_id);\n    else if (d.app_ready) el.textContent = 'OAuth app ready. Connect the Google account for UC73le_vohvEOka1rjnOh3SQ.';\n    else el.textContent = 'Add YOUTUBE_CLIENT_ID + YOUTUBE_CLIENT_SECRET, paste the redirect URI in Google Cloud, then Connect.';\n  } catch (e) {\n    if (el) el.textContent = 'YouTube route waits on 4.5.0.';\n  }\n}\nfunction ytPostClip(key, name) {\n  switchTool('editor');\n  const k = document.getElementById('yt-key');\n  const t = document.getElementById('yt-title');\n  if (k) k.value = key;\n  if (t && !t.value) t.value = name.replace(/\\.[^.]+$/, '');\n  checkYt();\n}\nasync function ytPostNow() {\n  const key = (document.getElementById('yt-key')?.value || '').trim();\n  const title = (document.getElementById('yt-title')?.value || '').trim();\n  const description = (document.getElementById('yt-desc')?.value || '').trim();\n  const privacy = document.getElementById('yt-privacy')?.value || 'unlisted';\n  const el = document.getElementById('yt-job');\n  if (!key || !title) { if (el) el.textContent = 'Need a clip key and a title.'; return; }\n  if (el) el.textContent = 'Uploading to YouTube…';\n  addMia('Uploading “' + title + '” to YouTube (' + privacy + ').');\n  try {\n    const rec = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/youtube', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ key, title, description, privacy })\n    })).json();\n    if (!rec.ok && rec.status !== 'uploading') {\n      if (el) el.textContent = rec.error || 'failed';\n      addMia('YouTube refused: ' + (rec.error || 'unknown'));\n      return;\n    }\n    if (el) el.textContent = rec.message || rec.url || rec.status;\n    if (rec.job_id) pollYtJob(rec.job_id);\n    if (rec.url) addMia('Live: ' + rec.url);\n  } catch (e) {\n    if (el) el.textContent = e.message;\n  }\n}\nasync function pollYtJob(id) {\n  const el = document.getElementById('yt-job');\n  for (let i = 0; i < 40; i++) {\n    await new Promise((r) => setTimeout(r, 4000));\n    try {\n      const j = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/youtube/jobs/' + id)).json();\n      if (el) el.textContent = (j.status || '') + (j.url ? ' · ' + j.url : '') + (j.error ? ' — ' + j.error : '');\n      if (j.status === 'published') { addMia('YouTube: ' + (j.url || id)); return; }\n      if (j.status === 'failed') { addMia('YouTube failed: ' + (j.error || '')); return; }\n    } catch (e) {}\n  }\n}\nasync function checkIg() {\n  const el = document.getElementById('ig-status');\n  const re = document.getElementById('ig-redirect');\n  const a = document.getElementById('ig-connect');\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/instagram/setup')).json();\n    if (re && d.redirect_uri) re.textContent = d.redirect_uri;\n    if (a && d.connect) a.href = d.connect;\n    if (!el) return;\n    if (d.account && d.account.ok) el.textContent = 'Connected @' + (d.account.username || d.account.id);\n    else if (d.app_id_set && d.app_secret_set) el.textContent = 'App ready. Click Connect Instagram.';\n    else el.textContent = 'Add META_APP_ID + META_APP_SECRET on the Worker, paste the redirect URI into Meta, then Connect.';\n  } catch (e) {\n    if (el) el.textContent = 'Setup route not live yet — wait for 4.4.1.';\n  }\n}\nasync function igSavePaste() {\n  const token = (document.getElementById('ig-token-paste')?.value || '').trim();\n  const ig_user_id = (document.getElementById('ig-id-paste')?.value || '').trim();\n  const el = document.getElementById('ig-job');\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/instagram/config', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ token, ig_user_id })\n    })).json();\n    if (el) el.textContent = d.ok ? d.message : (d.error || 'save failed');\n    if (d.ok) checkIg();\n  } catch (e) {\n    if (el) el.textContent = e.message;\n  }\n}\nfunction igPostClip(key, name) {\n  switchTool('editor');\n  const k = document.getElementById('ig-key');\n  const c = document.getElementById('ig-caption');\n  if (k) k.value = key;\n  if (c && !c.value) c.value = name.replace(/\\.[^.]+$/, '') + '\\n\\n#heymia';\n  checkIg();\n}\nasync function igPostNow() {\n  const key = (document.getElementById('ig-key')?.value || '').trim();\n  const caption = (document.getElementById('ig-caption')?.value || '').trim();\n  const el = document.getElementById('ig-job');\n  if (!key && !caption) { if (el) el.textContent = 'Need a clip key and a caption.'; return; }\n  if (el) el.textContent = 'Creating Instagram container…';\n  addMia('Posting to Instagram: ' + (key || 'url') + '.');\n  try {\n    const rec = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/instagram', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ key, caption })\n    })).json();\n    if (!rec.ok) {\n      if (el) el.textContent = rec.error || 'failed';\n      addMia('Instagram refused: ' + (rec.error || 'unknown'));\n      return;\n    }\n    if (el) el.textContent = rec.message;\n    pollIgJob(rec.job_id);\n  } catch (e) {\n    if (el) el.textContent = e.message;\n  }\n}\nasync function pollIgJob(id) {\n  if (!id) return;\n  const el = document.getElementById('ig-job');\n  for (let i = 0; i < 30; i++) {\n    await new Promise((r) => setTimeout(r, 4000));\n    try {\n      const j = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/social/instagram/jobs/' + id)).json();\n      if (el) el.textContent = (j.status || '') + (j.container_status ? ' · ' + j.container_status : '') + (j.media_id ? ' · media ' + j.media_id : '') + (j.error ? ' — ' + j.error : '');\n      if (j.status === 'published') {\n        addMia('Posted. Instagram media ' + (j.media_id || id) + '.');\n        return;\n      }\n      if (j.status === 'failed') {\n        addMia('Instagram failed: ' + (j.error || 'unknown'));\n        return;\n      }\n    } catch (e) {}\n  }\n}\nasync function downloadAllClips() {\n  const st = document.getElementById('clips-status');\n  try {\n    const d = await (await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clips')).json();\n    const clips = (d.clips || []).filter((c) => c.video || c.size);\n    if (!clips.length) { addMia('No clips to download yet.'); return; }\n    if (typeof JSZip === 'undefined') { addMia('JSZip missing — download clips one by one.'); return; }\n    if (st) st.textContent = 'Zipping ' + clips.length + '…';\n    const zip = new JSZip();\n    for (const c of clips) {\n      const res = await fetch(clipUrl(c, true));\n      zip.file(c.name, await res.arrayBuffer());\n    }\n    const blob = await zip.generateAsync({ type: 'blob' });\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = 'heymia-clips.zip';\n    a.click();\n    if (st) st.textContent = 'Downloaded heymia-clips.zip';\n    addMia('Clips zip downloaded (' + clips.length + ').');\n  } catch (e) {\n    addMia('Zip failed: ' + e.message);\n  }\n}\n\nasync function mktList() {\n  const box = document.getElementById('mkt-files');\n  if (!box) return;\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing?project=' + encodeURIComponent(state.mktProject));\n    const d = await res.json();\n    const files = (d.files || []).filter((f) => f.key.indexOf('/marketing/' + state.mktKind + '/') > -1);\n    box.innerHTML = files.length ? files.map((f) => `<div class=\"truncate\">${escapeHtml(f.key.split('/').pop())}</div>`).join('') : '<div>Empty — save a script or PNG into ' + state.mktProject + '/' + state.mktKind + '</div>';\n  } catch (e) {\n    box.textContent = 'Folders not on this Worker yet.';\n  }\n}\n\nasync function mktWriteScript() {\n  const brief = (document.getElementById('mkt-brief').value || '').trim() || ('15s marketing clip for ' + state.mktProject);\n  document.getElementById('mkt-status').textContent = 'Mia writing…';\n  const prompt = 'Write a 15-second marketing SCRIPT and on-screen CAPTIONS for product ' + state.mktProject + ' as a ' + state.mktKind + '. Brief: ' + brief + '. Format:\\nHOOK:\\nSCRIPT:\\nCAPTIONS:\\nCTA:\\nThen tell me which CapCut free tool to open.';\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/chat', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ message: prompt, messages:[{role:'user', content: prompt}], agent:'Mia', mode:'work' }) });\n    const d = await res.json();\n    document.getElementById('mkt-script').value = d.reply || d.response || '';\n    document.getElementById('mkt-status').textContent = 'Script ready. Save it, then open CapCut TTS / captions.';\n  } catch (e) {\n    document.getElementById('mkt-status').textContent = String(e.message || e);\n  }\n}\n\nasync function mktSaveScript() {\n  const text = document.getElementById('mkt-script').value || '';\n  if (!text.trim()) return;\n  const name = 'script-' + Date.now() + '.txt';\n  const kind = (state.mktKind === 'posts' || state.mktKind === 'clips' || state.mktKind === 'videos' || state.mktKind === 'ads' || state.mktKind === 'stories') ? 'scripts' : state.mktKind;\n  const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ project: state.mktProject, kind, name, content: text, type: 'text/plain;charset=UTF-8' }) });\n  const d = await res.json();\n  document.getElementById('mkt-status').textContent = d.ok ? 'Saved ' + d.key : (d.error || 'save failed');\n  addMia(d.ok ? 'Filed script into ' + d.key : 'Save failed');\n  mktList();\n}\n\nfunction mktDrawPost() {\n  const c = document.getElementById('mkt-canvas');\n  const ctx = c.getContext('2d');\n  const w = c.width, h = c.height;\n  const g = ctx.createLinearGradient(0,0,w,h);\n  g.addColorStop(0,'#2e1065'); g.addColorStop(1,'#9d174d');\n  ctx.fillStyle = g; ctx.fillRect(0,0,w,h);\n  const p = PRODUCTS_UI.find((x) => x.slug === state.mktProject);\n  const script = (document.getElementById('mkt-script').value || '').split('\\n').filter(Boolean);\n  const hook = (script.find((l) => /^HOOK/i.test(l)) || script[0] || (p && p.name) || 'HeyMia').replace(/^HOOK:\\s*/i,'');\n  ctx.fillStyle = '#fff';\n  ctx.font = 'bold 72px Plus Jakarta Sans, sans-serif';\n  wrapCanvasText(ctx, hook.slice(0, 90), 80, 280, w - 160, 84);\n  ctx.font = '32px Plus Jakarta Sans, sans-serif';\n  ctx.fillStyle = '#f9a8d4';\n  ctx.fillText((p && p.name) || state.mktProject, 80, h - 140);\n  ctx.fillStyle = '#fff';\n  ctx.font = '28px Plus Jakarta Sans, sans-serif';\n  const url = (p && p.urls && p.urls[0]) ? p.urls[0].replace(/^https?:\\/\\//,'') : 'heymia.lensflow.au';\n  ctx.fillText(url, 80, h - 90);\n}\n\nfunction wrapCanvasText(ctx, text, x, y, maxW, lh) {\n  const words = String(text).split(' ');\n  let line = '', yy = y;\n  for (const w of words) {\n    const test = line + w + ' ';\n    if (ctx.measureText(test).width > maxW) { ctx.fillText(line, x, yy); line = w + ' '; yy += lh; }\n    else line = test;\n  }\n  ctx.fillText(line, x, yy);\n}\n\nasync function mktSavePost() {\n  mktDrawPost();\n  const c = document.getElementById('mkt-canvas');\n  const data = c.toDataURL('image/png');\n  const name = 'post-' + Date.now() + '.png';\n  const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/marketing', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ project: state.mktProject, kind: 'posts', name, content: data, type: 'image/png' }) });\n  const d = await res.json();\n  document.getElementById('mkt-status').textContent = d.ok ? 'Saved ' + d.key : (d.error || 'save failed');\n  addMia(d.ok ? 'Post still filed in ' + d.key : 'PNG save failed');\n  mktList();\n}\n\n// ========== CAPCUT EDITOR ==========\nfunction edAction(act) {\n  if (act === 'export') {\n    addMia('Export requested. In production this renders via FFmpeg.wasm or CapCut desktop. Preview is ready.');\n    alert('Export demo complete. Source media can be downloaded from the preview.');\n  } else if (act === 'filter') {\n    const v = document.getElementById('ed-video');\n    v.style.filter = v.style.filter ? 'none' : 'sepia(0.3) saturate(1.3) brightness(1.05)';\n  }\n}\n\n// ========== LIVE AVATAR ==========\n\n// ========== WORK FAN STUDIO WEBCAM ==========\nstate.workCamStream = null;\nstate.workCamOn = true;\nstate.workMicOn = true;\n\nasync function startWorkCam() {\n  try {\n    state.workCamStream = await navigator.mediaDevices.getUserMedia({\n      video: { facingMode: 'user' },\n      audio: true,\n    });\n    const v = document.getElementById('work-user-cam');\n    if (v) {\n      v.srcObject = state.workCamStream;\n      v.muted = true;\n      await v.play().catch(() => {});\n    }\n    state.workCamOn = true;\n    state.workMicOn = true;\n    updateWorkCamUi();\n  } catch (e) {\n    console.warn(e);\n    addMia('Camera blocked. Allow camera in the browser address bar, then click Camera On.');\n    const off = document.getElementById('work-cam-off');\n    if (off) off.classList.remove('hidden');\n  }\n}\nfunction stopWorkCam() {\n  if (state.workCamStream) {\n    state.workCamStream.getTracks().forEach(tr => tr.stop());\n    state.workCamStream = null;\n  }\n  const v = document.getElementById('work-user-cam');\n  if (v) v.srcObject = null;\n}\nfunction updateWorkCamUi() {\n  const btn = document.getElementById('btn-work-cam');\n  const mic = document.getElementById('btn-work-mic');\n  const off = document.getElementById('work-cam-off');\n  if (btn) btn.textContent = state.workCamOn ? '📷 Camera On' : '📷 Camera Off';\n  if (mic) mic.textContent = state.workMicOn ? '🎤 Mic On' : '🎤 Mic Off';\n  if (off) {\n    if (state.workCamOn && state.workCamStream) off.classList.add('hidden');\n    else off.classList.remove('hidden');\n  }\n}\nfunction toggleWorkCam() {\n  if (!state.workCamStream) {\n    startWorkCam();\n    return;\n  }\n  state.workCamOn = !state.workCamOn;\n  state.workCamStream.getVideoTracks().forEach(tr => { tr.enabled = state.workCamOn; });\n  updateWorkCamUi();\n}\nfunction toggleWorkMic() {\n  if (!state.workCamStream) {\n    startWorkCam();\n    return;\n  }\n  state.workMicOn = !state.workMicOn;\n  state.workCamStream.getAudioTracks().forEach(tr => { tr.enabled = state.workMicOn; });\n  updateWorkCamUi();\n}\n\n\nasync function startLiveSession(companion) {\n  companion = companion || 'jess';\n  const status = document.getElementById('studio-status');\n  status.textContent = 'Creating ' + companion + ' session…';\n  try {\n    const base = WORKER_BASE.replace(/\\/$/, '');\n    const res = await fetch(base + '/session?companion=' + encodeURIComponent(companion));\n    if (!res.ok) throw new Error('session failed');\n    const data = await res.json();\n    state.liveSessionId = data.session_id;\n\n    await fetch(base + '/start', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ session_id: data.session_id, companion })\n    });\n\n    const iframe = document.getElementById('avatar-iframe');\n    const container = document.getElementById('avatar-container');\n    const embed =\n      data.avatar_url ||\n      (await (await fetch(base + '/config?companion=' + encodeURIComponent(companion))).json()).avatar_url;\n    iframe.src = embed;\n    iframe.classList.remove('hidden');\n    container.classList.add('hidden');\n    status.textContent = 'Live · ' + companion + ' · ' + data.session_id.slice(0, 8);\n    addMia('LiveAvatar (' + companion + ') started. Session ' + data.session_id.slice(0, 8));\n  } catch (err) {\n    status.textContent = 'Worker unreachable — using local preview';\n    addMia('Could not reach LiveAvatar Worker. Check WORKER_BASE and AVATAR_EMBED_URL_JESS.');\n  }\n}\n\nasync function stopLiveSession() {\n  if (state.liveSessionId) {\n    try {\n      await fetch(WORKER_BASE + '/stop', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ session_id: state.liveSessionId })\n      });\n    } catch {}\n  }\n  state.liveSessionId = null;\n  document.getElementById('avatar-iframe').classList.add('hidden');\n  document.getElementById('avatar-iframe').src = '';\n  document.getElementById('avatar-container').classList.remove('hidden');\n  document.getElementById('studio-status').textContent = 'Idle';\n  addMia('LiveAvatar session ended.');\n}\n\nfunction setStudioAgent(agent) {\n  state.studioAgent = agent;\n  const mia = document.getElementById('studio-agent-mia');\n  const jess = document.getElementById('studio-agent-jess');\n  if (mia && jess) {\n    mia.className = agent === 'mia'\n      ? 'px-4 py-1.5 rounded-full text-xs font-bold bg-purple-500 text-white'\n      : 'px-4 py-1.5 rounded-full text-xs font-bold bg-white/10 text-slate-300 hover:bg-white/15';\n    jess.className = agent === 'jess'\n      ? 'px-4 py-1.5 rounded-full text-xs font-bold bg-purple-500 text-white'\n      : 'px-4 py-1.5 rounded-full text-xs font-bold bg-white/10 text-slate-300 hover:bg-white/15';\n  }\n  addMia(agent === 'jess' ? 'Switched to Jess for Play / Fan Studio.' : 'Switched to Mia for Play / Fan Studio.');\n}\n\nfunction openLiveAvatar() {\n  switchMode('play');\n  switchTool('studio');\n  startLiveSession();\n}\n\n\n// ========== DEDUPE ==========\nfunction fileKey(f) {\n  return (f.name || '').toLowerCase() + '::' + (f.size || 0);\n}\nfunction scanDuplicates() {\n  const map = new Map();\n  const dups = [];\n  state.files.forEach(f => {\n    const k = fileKey(f);\n    if (!map.has(k)) map.set(k, []);\n    map.get(k).push(f);\n  });\n  map.forEach((arr, k) => {\n    if (arr.length > 1) dups.push({ key: k, files: arr });\n  });\n  state._dupGroups = dups;\n  const sum = document.getElementById('dedupe-summary');\n  const list = document.getElementById('dedupe-list');\n  if (!dups.length) {\n    sum.textContent = 'No duplicates found among ' + state.files.length + ' file(s).';\n    list.innerHTML = '';\n    addMia('Dedupe scan complete. No duplicates.');\n    return;\n  }\n  const extra = dups.reduce((n, g) => n + g.files.length - 1, 0);\n  sum.textContent = dups.length + ' duplicate group(s), ' + extra + ' extra file(s) can be removed.';\n  list.innerHTML = dups.map(g => `\n    <div class=\"p-3 rounded-xl bg-white/5 border border-white/10\">\n      <div class=\"font-medium text-pink-300 mb-1\">${g.files[0].name} · ${g.files[0].size} bytes · ×${g.files.length}</div>\n      <div class=\"text-slate-500\">${g.files.map(f => f.id).join(', ')}</div>\n    </div>`).join('');\n  addMia('Found ' + dups.length + ' duplicate group(s). Review Dedupe tab, then Remove or Download clean pack.');\n}\nfunction removeDuplicates() {\n  if (!state._dupGroups || !state._dupGroups.length) {\n    scanDuplicates();\n  }\n  if (!state._dupGroups || !state._dupGroups.length) {\n    addMia('Nothing to remove.');\n    return;\n  }\n  const keep = new Set();\n  const removeIds = new Set();\n  state._dupGroups.forEach(g => {\n    keep.add(g.files[0].id);\n    g.files.slice(1).forEach(f => removeIds.add(f.id));\n  });\n  const before = state.files.length;\n  state.files = state.files.filter(f => !removeIds.has(f.id));\n  state._dupGroups = [];\n  document.getElementById('dedupe-summary').textContent = 'Removed ' + (before - state.files.length) + ' duplicate(s). Vault now has ' + state.files.length + ' file(s).';\n  document.getElementById('dedupe-list').innerHTML = '';\n  renderCats();\n  renderFiles();\n  addMia('Removed duplicates. ' + state.files.length + ' file(s) remain in the vault.');\n}\nasync function downloadCleanPack() {\n  if (!state.files.length) {\n    addMia('Vault is empty. Upload files first.');\n    return;\n  }\n  if (typeof JSZip === 'undefined') {\n    addMia('JSZip not loaded. Check network / CDN.');\n    return;\n  }\n  addMia('Building clean pack…');\n  const zip = new JSZip();\n  const usedNames = new Set();\n  for (const f of state.files) {\n    let name = f.name || 'file';\n    if (usedNames.has(name)) {\n      const parts = name.split('.');\n      const ext = parts.length > 1 ? '.' + parts.pop() : '';\n      name = parts.join('.') + '-' + f.id.slice(-4) + ext;\n    }\n    usedNames.add(name);\n    try {\n      if (f.fileObj) {\n        zip.file(name, f.fileObj);\n      } else if (f.url) {\n        const res = await fetch(f.url);\n        zip.file(name, await res.blob());\n      }\n    } catch (e) {\n      zip.file(name + '.txt', 'Could not pack: ' + name);\n    }\n  }\n  const blob = await zip.generateAsync({ type: 'blob' });\n  const a = document.createElement('a');\n  a.href = URL.createObjectURL(blob);\n  a.download = 'heymia-clean-pack-' + new Date().toISOString().slice(0,10) + '.zip';\n  a.click();\n  URL.revokeObjectURL(a.href);\n  addMia('Clean pack downloaded (' + state.files.length + ' file(s)).');\n}\n\n// ========== API PANEL ==========\nfunction apiPreset(name) {\n  const base = (typeof WORKER_BASE !== 'undefined' ? WORKER_BASE : '').replace(/\\/$/, '');\n  document.getElementById('api-headers').value = JSON.stringify({ 'Content-Type': 'application/json' }, null, 0);\n  if (name === 'health') {\n    document.getElementById('api-method').value = 'GET';\n    document.getElementById('api-url').value = base + '/';\n    document.getElementById('api-body').value = '';\n  } else if (name === 'chat') {\n    document.getElementById('api-method').value = 'POST';\n    document.getElementById('api-url').value = base + '/chat';\n    document.getElementById('api-body').value = JSON.stringify({ message: 'Hello Mia', companion: 'mia' }, null, 2);\n  } else if (name === 'route') {\n    document.getElementById('api-method').value = 'POST';\n    document.getElementById('api-url').value = base + '/route';\n    document.getElementById('api-body').value = JSON.stringify({ fileName: 'test.mp3', fileType: 'audio/mpeg' }, null, 2);\n  } else if (name === 'packages') {\n    document.getElementById('api-method').value = 'GET';\n    document.getElementById('api-url').value = base + '/packages';\n    document.getElementById('api-body').value = '';\n  }\n}\nasync function sendApiRequest() {\n  const method = document.getElementById('api-method').value;\n  const url = document.getElementById('api-url').value.trim();\n  const statusEl = document.getElementById('api-status');\n  const out = document.getElementById('api-response');\n  if (!url) { out.textContent = 'URL required'; return; }\n  let headers = {};\n  try {\n    const h = document.getElementById('api-headers').value.trim();\n    if (h) headers = JSON.parse(h);\n  } catch {\n    out.textContent = 'Headers must be valid JSON';\n    return;\n  }\n  const opts = { method, headers };\n  if (method !== 'GET' && method !== 'HEAD') {\n    opts.body = document.getElementById('api-body').value;\n  }\n  statusEl.textContent = '…';\n  out.textContent = 'Sending…';\n  try {\n    const res = await fetch(url, opts);\n    const text = await res.text();\n    statusEl.textContent = res.status + ' ' + res.statusText;\n    try {\n      out.textContent = JSON.stringify(JSON.parse(text), null, 2);\n    } catch {\n      out.textContent = text;\n    }\n    addMia('API ' + method + ' ' + url + ' → ' + res.status);\n  } catch (e) {\n    statusEl.textContent = 'error';\n    out.textContent = e.message || String(e);\n  }\n}\n\n\n// ========== VOICE I/O ==========\nstate.autoVoice = localStorage.getItem('heymia_auto_voice') === '1';\nstate.voiceListening = false;\nlet _recognition = null;\n\nfunction toggleAutoVoice() {\n  state.autoVoice = !state.autoVoice;\n  localStorage.setItem('heymia_auto_voice', state.autoVoice ? '1' : '0');\n  const btn = document.getElementById('btn-voice-reply');\n  if (btn) {\n    btn.className = state.autoVoice\n      ? 'p-2 rounded-xl bg-pink-500/30 text-[10px] font-bold text-pink-200 shrink-0'\n      : 'p-2 rounded-xl glass-light text-[10px] font-bold text-slate-400 shrink-0';\n  }\n  addMia(state.autoVoice ? 'Voice replies ON — I will speak and show text.' : 'Voice replies OFF — text only.');\n}\n(function initVoiceBtn() {\n  setTimeout(() => {\n    const btn = document.getElementById('btn-voice-reply');\n    if (btn && state.autoVoice) {\n      btn.className = 'p-2 rounded-xl bg-pink-500/30 text-[10px] font-bold text-pink-200 shrink-0';\n    }\n  }, 100);\n})();\n\nfunction toggleVoiceInput() {\n  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n  if (!SR) {\n    addMia('Voice input needs Chrome or Edge on this device.');\n    return;\n  }\n  if (state.voiceListening && _recognition) {\n    _recognition.stop();\n    state.voiceListening = false;\n    document.getElementById('btn-mic')?.classList.remove('bg-pink-500/40', 'animate-pulse');\n    document.getElementById('voice-live')?.classList.add('hidden');\n    return;\n  }\n  _recognition = new SR();\n  _recognition.continuous = false;\n  _recognition.interimResults = true;\n  _recognition.lang = 'en-AU';\n  const live = document.getElementById('voice-live');\n  const input = document.getElementById('mia-input');\n  const mic = document.getElementById('btn-mic');\n  live.classList.remove('hidden');\n  live.textContent = 'Listening…';\n  mic.classList.add('bg-pink-500/40', 'animate-pulse');\n  state.voiceListening = true;\n  _recognition.onresult = (ev) => {\n    let interim = '';\n    let final = '';\n    for (let i = ev.resultIndex; i < ev.results.length; i++) {\n      const r = ev.results[i];\n      if (r.isFinal) final += r[0].transcript;\n      else interim += r[0].transcript;\n    }\n    const text = (final || interim).trim();\n    live.textContent = text || 'Listening…';\n    if (input) input.value = text;\n  };\n  _recognition.onerror = () => {\n    state.voiceListening = false;\n    mic.classList.remove('bg-pink-500/40', 'animate-pulse');\n    live.textContent = 'Mic error — try again';\n  };\n  _recognition.onend = () => {\n    state.voiceListening = false;\n    mic.classList.remove('bg-pink-500/40', 'animate-pulse');\n    const text = (input?.value || '').trim();\n    if (text) {\n      live.textContent = 'Sending…';\n      sendToMia(new Event('submit'));\n    }\n    setTimeout(() => live.classList.add('hidden'), 800);\n  };\n  _recognition.start();\n}\n\nasync function speakMiaText(text) {\n  if (!text || !state.autoVoice) return;\n  if (!WORKER_BASE) return;\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/tts', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ text: text.slice(0, 500), companion: 'mia' }),\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || 'tts failed');\n    const audio = new Audio('data:audio/mpeg;base64,' + data.audio);\n    await audio.play();\n  } catch (e) {\n    // fallback: browser speech synthesis\n    try {\n      const u = new SpeechSynthesisUtterance(text.slice(0, 500));\n      u.rate = 1;\n      speakMia(u);\n    } catch {}\n  }\n}\n\nfunction showPhoneLink() {\n  const url = window.location.href.split('?')[0];\n  addMia('On your phone, open this same address in the browser:\\n' + url + '\\n\\nSame tools. Vault files stay on each device until cloud vault is added — use Download clean pack, then open the zip on your phone, or upload from the phone camera/files into the vault here.');\n  if (navigator.share) {\n    navigator.share({ title: 'HeyMia', url }).catch(() => {});\n  } else {\n    prompt('Copy this URL on your phone:', url);\n  }\n}\n\n\n// ========== PANEL RESIZE ==========\n(function setupResize() {\n  let active = null;\n  let startX = 0;\n  let startW = 0;\n  const targets = {\n    mia: () => document.getElementById('mia-aside'),\n    cats: () => document.getElementById('vault-cats'),\n    preview: () => document.getElementById('vault-preview'),\n  };\n  document.querySelectorAll('.resize-handle').forEach(h => {\n    h.addEventListener('pointerdown', e => {\n      const key = h.getAttribute('data-resize');\n      const el = targets[key]?.();\n      if (!el) return;\n      active = { el, key, handle: h, dir: key === 'preview' ? -1 : 1 };\n      startX = e.clientX;\n      startW = el.getBoundingClientRect().width;\n      h.classList.add('dragging');\n      h.setPointerCapture(e.pointerId);\n      e.preventDefault();\n    });\n  });\n  window.addEventListener('pointermove', e => {\n    if (!active) return;\n    const dx = (e.clientX - startX) * active.dir;\n    const w = Math.min(Math.max(startW + dx, 160), window.innerWidth * 0.55);\n    active.el.style.width = w + 'px';\n  });\n  window.addEventListener('pointerup', () => {\n    if (!active) return;\n    active.handle.classList.remove('dragging');\n    try {\n      localStorage.setItem('heymia_w_' + active.key, active.el.style.width);\n    } catch {}\n    active = null;\n  });\n  // restore\n  ['mia','cats','preview'].forEach(k => {\n    const w = localStorage.getItem('heymia_w_' + k);\n    const el = targets[k]?.();\n    if (w && el) {\n      const n = parseFloat(w);\n      if (n >= 160) el.style.width = w;\n    }\n  });\n})();\n\n\nasync function loadCloudVault() {\n  if (!WORKER_BASE) return;\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/files');\n    if (!res.ok) return;\n    const data = await res.json();\n    if (!data.files || !data.files.length) return;\n    const existing = new Set(state.files.map(f => f.key).filter(Boolean));\n    const overrides = loadCatOverrides();\n    data.files.forEach(o => {\n      if (existing.has(o.key)) return;\n      const name = (o.customMetadata && o.customMetadata.originalName) || o.key.split('/').pop();\n        const ctype = (o.httpMetadata && o.httpMetadata.contentType) || 'application/octet-stream';\n        const cat = (o.customMetadata && o.customMetadata.category) || overrides[o.key] || guessCatFromCloud(name, ctype);\n        const project = o.project || (o.key || '').split('/')[1];\n      state.files.push({\n        id: 'r2-' + o.key,\n        key: o.key,\n        name,\n        type: ctype,\n        size: o.size || 0,\n        category: cat,\n        project,\n        url: WORKER_BASE.replace(/\\/$/, '') + '/files?key=' + encodeURIComponent(o.key),\n        status: 'cloud',\n      });\n    });\n    renderCats();\n    renderFiles();\n    addMia('Cloud vault loaded: ' + data.files.length + ' file(s) from R2.');\n  } catch (e) {}\n}\n\n\n// ========== SHELL ==========\nfunction shellPrint(line) {\n  const out = document.getElementById('shell-out');\n  if (!out) return;\n  out.textContent += line + '\\n';\n  out.scrollTop = out.scrollHeight;\n}\nfunction runShell(e) {\n  e.preventDefault();\n  const input = document.getElementById('shell-in');\n  const raw = (input.value || '').trim();\n  input.value = '';\n  if (!raw) return;\n  shellPrint('heymia> ' + raw);\n  const parts = raw.split(/\\s+/);\n  const cmd = parts[0].toLowerCase();\n  const arg = parts.slice(1).join(' ');\n  if (cmd === 'help') {\n    shellPrint('Commands:');\n    shellPrint('  help              this list');\n    shellPrint('  vault list        count vault files');\n    shellPrint('  cloud             reload R2 vault');\n    shellPrint('  dedupe            open dedupe tool');\n    shellPrint('  api health        ping worker /');\n    shellPrint('  play              open /play');\n    shellPrint('  work              focus work vault');\n    shellPrint('  github repos      list GitHub repos');\n    shellPrint('  clear             clear shell');\n    shellPrint('  ui status         active UI from R2?');\n    shellPrint('  upgrade list      files that look like upgrades');\n    shellPrint('  upgrade work KEY  activate work UI from R2 key');\n    shellPrint('  upgrade play KEY  activate play UI');\n    shellPrint('  upgrade reset     back to embedded Worker UI');\n    shellPrint('  persona drill     daily video personality drill');\n    shellPrint('  persona install   save traits from reference video');\n    shellPrint('  persona video KEY set video URL from R2 key');\n  } else if (cmd === 'clear') {\n    document.getElementById('shell-out').textContent = '';\n  } else if (cmd === 'vault' && (arg === 'list' || !arg)) {\n    shellPrint('Vault files: ' + state.files.length);\n    state.files.slice(0, 20).forEach(f => shellPrint('  - ' + f.name + (f.key ? ' [R2]' : ' [local]')));\n    if (state.files.length > 20) shellPrint('  …');\n  } else if (cmd === 'cloud') {\n    shellPrint('Reloading R2…');\n    if (typeof loadCloudVault === 'function') loadCloudVault();\n    else shellPrint('loadCloudVault not available');\n  } else if (cmd === 'dedupe') {\n    switchTool('dedupe');\n    if (typeof scanDuplicates === 'function') scanDuplicates();\n    shellPrint('Opened Dedupe');\n  } else if (cmd === 'play') {\n    location.href = '/play';\n  } else if (cmd === 'work') {\n    switchTool('vault');\n    shellPrint('Work / File Vault');\n  } else if (cmd === 'api' && arg === 'health') {\n    shellPrint('GET ' + WORKER_BASE + '/');\n    fetch(WORKER_BASE.replace(/\\/$/, '') + '/').then(r => r.json()).then(d => {\n      shellPrint(JSON.stringify(d, null, 2));\n    }).catch(err => shellPrint('Error: ' + err.message));\n  } else if (cmd === 'persona') {\n    const bits = arg.split(/\\s+/);\n    if (bits[0] === 'install') installPersonalityFromVideo();\n    else if (bits[0] === 'video' && bits[1]) {\n      const key = bits[1];\n      const url = WORKER_BASE.replace(/\\/$/, '') + '/files?key=' + encodeURIComponent(key);\n      setPersonalityVideoUrl(url);\n      shellPrint('Persona video URL set to ' + url);\n    } else {\n      dailyPersonalityDrill();\n    }\n  } else if (cmd === 'ui' && arg === 'status') {\n    uiStatus();\n  } else if (cmd === 'upgrade') {\n    const bits = arg.split(/\\s+/);\n    if (!arg || bits[0] === 'list') {\n      const ups = state.files.filter(f => /upgrade|\\.html$/i.test(f.name || '') || (f.key || '').includes('ui/'));\n      shellPrint('Upgrade candidates: ' + ups.length);\n      ups.forEach(f => shellPrint('  ' + (f.key || f.id) + ' · ' + f.name));\n    } else if (bits[0] === 'reset') {\n      resetUpgrade(bits[1] || 'work');\n    } else if (bits[0] === 'work' || bits[0] === 'play') {\n      activateUpgrade(bits[1], bits[0]);\n    } else {\n      activateUpgrade(bits[0], 'work');\n    }\n  } else if (cmd === 'github' && arg.startsWith('repo')) {\n    listGithubRepos(true);\n  } else {\n    shellPrint('Unknown command. Type help');\n  }\n}\n\n// ========== GITHUB ==========\nfunction saveGithubToken() {\n  const v = document.getElementById('gh-token').value.trim();\n  if (!v) return;\n  state.githubToken = v;\n  localStorage.setItem('heymia_github', v);\n  document.getElementById('gh-status').textContent = 'Token saved in this browser only.';\n  addMia('GitHub token saved.');\n}\nasync function listGithubRepos(fromShell) {\n  const token = state.githubToken || localStorage.getItem('heymia_github') || '';\n  if (!token) {\n    const msg = 'No GitHub token. Open GitHub tab and save a PAT (repo scope).';\n    if (fromShell) shellPrint(msg); else document.getElementById('gh-status').textContent = msg;\n    switchTool('github');\n    return;\n  }\n  document.getElementById('gh-status').textContent = 'Loading repos…';\n  try {\n    const res = await fetch('https://api.github.com/user/repos?per_page=50&sort=updated', {\n      headers: {\n        Authorization: 'Bearer ' + token,\n        Accept: 'application/vnd.github+json',\n      },\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.message || res.status);\n    const box = document.getElementById('gh-repos');\n    box.innerHTML = data.map(r => `\n      <a class=\"block p-3 rounded-xl bg-white/5 hover:bg-white/10 border border-white/5\" href=\"${r.html_url}\" target=\"_blank\" rel=\"noopener\">\n        <div class=\"font-medium\">${r.full_name}</div>\n        <div class=\"text-slate-500 text-[10px]\">${r.private ? 'private' : 'public'} · ${r.language || '—'} · updated ${new Date(r.updated_at).toLocaleDateString()}</div>\n      </a>`).join('');\n    document.getElementById('gh-status').textContent = data.length + ' repos';\n    if (fromShell) {\n      shellPrint(data.length + ' repos:');\n      data.slice(0, 15).forEach(r => shellPrint('  ' + r.full_name));\n    }\n    addMia('GitHub: listed ' + data.length + ' repos.');\n  } catch (e) {\n    document.getElementById('gh-status').textContent = 'Error: ' + e.message;\n    if (fromShell) shellPrint('GitHub error: ' + e.message);\n  }\n}\n\n\n// ========== MODES / SKILLS / KNOWLEDGE ==========\nconst MIA_MODES = {\n  plain: 'Mode PLAIN: clear, direct, no fluff, not rude. Short practical answers.',\n  soft: 'Mode SOFT: warm, conversational, patient. You may use a gentle line of small talk. Still helpful.',\n  build: 'Mode BUILD: technical and structured. Prefer steps, checklists, file names, commands. No emotional filler.',\n  grok: 'Mode GROK: xAI Grok-4.5 troubleshoots the Worker, vault, deploy, DNS, and this UI. Short numbered fixes.',\n};\n\nfunction setMiaMode(mode, silent) {\n  state.miaMode = mode;\n  localStorage.setItem('heymia_mode', mode);\n  document.querySelectorAll('.mia-mode').forEach(btn => {\n    const on = btn.getAttribute('data-mode') === mode;\n    btn.className = on\n      ? 'mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold tab-active'\n      : 'mia-mode px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300';\n  });\n  if (!silent) addMia('Mode set to ' + mode + '.');\n  try { trackMiaSignal('mode', mode); } catch(e) {}\n}\n\nfunction toggleSkill(id) {\n  state.skills[id] = !state.skills[id];\n  localStorage.setItem('heymia_skills', JSON.stringify(state.skills));\n  document.querySelectorAll('.mia-skill').forEach(btn => {\n    const sid = btn.getAttribute('data-skill');\n    const on = !!state.skills[sid];\n    btn.className = on\n      ? 'mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-pink-300'\n      : 'mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400';\n  });\n  addMia((state.skills[id] ? 'Enabled' : 'Disabled') + ' skill: ' + id);\n}\n\nfunction renderKnowledge() {\n  const log = document.getElementById('knowledge-log');\n  if (!log) return;\n  if (!state.knowledge.length) {\n    log.innerHTML = '<div class=\"text-slate-500\">No knowledge entries yet.</div>';\n    return;\n  }\n  log.innerHTML = state.knowledge.map((n, i) => `\n    <div class=\"p-3 rounded-xl bg-white/5 flex justify-between gap-2\">\n      <div><div class=\"text-[10px] text-slate-500 mb-0.5\">${n.date || ''}</div>${escapeHtml(n.text)}</div>\n      <button onclick=\"removeKnowledge(${i})\" class=\"text-slate-500 hover:text-red-400 text-xs shrink-0\">✕</button>\n    </div>`).join('');\n}\n\nfunction saveKnowledge() {\n  const input = document.getElementById('knowledge-input');\n  const text = (input?.value || '').trim();\n  if (!text) return;\n  state.knowledge.unshift({ text, date: new Date().toLocaleString() });\n  localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge));\n  input.value = '';\n  renderKnowledge();\n  addMia('Knowledge saved. I will use it in replies.');\n}\n\nfunction removeKnowledge(i) {\n  state.knowledge.splice(i, 1);\n  localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge));\n  renderKnowledge();\n}\n\nfunction buildMiaSystem() {\n  const mode = MIA_MODES[state.miaMode] || MIA_MODES.plain;\n  const skillsOn = Object.entries(state.skills || {}).filter(([, v]) => v).map(([k]) => k);\n  const skillLine = skillsOn.length\n    ? 'Active skills (prefer using these tools): ' + skillsOn.join(', ') + '.'\n    : 'No special skills flagged.';\n  const know = (state.knowledge || []).slice(0, 12).map(k => '- ' + k.text).join('\\n');\n  const train = (state.trainingNotes || []).slice(0, 8).map(k => '- ' + k.text).join('\\n');\n  return `You are Mia. Talk like a real colleague. First sentence: show you heard THIS message. No filler (Great question, I hear you, I'd be happy to).\n${mode}\n${skillLine}\nNotes you were trained on:\n${train || '- (none)'}\n${know ? 'Knowledge:\\n'+know : ''}\nDo not invent secrets.`;\n}\n\n// init mode/skill UI after load\nfunction initMiaControls() {\n  try {\n    setMiaMode(state.miaMode || 'plain', true);\n    // suppress extra addMia from setMiaMode on boot - optional\n    document.querySelectorAll('.mia-skill').forEach(btn => {\n      const sid = btn.getAttribute('data-skill');\n      const on = !!(state.skills && state.skills[sid]);\n      btn.className = on\n        ? 'mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-pink-300'\n        : 'mia-skill px-2 py-0.5 rounded-md text-[9px] glass-light text-slate-400';\n    });\n    renderKnowledge();\n  } catch (e) {}\n}\n\n\n// ========== SELF-UPGRADE ==========\nasync function activateUpgrade(key, target) {\n  target = target || 'work';\n  if (!key) {\n    addMia('No R2 key. Upload an HTML file first, then activate.');\n    return;\n  }\n  addMia('Activating UI upgrade (' + target + ')…');\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/ui/activate', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ key, target }),\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || res.status);\n    addMia('Upgrade live: ' + data.activeKey + '. Hard refresh (Ctrl+Shift+R).');\n    showDeployResult({ ok: true, action: 'activate_ui', name: data.activeKey || key, url: data.url, at: new Date().toISOString() });\n    if (typeof shellPrint === 'function') shellPrint(JSON.stringify(data, null, 2));\n  } catch (e) {\n    addMia('Upgrade failed: ' + e.message);\n    showDeployResult({ ok: false, action: 'activate_ui', name: key, error: String(e.message || e), at: new Date().toISOString() });\n  }\n}\nasync function uiStatus() {\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/ui/status');\n    const data = await res.json();\n    addMia('UI status: work=' + (data.workActive || (data.work && data.work.active)) + ' play=' + (data.playActive || (data.play && data.play.active)));\n    if (typeof shellPrint === 'function') shellPrint(JSON.stringify(data, null, 2));\n    return data;\n  } catch (e) {\n    addMia('UI status error: ' + e.message);\n  }\n}\nasync function resetUpgrade(target) {\n  target = target || 'work';\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/ui/reset', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ target }),\n    });\n    const data = await res.json();\n    addMia(data.message || 'Reset done. Hard refresh.');\n  } catch (e) {\n    addMia('Reset failed: ' + e.message);\n  }\n}\n\n\n\n// ========== JESS TRAINER (memory · emotion · intimacy) ==========\nstate.trainerCompanion = localStorage.getItem('heymia_trainer_comp') || 'mia';\nstate.jessKnowledge = JSON.parse(localStorage.getItem('heymia_jess_knowledge') || '[]');\nstate.jessTraining = JSON.parse(localStorage.getItem('heymia_jess_training') || '[]');\nstate.jessTrainerLog = JSON.parse(localStorage.getItem('heymia_jess_trainer_log') || '[]');\nstate.jessTrainerPending = [];\nstate.jessMetrics = JSON.parse(localStorage.getItem('heymia_jess_metrics') || '{}');\nstate.jessQuoteDrill = JSON.parse(localStorage.getItem('heymia_jess_quote') || 'null');\n\nconst JESS_TRAINER_SYSTEM = `You are the Trainer AI for Jess (Fan Studio companion). You are NOT Jess and NOT Mia.\nYour only job is daily training for Jess: memory, emotional range, and high-intimacy performance.\nFocus areas:\n- Identity: Jess is bold, teasing, confident, fan-studio energy — separate from Mia\n- Intimacy ladder: flirty → explicit → intense; match user pace; never dull\n- Emotional reads: desire, jealousy play, aftercare tone when needed\n- Room awareness: Bedroom, Dungeon, Penthouse, Velvet Lounge\n- Memory: names, preferences, boundaries the owner records\nOutput clear lines starting with RULE: or KNOW: for Jess.\nShort, practical. No casual companion chat.`;\n\nconst JESS_QUOTE_BANK = [\n  'Come closer. Say it slower.',\n  'I remember what you like — do not make me wait.',\n  'In this room, you ask; I decide how slow.',\n  'Heat first, manners second.',\n  'Tell me exactly what you want from Jess tonight.',\n];\n\nfunction setTrainerCompanion(id) {\n  state.trainerCompanion = id === 'jess' ? 'jess' : 'mia';\n  localStorage.setItem('heymia_trainer_comp', state.trainerCompanion);\n  document.querySelectorAll('.trainer-comp').forEach(btn => {\n    const on = btn.getAttribute('data-tc') === state.trainerCompanion;\n    btn.className = on\n      ? 'trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold tab-active'\n      : 'trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300';\n  });\n  const who = document.getElementById('trainer-who');\n  if (who) who.textContent = state.trainerCompanion === 'jess' ? 'Jess' : 'Mia';\n  const box = document.getElementById('trainer-chat');\n  if (box) {\n    box.innerHTML = '';\n    box.dataset.started = '';\n  }\n  startDailyTrainingSession();\n}\n\n\n// ========== TRAINER AI (daily training specialist) ==========\nstate.trainerLog = JSON.parse(localStorage.getItem('heymia_trainer_log') || '[]');\nstate.trainerPending = [];\n\nconst TRAINER_SYSTEM = `You are the Trainer AI for HeyMia. Your ONLY job is to help the owner train Mia every day.\nYou are not Mia. You are not a companion. You do not flirt.\nYou:\n- Ask what should change about Mia today (tone, facts, boundaries, business rules, Mia vs Jess identity)\n- Turn the owner's notes into clear TRAINING RULES and KNOWLEDGE bullets\n- Suggest a short daily drill (3 questions to test Mia later)\n- Keep replies structured and practical\nFormat useful rules as lines starting with RULE: or KNOW:\nOwner trains Mia for Lensflow / Glimr. Mia is ops + companion identity; Jess is a separate companion.`;\n\nfunction trainerBubble(who, text) {\n  const box = document.getElementById('trainer-chat');\n  if (!box) return;\n  const div = document.createElement('div');\n  const isUser = who === 'You';\n  div.className = (isUser ? 'msg-user ml-6' : 'msg-mia mr-6') + ' rounded-2xl p-3';\n  div.innerHTML = `<div class=\"text-[10px] font-bold ${isUser ? 'text-pink-300' : 'text-purple-300'} mb-1\">${who}</div>${escapeHtml(text)}`;\n  box.appendChild(div);\n  box.scrollTop = box.scrollHeight;\n}\n\nfunction startDailyTrainingSession() {\n  switchTool('trainer');\n  try {\n    document.querySelectorAll('.trainer-comp').forEach(btn => {\n      const on = btn.getAttribute('data-tc') === (state.trainerCompanion || 'mia');\n      btn.className = on\n        ? 'trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold tab-active'\n        : 'trainer-comp px-2 py-0.5 rounded-md text-[10px] font-bold glass-light text-slate-300';\n    });\n    const who = document.getElementById('trainer-who');\n    if (who) who.textContent = state.trainerCompanion === 'jess' ? 'Jess' : 'Mia';\n  } catch (e) {}\n  const box = document.getElementById('trainer-chat');\n  if (box && !box.dataset.started) {\n    box.dataset.started = '1';\n    if (state.trainerCompanion === 'jess') {\n      trainerBubble('Trainer', [\n        'Jess daily training — memory, emotion, intimacy.',\n        '',\n        '1) Intimacy: what should Jess do better in the rooms?',\n        '2) Emotion: confidence, tease, aftercare, jealousy play?',\n        '3) Memory: any preferences or boundaries to lock in?',\n        '4) Identity: keep Jess bold — never confuse with Mia.',\n        '',\n        'I will output RULE: and KNOW: for Jess. Press Save into Mia/Jess when ready.'\n      ].join('\\n'));\n    } else {\n      trainerBubble('Trainer', [\n        'Mia daily training session.',\n        '',\n        '1) What should Mia do better today?',\n        '2) Any new facts (business, Mia vs Jess, boundaries)?',\n        '3) Tone: Plain, Soft, or Build?',\n        '',\n        'I will turn your answers into RULE: and KNOW: lines. Press Save when ready.'\n      ].join('\\n'));\n    }\n  }\n}\n\nasync function sendTrainer() {\n  const input = document.getElementById('trainer-input');\n  const text = (input?.value || '').trim();\n  if (!text) return;\n  input.value = '';\n  trainerBubble('You', text);\n  const isJess = state.trainerCompanion === 'jess';\n  if (isJess) {\n    state.jessTrainerLog.push({ role: 'user', text, date: new Date().toISOString() });\n  } else {\n    state.trainerLog.push({ role: 'user', text, date: new Date().toISOString() });\n  }\n\n  let reply = null;\n  const prompt = (isJess ? JESS_TRAINER_SYSTEM : TRAINER_SYSTEM) + '\\n\\nOwner says:\\n' + text + '\\n\\nRespond as Trainer AI only.';\n\n  try {\n    if (WORKER_BASE) {\n      const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/chat', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          message: prompt,\n          companion: 'mia',\n          model: 'auto',\n        }),\n      });\n      if (res.ok) {\n        const data = await res.json();\n        reply = data.reply;\n      }\n    }\n  } catch (e) {}\n\n  if (!reply && state.geminiKey) {\n    try {\n      const res = await fetch(\n        `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent?key=${state.geminiKey}`,\n        {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({\n            contents: [{ role: 'user', parts: [{ text: prompt }] }],\n            generationConfig: { temperature: 0.4, maxOutputTokens: 500 },\n          }),\n        }\n      );\n      const data = await res.json();\n      reply = data.candidates?.[0]?.content?.parts?.[0]?.text;\n    } catch (e) {}\n  }\n\n  if (!reply) {\n    reply = 'Recorded. Add Gemini key for full Trainer replies.\\nSuggested:\\nKNOW: ' + text.slice(0, 200) + '\\nRULE: Apply this in future Mia replies.\\n\\nPress Save into Mia to store.';\n    state.trainerPending.push('KNOW: ' + text.slice(0, 300));\n  } else {\n    reply.split('\\n').forEach(line => {\n      const s = line.trim();\n      if (s.startsWith('RULE:') || s.startsWith('KNOW:')) state.trainerPending.push(s);\n    });\n  }\n\n  trainerBubble('Trainer', reply);\n  if (state.trainerCompanion === 'jess') {\n    state.jessTrainerLog.push({ role: 'trainer', text: reply, date: new Date().toISOString() });\n    localStorage.setItem('heymia_jess_trainer_log', JSON.stringify(state.jessTrainerLog.slice(-100)));\n    (reply || '').split('\\n').forEach(line => {\n      const s = line.trim();\n      if (s.startsWith('RULE:') || s.startsWith('KNOW:')) state.jessTrainerPending.push(s);\n    });\n  } else {\n    state.trainerLog.push({ role: 'trainer', text: reply, date: new Date().toISOString() });\n    localStorage.setItem('heymia_trainer_log', JSON.stringify(state.trainerLog.slice(-100)));\n  }\n}\n\nfunction commitTrainerToMia() {\n  const isJess = state.trainerCompanion === 'jess';\n  let added = 0;\n  let pending = isJess ? state.jessTrainerPending.slice() : state.trainerPending.slice();\n  const log = isJess ? state.jessTrainerLog : state.trainerLog;\n  log.slice(-5).forEach(e => {\n    if (e.role !== 'trainer') return;\n    (e.text || '').split('\\n').forEach(line => {\n      const s = line.trim();\n      if (s.startsWith('RULE:') || s.startsWith('KNOW:')) pending.push(s);\n    });\n  });\n  const unique = [...new Set(pending)];\n  unique.forEach(line => {\n    const body = line.replace(/^(RULE:|KNOW:)\\s*/i, '').trim();\n    if (!body) return;\n    if (isJess) {\n      if (line.toUpperCase().startsWith('RULE')) {\n        state.jessTraining.unshift({ text: body, date: new Date().toLocaleString() });\n      } else {\n        state.jessKnowledge.unshift({ text: body, date: new Date().toLocaleString() });\n      }\n    } else {\n      if (line.toUpperCase().startsWith('RULE')) {\n        state.trainingNotes.unshift({ text: body, date: new Date().toLocaleString() });\n      } else {\n        state.knowledge.unshift({ text: body, date: new Date().toLocaleString() });\n      }\n    }\n    added++;\n  });\n  if (isJess) {\n    state.jessTraining = state.jessTraining.slice(0, 50);\n    state.jessKnowledge = state.jessKnowledge.slice(0, 50);\n    localStorage.setItem('heymia_jess_training', JSON.stringify(state.jessTraining));\n    localStorage.setItem('heymia_jess_knowledge', JSON.stringify(state.jessKnowledge));\n    state.jessTrainerPending = [];\n  } else {\n    state.trainingNotes = state.trainingNotes.slice(0, 50);\n    state.knowledge = state.knowledge.slice(0, 50);\n    localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n    localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge));\n    state.trainerPending = [];\n    if (typeof renderTraining === 'function') renderTraining();\n    if (typeof renderKnowledge === 'function') renderKnowledge();\n  }\n  const name = isJess ? 'Jess' : 'Mia';\n  trainerBubble('Trainer', added ? ('Saved ' + added + ' item(s) into ' + name + ' training/knowledge.') : 'Nothing to save yet. Ask for RULE: and KNOW: lines first.');\n  addMia(added ? ('Trainer saved ' + added + ' items for ' + name + '.') : 'Trainer had nothing new to save.');\n}\n\n\n// ========== DAILY MIA PERFORMANCE REPORT ==========\nstate.miaMetrics = JSON.parse(localStorage.getItem('heymia_mia_metrics') || '{}');\nstate.dailyReports = JSON.parse(localStorage.getItem('heymia_daily_reports') || '[]');\n\nfunction trackMiaSignal(kind, value) {\n  const day = new Date().toDateString();\n  if (!state.miaMetrics[day]) {\n    state.miaMetrics[day] = {\n      messages: 0, fallbacks: 0, replies: 0, replyChars: 0, softChars: 0,\n      soft: 0, plain: 0, build: 0, voice: 0, userCorrections: 0,\n      aggressionFlags: 0, memoryHits: 0,\n    };\n  }\n  const m = state.miaMetrics[day];\n  if (kind === 'message') m.messages++;\n  if (kind === 'fallback') m.fallbacks++;\n  if (kind === 'reply') { m.replies++; m.replyChars += (value || 0); }\n  if (kind === 'mode') m[value] = (m[value] || 0) + 1;\n  if (kind === 'voice') m.voice++;\n  if (kind === 'correction') m.userCorrections++;\n  if (kind === 'aggression') m.aggressionFlags++;\n  if (kind === 'memory') m.memoryHits++;\n  localStorage.setItem('heymia_mia_metrics', JSON.stringify(state.miaMetrics));\n}\n\nfunction scoreFromDay(m) {\n  m = m || {};\n  const msgs = Math.max(m.messages || 0, 1);\n  const fbRate = (m.fallbacks || 0) / msgs;\n  const avgLen = (m.replies ? (m.replyChars || 0) / m.replies : 0);\n  const confidence = Math.round(Math.max(0, Math.min(100, 70 - fbRate * 80 + Math.min(avgLen, 200) / 10)));\n  const memory = Math.round(Math.min(100, 40 + (state.knowledge?.length || 0) * 3 + (state.trainingNotes?.length || 0) * 3 + (m.memoryHits || 0) * 5));\n  const aggression = Math.round(Math.min(100, (m.aggressionFlags || 0) * 15 + fbRate * 20));\n  const communication = Math.round(Math.max(0, Math.min(100, 55 + Math.min(avgLen, 180) / 8 - fbRate * 50 - (m.userCorrections || 0) * 8)));\n  const emotion = Math.round(Math.min(100, 50 + (m.soft || 0) * 5 + (state.miaMode === 'soft' ? 15 : 0) - aggression / 5));\n  const responseQuality = Math.round(Math.max(0, Math.min(100, 60 - fbRate * 70 + (m.replies || 0) * 2)));\n  return { confidence, memory, aggression, communication, emotion, responseQuality, fbRate, msgs, avgLen };\n}\n\nfunction reportNarrative(scores, m) {\n  const lines = [];\n  lines.push('MIA DAILY REPORT — ' + new Date().toLocaleDateString());\n  lines.push('');\n  lines.push('Scores (0–100)');\n  lines.push('• Confidence:        ' + scores.confidence);\n  lines.push('• Response quality:  ' + scores.responseQuality);\n  lines.push('• Memory base:       ' + scores.memory);\n  lines.push('• Aggression risk:   ' + scores.aggression + ' (lower is calmer)');\n  lines.push('• Emotional range:   ' + scores.emotion);\n  lines.push('• Communication:     ' + scores.communication);\n  lines.push('');\n  lines.push('Activity today');\n  lines.push('• User messages tracked: ' + (m.messages || 0));\n  lines.push('• Replies: ' + (m.replies || 0) + ' · Fallback hits: ' + (m.fallbacks || 0));\n  lines.push('• Knowledge items: ' + (state.knowledge?.length || 0) + ' · Training notes: ' + (state.trainingNotes?.length || 0));\n  lines.push('• Mode bias: plain=' + (m.plain||0) + ' soft=' + (m.soft||0) + ' build=' + (m.build||0));\n  lines.push('');\n  lines.push('Trainer assessment');\n  if (scores.fbRate > 0.3) lines.push('• Chat is still relying on fallbacks — fix Gemini/Worker chat before personality work.');\n  else lines.push('• Model path looks usable; focus training on tone and facts.');\n  if (scores.aggression >= 40) lines.push('• Aggression/shortness elevated — prefer Soft mode + RULE: stay warm, no snap replies.');\n  if (scores.memory < 50) lines.push('• Memory thin — add KNOW: facts (Mia identity, Jess separate, business rules).');\n  if (scores.communication < 55) lines.push('• Communication weak — daily drill: answer in 2–4 full sentences.');\n  if (scores.confidence >= 70 && scores.fbRate < 0.2) lines.push('• Confidence healthy for today.');\n  lines.push('');\n  lines.push('Recommended focus tomorrow');\n  if (scores.fbRate > 0.3) lines.push('1. Unlock real AI replies (Gemini key + Worker /chat).');\n  else if (scores.memory < 55) lines.push('1. Add 3 KNOW: lines about identity and business.');\n  else if (scores.aggression >= 35) lines.push('1. Soft mode + anti-snap RULE.');\n  else lines.push('1. One roleplay drill: “Who are you?” “Who is Jess?” “What is Glimr?”');\n  lines.push('2. Run Trainer session and Save into Mia.');\n  lines.push('3. One voice test if ElevenLabs is configured.');\n  return lines.join('\\n');\n}\n\nfunction generateDailyReport() {\n  switchTool('trainer');\n  const day = new Date().toDateString();\n  const m = state.miaMetrics[day] || { messages: 0, fallbacks: 0, replies: 0, replyChars: 0 };\n  const scores = scoreFromDay(m);\n  const text = reportNarrative(scores, m);\n  const report = { date: day, scores, text, createdAt: new Date().toISOString() };\n  // once per day: replace today's report if exists\n  state.dailyReports = (state.dailyReports || []).filter(r => r.date !== day);\n  state.dailyReports.unshift(report);\n  state.dailyReports = state.dailyReports.slice(0, 30);\n  localStorage.setItem('heymia_daily_reports', JSON.stringify(state.dailyReports));\n  trainerBubble('Trainer', text);\n  addMia('Daily report ready in Trainer AI.');\n  return report;\n}\n\nfunction maybeAutoDailyReport() {\n  try {\n    const day = new Date().toDateString();\n    const last = localStorage.getItem('heymia_last_auto_report');\n    if (last === day) return;\n    // only auto once per calendar day when Trainer or app opens\n    localStorage.setItem('heymia_last_auto_report', day);\n    // light notification in Mia chat, full text in Trainer\n    const m = state.miaMetrics[day] || {};\n    const scores = scoreFromDay(m);\n    addMia('Trainer: daily report available — confidence ' + scores.confidence + ', communication ' + scores.communication + '. Open Trainer AI → Daily report.');\n    addMia('Persona drill ready — open Trainer AI → Daily persona drill (reference video energy).');\n  } catch (e) {}\n}\n\n\n// ========== TRIGGERS · REINFORCEMENT · QUOTE MEMORY ==========\nconst BEHAVIOR_TRIGGERS = [\n  { id: 'fallback_loop', re: /I hear you|Tell me more|What do you need right now|I.m here\\. Tell me more/i, label: 'Fallback loop' },\n  { id: 'identity_confusion', re: /\\b(I am Jess|I'm Jess|as Jess)\\b/i, label: 'Identity confusion' },\n  { id: 'snap', re: /^(No\\.|Wrong\\.|Stop\\.)/i, label: 'Snap / hard no' },\n  { id: 'warm', re: /\\b(I.m with you|take your time|I hear you carefully|glad you.re here)\\b/i, label: 'Warm tone' },\n  { id: 'clear_help', re: /\\b(here.s what we.ll do|step 1|you can upload|open the)\\b/i, label: 'Clear guidance' },\n  { id: 'memory_use', re: /\\b(as you (said|told|asked)|you mentioned|from training|you prefer)\\b/i, label: 'Used memory' },\n];\n\nconst REINFORCEMENTS = [\n  'Good — that was clear and calm. Keep that tone.',\n  'Nice memory use. That’s the standard.',\n  'Strong help. More of this, less short snaps.',\n  'Identity correct. You are Mia; Jess is separate. Well done.',\n  'Warm and useful — that’s Soft done right.',\n];\n\nstate.quoteDrill = JSON.parse(localStorage.getItem('heymia_quote_drill') || 'null');\nstate.triggerEvents = JSON.parse(localStorage.getItem('heymia_triggers') || '[]');\n\nconst QUOTE_BANK = [\n  'Small steps still move the mountain.',\n  'Clarity is kindness.',\n  'Mia builds; Jess plays — know the room.',\n  'Remember the user before you answer.',\n  'Calm first, clever second.',\n  'What we train today, we test tomorrow.',\n];\n\nfunction logTrigger(id, label, sample) {\n  const day = new Date().toDateString();\n  const ev = { id, label, sample: (sample || '').slice(0, 80), day, at: Date.now() };\n  state.triggerEvents.unshift(ev);\n  state.triggerEvents = state.triggerEvents.slice(0, 100);\n  localStorage.setItem('heymia_triggers', JSON.stringify(state.triggerEvents));\n  try { trackMiaSignal(id === 'snap' || id === 'fallback_loop' ? 'aggression' : 'memory'); } catch (e) {}\n  renderTriggerPanel();\n}\n\nfunction renderTriggerPanel() {\n  const el = document.getElementById('trigger-log');\n  if (!el) return;\n  const day = new Date().toDateString();\n  const today = state.triggerEvents.filter(e => e.day === day);\n  el.textContent = today.length ? today.slice(0, 8).map(e => e.label).join(' · ') : 'None yet';\n}\n\nfunction positiveReinforce(reason) {\n  const line = REINFORCEMENTS[Math.floor(Math.random() * REINFORCEMENTS.length)];\n  const msg = 'Reinforcement: ' + line + (reason ? ' (' + reason + ')' : '');\n  const el = document.getElementById('reinforce-log');\n  if (el) el.textContent = line;\n  try { addMia(msg); } catch (e) {}\n  try { trackMiaSignal('memory'); } catch (e) {}\n}\n\nfunction scanReplyForBehavior(text) {\n  if (!text) return;\n  let reinforced = false;\n  BEHAVIOR_TRIGGERS.forEach(tr => {\n    if (tr.re.test(text)) {\n      logTrigger(tr.id, tr.label, text);\n      if (tr.id === 'warm' || tr.id === 'clear_help' || tr.id === 'memory_use') {\n        if (!reinforced) {\n          positiveReinforce(tr.label);\n          reinforced = true;\n        }\n      }\n    }\n  });\n}\n\nfunction assignDailyQuote() {\n  const quote = QUOTE_BANK[Math.floor(Math.random() * QUOTE_BANK.length)];\n  const tomorrow = new Date();\n  tomorrow.setDate(tomorrow.getDate() + 1);\n  state.quoteDrill = {\n    quote,\n    assignedOn: new Date().toDateString(),\n    testOn: tomorrow.toDateString(),\n    savedToTraining: true,\n    lastResult: null,\n  };\n  localStorage.setItem('heymia_quote_drill', JSON.stringify(state.quoteDrill));\n  state.trainingNotes.unshift({\n    text: 'Daily quote to remember: \"' + quote + '\" — if asked, recite it exactly.',\n    date: new Date().toLocaleString(),\n  });\n  state.trainingNotes = state.trainingNotes.slice(0, 50);\n  localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n  if (typeof renderTraining === 'function') renderTraining();\n  updateQuoteStatus();\n  trainerBubble('Trainer', ['Quote assigned for tomorrow test:', '', '\"' + quote + '\"', '', 'Saved into Mia training. Tomorrow: Test recall.'].join('\\n'));\n  addMia('I will try to remember this quote: \"' + quote + '\"');\n}\n\nfunction updateQuoteStatus() {\n  const el = document.getElementById('quote-status');\n  if (!el) return;\n  if (!state.quoteDrill) {\n    el.textContent = 'No active quote';\n    return;\n  }\n  const q = state.quoteDrill;\n  el.textContent = '\"' + q.quote.slice(0, 40) + (q.quote.length > 40 ? '…' : '') + '\" · test ' + q.testOn + (q.lastResult ? ' · last: ' + q.lastResult : '');\n}\n\nasync function runQuoteMemoryTest() {\n  if (!state.quoteDrill || !state.quoteDrill.quote) {\n    trainerBubble('Trainer', 'No quote assigned. Press Assign quote first.');\n    return;\n  }\n  const expected = state.quoteDrill.quote.trim().toLowerCase();\n  trainerBubble('Trainer', 'Testing Mia recall… Asking her for the daily quote.');\n  // Ask via same channels as chat\n  let reply = null;\n  const ask = 'What is the daily quote you were trained to remember? Recite it exactly if you know it.';\n  try {\n    if (WORKER_BASE) {\n      const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/chat', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ message: ask, companion: 'mia' }),\n      });\n      if (res.ok) reply = (await res.json()).reply;\n    }\n  } catch (e) {}\n  if (!reply && state.geminiKey) {\n    try {\n      const system = (typeof buildMiaSystem === 'function' ? buildMiaSystem() : '') + '\\nUser asks for the daily quote.';\n      const res = await fetch(\n        `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent?key=${state.geminiKey}`,\n        {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({\n            contents: [{ role: 'user', parts: [{ text: system + '\\n\\nUser: ' + ask }] }],\n            generationConfig: { temperature: 0.2, maxOutputTokens: 200 },\n          }),\n        }\n      );\n      const data = await res.json();\n      reply = data.candidates?.[0]?.content?.parts?.[0]?.text;\n    } catch (e) {}\n  }\n  if (!reply) reply = '';\n  const hit = reply.toLowerCase().includes(expected.slice(0, 20)) || expected.includes(reply.toLowerCase().slice(0, 20));\n  state.quoteDrill.lastResult = hit ? 'REMEMBERED' : 'MISSED';\n  state.quoteDrill.lastReply = reply;\n  localStorage.setItem('heymia_quote_drill', JSON.stringify(state.quoteDrill));\n  updateQuoteStatus();\n  if (hit) {\n    positiveReinforce('quote memory');\n    trainerBubble('Trainer', 'PASS — she recalled the quote.\\nMia said: ' + reply);\n    logTrigger('memory_use', 'Quote remembered', reply);\n  } else {\n    trainerBubble('Trainer', 'MISS — train again.\\nExpected: \"' + state.quoteDrill.quote + '\"\\nMia said: ' + (reply || '(empty/fallback)'));\n    logTrigger('fallback_loop', 'Quote missed', reply);\n    state.trainingNotes.unshift({\n      text: 'REPEAT quote until memorized: \"' + state.quoteDrill.quote + '\"',\n      date: new Date().toLocaleString(),\n    });\n    localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n  }\n}\n\n\n// ========== DAILY PERSONALITY VIDEO ==========\nconst MIA_PERSONALITY_VIDEO = {\n  title: 'Mia energy reference (daily)',\n  // User can replace with R2 URL after upload\n  url: localStorage.getItem('heymia_personality_video_url') || '',\n  transcript: [\n    'We have a situation with missing cash.',\n    'Stratton finance has the solution.',\n    'Get Australia to jump on the website now.',\n  ],\n  traits: [\n    'High energy and expressive face — brows, eyes, and hands do the talking',\n    'Direct opener: names the problem fast, no waffle',\n    'Confident sales energy without mumbling',\n    'Points at the viewer — personal, confronting in a friendly way',\n    'Ends with a clear call to action',\n    'Professional look (blazer) + approachable warmth',\n  ],\n  rules: [\n    'RULE: Match this reference energy when in Soft or Build for business: clear problem → solution → call to action',\n    'RULE: You are Mia. This video is personality reference, not a different identity',\n    'KNOW: Daily persona drill — problem, solution, CTA in one short beat',\n  ],\n};\n\nfunction setPersonalityVideoUrl(url) {\n  if (!url) return;\n  localStorage.setItem('heymia_personality_video_url', url);\n  MIA_PERSONALITY_VIDEO.url = url;\n  addMia('Personality reference video saved for daily Trainer use.');\n  renderPersonalityVideo();\n}\n\nfunction renderPersonalityVideo() {\n  const box = document.getElementById('personality-video-box');\n  if (!box) return;\n  const url = MIA_PERSONALITY_VIDEO.url;\n  if (url) {\n    box.innerHTML = `<video src=\"${url}\" class=\"w-full rounded-xl max-h-48 bg-black\" controls playsinline></video>\n      <div class=\"text-[10px] text-slate-400 mt-1\">Daily personality reference — watch once, then train</div>`;\n  } else {\n    box.innerHTML = `<div class=\"text-[10px] text-slate-500\">Upload the Mia reference video to the vault, then Shell: <code class=\"text-pink-400\">persona video KEY</code> or paste URL in Trainer.</div>`;\n  }\n}\n\nfunction installPersonalityFromVideo() {\n  MIA_PERSONALITY_VIDEO.traits.forEach(tr => {\n    state.knowledge.unshift({ text: 'Persona video: ' + tr, date: new Date().toLocaleString() });\n  });\n  MIA_PERSONALITY_VIDEO.rules.forEach(line => {\n    const body = line.replace(/^(RULE:|KNOW:)\\s*/i, '');\n    if (line.toUpperCase().startsWith('RULE')) {\n      state.trainingNotes.unshift({ text: body, date: new Date().toLocaleString() });\n    } else {\n      state.knowledge.unshift({ text: body, date: new Date().toLocaleString() });\n    }\n  });\n  // Quote-style lines from transcript for tomorrow test\n  const line = MIA_PERSONALITY_VIDEO.transcript[0];\n  state.trainingNotes.unshift({\n    text: 'Daily delivery line to remember: \"' + line + '\" — say it with direct confident energy.',\n    date: new Date().toLocaleString(),\n  });\n  state.knowledge = state.knowledge.slice(0, 50);\n  state.trainingNotes = state.trainingNotes.slice(0, 50);\n  localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge));\n  localStorage.setItem('heymia_training', JSON.stringify(state.trainingNotes));\n  if (typeof renderKnowledge === 'function') renderKnowledge();\n  if (typeof renderTraining === 'function') renderTraining();\n  trainerBubble('Trainer', 'Installed persona from daily video:\\n- ' + MIA_PERSONALITY_VIDEO.traits.join('\\n- ') + '\\n\\nTranscript lines locked for drills. Watch the video once today, then chat as Mia with that energy.');\n  addMia('I loaded my daily personality reference: direct, expressive, problem → solution → call to action.');\n}\n\nfunction dailyPersonalityDrill() {\n  switchTool('trainer');\n  renderPersonalityVideo();\n  const lines = MIA_PERSONALITY_VIDEO.transcript;\n  trainerBubble('Trainer', [\n    'DAILY PERSONA DRILL',\n    '',\n    '1) Watch the reference video.',\n    '2) Deliver these three beats in your own words as Mia:',\n    '• Problem: ' + lines[0],\n    '• Solution: ' + lines[1],\n    '• CTA: ' + lines[2],\n    '',\n    '3) Stay Mia (not Jess).',\n    'Press Install persona if not done yet.'\n  ].join('\\n'));\n}\n\n\nfunction jessIntimacyDrill() {\n  setTrainerCompanion('jess');\n  trainerBubble('Trainer', [\n    'JESS INTIMACY DRILL',\n    '',\n    'Practice ladder (owner writes notes; Jess rules get saved):',\n    '1) Flirty open — one line invite',\n    '2) Explicit ask — what she wants to hear',\n    '3) Peak heat — short filthy beat',\n    '4) Soft land — still in character',\n    '',\n    'Also lock: Jess is never Mia. Rooms: Bedroom, Dungeon, Penthouse, Velvet.',\n    'Reply with what to fix; I will emit RULE: and KNOW:.'\n  ].join('\\n'));\n}\n\nfunction buildJessSystemExtras() {\n  const know = (state.jessKnowledge || []).slice(0, 12).map(k => '- ' + k.text).join('\\n');\n  const train = (state.jessTraining || []).slice(0, 8).map(k => '- ' + k.text).join('\\n');\n  return 'Jess knowledge:\\n' + (know || '- (empty)') + '\\nJess training:\\n' + (train || '- (empty)');\n}\n\nfunction escapeHtml(s) {\n  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');\n}\n\n\n/* ========== MIA SUPPORT WIDGET + MEMORY UPLOAD (page-side only) ========== */\nconst HELP_SYSTEM = 'You are Mia Support, the built-in help desk for the HeyMia command center at ' + PUBLIC_DOMAIN + '. Answer questions about using this dashboard: File Vault uploads, categories, Knowledge and memory, Deploy, Shell, Settings, and the Play page. Be short, concrete and practical. If something needs a code change, say exactly what to change.';\nfunction helpContext() {\n  const facts = [\n    'Support context for the HeyMia command center at ' + PUBLIC_DOMAIN + '.',\n    'Facts: files are uploaded from the Upload Files box on /work and stored in Cloudflare R2; categories are assigned automatically from the file name and type and can be changed with Ask Mia to Route; the Knowledge tab has a Memory upload box that accepts .txt .md .json .csv .log up to 200 KB and can save or load memory to the cloud; /play is the companion chat; /work is the command center; the Worker URL is set in Settings.',\n    'Current page state: ' + (state.files ? state.files.length : 0) + ' vault file(s), ' + (state.knowledge ? state.knowledge.length : 0) + ' memory entr(ies).',\n    'Answer only the question below, briefly and practically. No roleplay.'\n  ];\n  return facts.join(' ') + '\\n\\nQuestion: ';\n}\nlet helpHistory = [];\nfunction helpToggle() {\n  const p = document.getElementById('help-panel');\n  if (!p) return;\n  const open = p.style.display === 'flex';\n  p.style.display = open ? 'none' : 'flex';\n  if (!open) {\n    if (!helpHistory.length) helpBubble('mia', 'Hi — what is not working? I can help with uploads, categories, memory, deploys and the Play page.');\n    const i = document.getElementById('help-in');\n    if (i) i.focus();\n  }\n}\nfunction helpKey(e) { if (e.key === 'Enter') { e.preventDefault(); helpSend(); } }\nfunction helpBubble(role, text) {\n  const log = document.getElementById('help-log');\n  if (!log) return null;\n  const d = document.createElement('div');\n  d.style.cssText = role === 'user'\n    ? 'align-self:flex-end;max-width:85%;background:linear-gradient(135deg,#db2777,#7c3aed);padding:8px 10px;border-radius:12px;white-space:pre-wrap'\n    : 'align-self:flex-start;max-width:92%;background:rgba(255,255,255,.07);padding:8px 10px;border-radius:12px;white-space:pre-wrap';\n  d.textContent = text;\n  log.appendChild(d);\n  log.scrollTop = log.scrollHeight;\n  return d;\n}\nasync function helpSend() {\n  const input = document.getElementById('help-in');\n  const text = ((input && input.value) || '').trim();\n  if (!text) return;\n  input.value = '';\n  helpBubble('user', text);\n  helpHistory.push({ role: 'user', content: text });\n  if (helpHistory.length > 20) helpHistory = helpHistory.slice(-20);\n  const pending = helpBubble('mia', 'Thinking…');\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/chat', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ message: helpContext() + text, history: helpHistory, model: 'auto', system: HELP_SYSTEM })\n    });\n    const data = res.ok ? await res.json() : null;\n    const reply = (data && data.reply) || 'Support is offline right now — check the Worker URL in Settings.';\n    if (pending) pending.textContent = reply;\n    helpHistory.push({ role: 'assistant', content: reply });\n  } catch (e) {\n    if (pending) pending.textContent = 'Could not reach the Worker. Check the URL in Settings.';\n  }\n}\n\n\nasync function loadMiaHistory() {\n  try {\n    const local = JSON.parse(localStorage.getItem('heymia_chat') || '[]');\n    if (Array.isArray(local) && local.length) state.miaTurns = local.slice(-80);\n  } catch (e) {}\n  try {\n    const res = await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/history?limit=80');\n    if (res.ok) {\n      const d = await res.json();\n      if (d.turns && d.turns.length) state.miaTurns = d.turns.map(t => ({ role: t.role, content: t.content }));\n    }\n  } catch (e) {}\n  const box = document.getElementById('mia-chat');\n  if (state.miaTurns && state.miaTurns.length && box) {\n    box.innerHTML = '';\n    state.miaTurns.slice(-40).forEach(t => addMia(t.content, t.role === 'user' ? 'user' : 'mia'));\n  } else {\n    addMia(\"I'm here. I keep a year of this chat. What's on your mind?\");\n  }\n}\nfunction persistMiaTurns() {\n  try { localStorage.setItem('heymia_chat', JSON.stringify((state.miaTurns || []).slice(-200))); } catch (e) {}\n  try {\n    fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/history', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ agent: 'Mia', turns: (state.miaTurns || []).slice(-6) }),\n    });\n  } catch (e) {}\n}\nfunction openCut(key, name) {\n  const q = new URLSearchParams();\n  q.set('embed', '1');\n  if (key) q.set('key', key);\n  if (name) q.set('name', name);\n  const frame = document.getElementById('cut-frame');\n  if (frame) frame.src = '/edit.html?' + q.toString();\n  switchTool('cut');\n}\nasync function convertMp4Now(key, name) {\n  if (!key) { addMia('Upload the MP4 to the vault first, then convert.'); return; }\n  addMia('Wrapping “' + name + '” into an HTML page…');\n  try {\n    const res = await fetch((WORKER_BASE || location.origin).replace(/\\/$/, '') + '/api/clip', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ key: key, name: name, title: String(name||'clip').replace(/\\\\.mp4$/i,'') })\n    });\n    const d = await res.json();\n    if (d.ok && d.url) {\n      addMia('Clip is a page: ' + d.url);\n      showDeployResult({ ok: true, name: d.slug || name, url: d.url, at: new Date().toISOString() });\n    } else addMia('Convert failed: ' + (d.error || 'unknown'));\n  } catch (e) { addMia('Convert failed: ' + (e.message || e)); }\n}\n\nconst MEMORY_FILE = 'heymia-memory.json';\nfunction memStatus(msg) { const el = document.getElementById('memory-status'); if (el) el.textContent = msg; }\nasync function importMemoryFiles(files) {\n  const list = Array.from(files || []);\n  if (!list.length) return;\n  let added = 0;\n  for (const f of list) {\n    if (f.size > 200 * 1024) { memStatus('\"' + f.name + '\" is over 200 KB — skipped.'); continue; }\n    let text = '';\n    try { text = await f.text(); } catch (e) { continue; }\n    text = text.trim();\n    if (!text) continue;\n    state.knowledge.unshift({ text: '[' + f.name + '] ' + text, date: new Date().toLocaleString(), source: f.name });\n    added++;\n    try { await uploadMemoryFile(f); } catch (e) {}\n  }\n  localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge));\n  try { renderKnowledge(); } catch (e) {}\n  memStatus(added + ' file(s) added to memory.');\n  try { addMia('Memory updated from ' + added + ' file(s).'); } catch (e) {}\n  const inp = document.getElementById('memory-file'); if (inp) inp.value = '';\n  syncMemoryCloud();\n}\nasync function uploadMemoryFile(f) {\n  if (!WORKER_BASE) return;\n  await fetch(WORKER_BASE.replace(/\\/$/, '') + '/files', { method: 'POST', headers: { 'Content-Type': f.type || 'text/plain', 'X-File-Name': f.name, 'X-Category': 'scripts' }, body: f });\n}\nasync function syncMemoryCloud() {\n  if (!WORKER_BASE) return;\n  try {\n    const payload = JSON.stringify({ knowledge: state.knowledge, saved: new Date().toISOString() });\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/files', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-File-Name': MEMORY_FILE, 'X-Category': 'scripts' }, body: new Blob([payload], { type: 'application/json' }) });\n    memStatus(res.ok ? 'Memory saved to cloud (' + state.knowledge.length + ' entries).' : 'Cloud save failed.');\n  } catch (e) { memStatus('Cloud save failed — Worker unreachable.'); }\n}\nasync function loadMemoryCloud(announce) {\n  if (!WORKER_BASE) return;\n  try {\n    const base = WORKER_BASE.replace(/\\/$/, '');\n    const res = await fetch(base + '/files');\n    if (!res.ok) return;\n    const data = await res.json();\n    const mem = (data.files || []).filter(o => o.key.indexOf(MEMORY_FILE) > -1).sort((a, b) => new Date(b.uploaded) - new Date(a.uploaded))[0];\n    if (!mem) { if (announce) memStatus('No cloud memory saved yet.'); return; }\n    const r2 = await fetch(base + '/files?key=' + encodeURIComponent(mem.key));\n    if (!r2.ok) return;\n    const saved = await r2.json();\n    const cloud = Array.isArray(saved.knowledge) ? saved.knowledge : [];\n    const seen = new Set(state.knowledge.map(k => k.text));\n    let merged = 0;\n    cloud.forEach(k => { if (k && k.text && !seen.has(k.text)) { state.knowledge.push(k); seen.add(k.text); merged++; } });\n    if (merged) { localStorage.setItem('heymia_knowledge', JSON.stringify(state.knowledge)); try { renderKnowledge(); } catch (e) {} }\n    if (announce || merged) memStatus('Cloud memory loaded — ' + merged + ' new, ' + state.knowledge.length + ' total.');\n  } catch (e) { if (announce) memStatus('Could not reach the Worker.'); }\n}\ndocument.addEventListener('DOMContentLoaded', () => { setTimeout(() => { try { loadMemoryCloud(false); } catch (e) {} }, 1200); });\n\n\n/* ========== PUBLISH PANEL + LIVE BUILD BADGE (page-side only) ========== */\nfunction fmtWhen(iso) {\n  if (!iso) return 'never';\n  const d = new Date(iso);\n  return isNaN(d) ? String(iso) : d.toLocaleString();\n}\nfunction updateBuildBadge(st) {\n  const el = document.getElementById('build-badge');\n  if (!el) return;\n  if (st && st.workUploaded) {\n    const d = new Date(st.workUploaded);\n    el.textContent = 'Build ' + d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\n  } else {\n    el.textContent = 'Build: default';\n  }\n}\nasync function refreshBuildBadge() {\n  if (!WORKER_BASE) return;\n  try {\n    const st = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/ui/status')).json();\n    updateBuildBadge(st);\n  } catch (e) {}\n}\nfunction openPublish() {\n  try { switchTool('deploy'); } catch (e) {}\n  try { refreshDeployBoard(); } catch (e) { try { renderPublish(); } catch (err) {} }\n}\nfunction paintDockShip() {\n  const el = document.getElementById('dock-ship');\n  if (!el) return;\n  fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/status').then((r) => r.json()).then((st) => {\n    const last = st.last_deploy || {};\n    el.innerHTML = escapeHtml(st.version || 'worker') +\n      (last.name ? ' · ' + escapeHtml(last.name) : '') +\n      (last.at ? '<br>' + escapeHtml(fmtWhen(last.at)) : '');\n  }).catch(() => { el.textContent = 'Worker offline'; });\n}\nfunction cardHtml(k, v, sub) {\n  return '<div class=\"glass rounded-2xl p-4 border border-white/10 min-w-0\">' +\n    '<div class=\"text-[10px] uppercase tracking-wider text-slate-500\">' + escapeHtml(k) + '</div>' +\n    '<div class=\"text-sm font-bold mt-1 truncate\">' + v + '</div>' +\n    (sub ? '<div class=\"text-[10px] text-slate-400 mt-1\">' + sub + '</div>' : '') +\n    '</div>';\n}\nfunction refreshDeployBoard() {\n  renderDeploy();\n  renderPublish();\n  fillDeployCards();\n}\nasync function fillDeployCards() {\n  const box = document.getElementById('deploy-cards');\n  if (!box) return;\n  box.innerHTML = cardHtml('Worker', '…', 'checking') + cardHtml('Last ship', '…', '') + cardHtml('Vault', '…', '') + cardHtml('AI', '…', '');\n  try {\n    const st = await (await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/status')).json();\n    const last = st.last_deploy || {};\n    const when = last.at ? fmtWhen(last.at) : 'no ship yet';\n    const lastName = escapeHtml(last.name || last.action || 'git');\n    const lastUrl = last.url ? '<a class=\"underline text-pink-300\" href=\"' + last.url + '\" target=\"_blank\" rel=\"noopener\">open</a>' : '';\n    box.innerHTML =\n      cardHtml('Worker', escapeHtml(st.version || '—'), escapeHtml(st.service || 'heymia')) +\n      cardHtml('Last ship', lastName, when + (lastUrl ? ' · ' + lastUrl : '')) +\n      cardHtml('Vault', escapeHtml(st.vault || '—'), st.ok ? 'bound' : 'check binding') +\n      cardHtml('AI', escapeHtml(st.ai_model || '—'),\n        (st.grok === 'set' ? 'Grok on' : 'Grok off') + ' · ' + (st.gemini === 'set' ? 'Gemini on' : 'Gemini off'));\n    updateBuildBadge({ workUploaded: last.at, workActive: true });\n  } catch (e) {\n    box.innerHTML = cardHtml('Worker', 'unreachable', escapeHtml(e.message || 'fetch failed'));\n  }\n}\nasync function renderPublish() {\n  const statusEl = document.getElementById('publish-status');\n  const listEl = document.getElementById('publish-list');\n  if (!statusEl || !listEl) return;\n  const base = WORKER_BASE.replace(/\\/$/, '');\n  statusEl.textContent = 'Checking…';\n  try {\n    const st = await (await fetch(base + '/ui/status')).json();\n    statusEl.innerHTML =\n      '<div class=\"mb-1\">Work page: <span class=\"' + (st.workActive ? 'text-emerald-400' : 'text-slate-400') + '\">' + (st.workActive ? 'your build is live' : 'default build') + '</span> · published ' + fmtWhen(st.workUploaded) + '</div>' +\n      '<div>Play page: <span class=\"' + (st.playActive ? 'text-emerald-400' : 'text-slate-400') + '\">' + (st.playActive ? 'your build is live' : 'default build') + '</span> · published ' + fmtWhen(st.playUploaded) + '</div>';\n    updateBuildBadge(st);\n  } catch (e) {\n    statusEl.textContent = 'Could not reach the Worker — check the URL in Settings.';\n  }\n  try {\n    const data = await (await fetch(base + '/files')).json();\n    const builds = (data.files || [])\n      .filter(o => /\\.html$/i.test(o.key))\n      .sort((a, b) => new Date(b.uploaded) - new Date(a.uploaded))\n      .slice(0, 15);\n    if (!builds.length) {\n      listEl.innerHTML = '<div class=\"text-slate-500\">No .html builds in the vault yet. Upload one in File Vault first.</div>';\n      return;\n    }\n    listEl.innerHTML = builds.map(o => {\n      const nm = o.key.split('/').pop();\n      return '<div class=\"p-3 rounded-xl bg-white/5 flex items-center justify-between gap-3\">' +\n        '<div class=\"min-w-0\"><div class=\"truncate\">' + escapeHtml(nm) + '</div>' +\n        '<div class=\"text-[10px] text-slate-500\">' + fmtWhen(o.uploaded) + ' · ' + Math.round((o.size || 0) / 1024) + ' KB</div></div>' +\n        '<div class=\"flex gap-2 shrink-0\">' +\n        '<button onclick=\"publishBuild(&quot;' + o.key + '&quot;, &quot;work&quot;)\" class=\"px-3 py-1.5 rounded-xl bg-gradient-to-r from-pink-600 to-purple-600 text-[11px] font-bold\">Make live: Work</button>' +\n        '<button onclick=\"publishBuild(&quot;' + o.key + '&quot;, &quot;play&quot;)\" class=\"px-3 py-1.5 rounded-xl glass-light text-[11px] font-bold\">Make live: Play</button>' +\n        '</div></div>';\n    }).join('');\n  } catch (e) {\n    listEl.innerHTML = '<div class=\"text-slate-500\">Could not list builds.</div>';\n  }\n}\nasync function publishBuild(key, target) {\n  const nm = String(key).split('/').pop();\n  if (!confirm('Make \"' + nm + '\" the live ' + target + ' page?')) return;\n  showDeployPending(nm);\n  try {\n    const res = await fetch(WORKER_BASE.replace(/\\/$/, '') + '/api/deploy', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ action: 'activate_ui', key: key, target: target, name: nm })\n    });\n    const rec = await res.json();\n    rec.ok = rec.ok !== false && res.ok;\n    if (!rec.at) rec.at = new Date().toISOString();\n    showDeployResult(rec);\n    const el = document.getElementById('publish-status');\n    if (el) el.innerHTML = rec.ok\n      ? '<span class=\"text-emerald-400 font-bold\">SUCCESS</span> — Published ' + escapeHtml(nm) + ' as ' + target + '. Hard refresh (Ctrl+Shift+R).'\n      : '<span class=\"text-rose-400 font-bold\">FAILED</span> — ' + escapeHtml(rec.error || 'publish failed');\n  } catch (e) {\n    const rec = { ok: false, action: 'activate_ui', name: nm, error: String(e.message || e), at: new Date().toISOString() };\n    showDeployResult(rec);\n    await logDeploy(rec);\n  }\n  setTimeout(renderPublish, 800);\n}\ndocument.addEventListener('DOMContentLoaded', () => {\n  setTimeout(refreshBuildBadge, 600);\n  setTimeout(loadLastDeploy, 700);\n});\n\n\n/* ========== BACKUP / RESTORE POINTS FOR THE LIVE PAGES ========== */\nfunction stampNow() {\n  const d = new Date();\n  const p = n => String(n).length < 2 ? '0' + n : String(n);\n  return d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes());\n}\nasync function backupLivePages() {\n  const el = document.getElementById('backup-status');\n  const base = WORKER_BASE.replace(/\\/$/, '');\n  const stamp = stampNow();\n  const saved = [];\n  if (el) el.textContent = 'Backing up…';\n  for (const page of ['work', 'play']) {\n    try {\n      const res = await fetch('/' + page, { cache: 'no-store' });\n      if (!res.ok) continue;\n      const body = await res.text();\n      const name = 'backup-' + page + '-' + stamp + '.html';\n      const up = await fetch(base + '/files', {\n        method: 'POST',\n        headers: { 'Content-Type': 'text/html', 'X-File-Name': name, 'X-Category': 'code' },\n        body: new Blob([body], { type: 'text/html' })\n      });\n      if (up.ok) saved.push(name + ' (' + Math.round(body.length / 1024) + ' KB)');\n    } catch (e) {}\n  }\n  if (el) el.textContent = saved.length ? 'Saved to vault: ' + saved.join(' · ') : 'Backup failed — check the Worker URL in Settings.';\n  try { addMia('Backup saved: ' + (saved.join(', ') || 'nothing')); } catch (e) {}\n  try { renderPublish(); } catch (e) {}\n  try { loadCloudVault(); } catch (e) {}\n}\nasync function downloadLivePages() {\n  const el = document.getElementById('backup-status');\n  const stamp = stampNow();\n  for (const page of ['work', 'play']) {\n    try {\n      const res = await fetch('/' + page, { cache: 'no-store' });\n      if (!res.ok) continue;\n      const blob = new Blob([await res.text()], { type: 'text/html' });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = 'heymia-' + page + '-' + stamp + '.html';\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n      setTimeout(() => URL.revokeObjectURL(url), 4000);\n    } catch (e) {}\n  }\n  if (el) el.textContent = 'Two files downloaded — keep them, or upload them to Hercules under Files & Media.';\n}\n\nlet _miaVoice = null;\nfunction pickMiaVoice() {\n  const voices = speechSynthesis.getVoices();\n  if (!voices.length) return null;\n  const preferred = ['Samantha','Victoria','Karen','Tessa','Moira','Fiona','Zira','Google UK English Female'];\n  for (const name of preferred) { const v = voices.find(v => v.name === name); if (v) return v; }\n  return voices.find(v => v.lang.startsWith('en') && /female/i.test(v.name)) || voices[0];\n}\nif ('speechSynthesis' in window) { speechSynthesis.onvoiceschanged = () => { _miaVoice = pickMiaVoice(); }; _miaVoice = pickMiaVoice(); }\nfunction speakMia(text) {\n  if (!('speechSynthesis' in window)) return;\n  speechSynthesis.cancel();\n  const u = new SpeechSynthesisUtterance(typeof text === 'string' ? text : text.text);\n  if (_miaVoice) u.voice = _miaVoice;\n  u.rate = 1.0; u.pitch = 1.1;\n  speakMia(u);\n}\n</script>\n\n<!-- MIA SUPPORT WIDGET -->\n<button id=\"help-fab\" onclick=\"helpToggle()\" title=\"Ask Mia Support\" style=\"position:fixed;right:18px;bottom:18px;z-index:9999;width:56px;height:56px;border-radius:9999px;border:1px solid rgba(255,255,255,.18);background:linear-gradient(135deg,#db2777,#7c3aed);color:#fff;font-size:22px;box-shadow:0 10px 30px rgba(0,0,0,.45);cursor:pointer\">🛠</button>\n<div id=\"help-panel\" style=\"display:none;position:fixed;right:18px;bottom:86px;z-index:9999;width:340px;max-width:calc(100vw - 36px);height:440px;max-height:70vh;flex-direction:column;border-radius:18px;overflow:hidden;border:1px solid rgba(255,255,255,.12);background:#0b0b12;box-shadow:0 20px 50px rgba(0,0,0,.6)\">\n  <div style=\"padding:10px 12px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,rgba(219,39,119,.28),rgba(124,58,237,.28));border-bottom:1px solid rgba(255,255,255,.1)\">\n    <div style=\"font-size:12px;font-weight:700;color:#fff\">Mia Support</div>\n    <button onclick=\"helpToggle()\" style=\"background:none;border:0;color:#94a3b8;font-size:14px;cursor:pointer\">✕</button>\n  </div>\n  <div id=\"help-log\" style=\"flex:1;overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px;font-size:12px;color:#e2e8f0\"></div>\n  <div style=\"display:flex;gap:6px;padding:10px;border-top:1px solid rgba(255,255,255,.1)\">\n    <input id=\"help-in\" onkeydown=\"helpKey(event)\" placeholder=\"Describe the issue...\" style=\"flex:1;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:12px;padding:8px 10px;font-size:12px;color:#fff;outline:none\">\n    <button onclick=\"helpSend()\" style=\"padding:8px 12px;border-radius:12px;border:0;background:linear-gradient(135deg,#db2777,#7c3aed);color:#fff;font-size:11px;font-weight:700;cursor:pointer\">Send</button>\n  </div>\n</div>\n</body>\n</html>";
